      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠨᠢᠭᠤᠴᠠ ᠲᠣᠪᠴᠢᠶᠠᠨ᠂ ᠠᠶᠠᠯᠠᠯ ᠤᠨ ᠲᠡᠮᠳᠡᠭᠯᠡᠯ ᠪᠠ ᠪᠤᠰᠤᠳ ᠲᠡᠦᠬᠡᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠤᠨ ᠤᠩᠰᠢᠵᠤ ᠪᠣᠯᠣᠨ᠎ᠠ᠃ ᠵᠣᠬᠢᠶᠠᠭᠴᠢ᠂ ᠣᠷᠴᠢᠭᠤᠯᠤᠭᠴᠢ ᠪᠠ ᠬᠡᠪᠯᠡᠯ ᠢ ᠨᠢ ᠱᠠᠯᠭᠠᠬᠤ ᠨᠢ ᠴᠢᠬᠤᠯᠠ᠃',
        'ᠷᠢᠴᠦᠮᠧᠶᠢᠺᠠᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ ᠶᠢᠨ ᠴᠠᠬᠢᠮ ᠡᠬᠡ ᠳᠦ ᠠᠯᠲᠠᠨ ᠲᠣᠪᠴᠢ ᠪᠠ ᠠᠰᠠᠷᠠᠭᠴᠢ ᠨᠡᠷᠡᠲᠦ ᠶᠢᠨ ᠲᠡᠦᠬᠡ ᠪᠤᠢ᠃ ᠡᠬᠡ ᠶᠢ ᠨᠡᠭᠡᠭᠡᠵᠦ ᠮᠣᠩᠭᠣᠯ ᠪᠢᠴᠢᠭ ᠢᠶᠠᠷ ᠤᠩᠰᠢᠵᠤ ᠪᠣᠯᠣᠨ᠎ᠠ᠃',
      ],
