      category: 'sources',
      title: 'ᠰᠤᠷᠪᠤᠯᠵᠢ ᠶᠢ ᠰᠤᠳᠤᠯᠬᠤ',
      summary: 'ᠬᠡᠨ᠂ ᠬᠡᠵᠢᠶ᠎ᠡ᠂ ᠬᠡᠨ ᠳᠦ ᠵᠣᠷᠢᠭᠤᠯᠵᠤ ᠪᠢᠴᠢᠭᠰᠡᠨ ᠪᠡ ᠭᠡᠵᠦ ᠠᠰᠠᠭᠤᠶ᠎ᠠ᠃',
      body: [
        'ᠰᠤᠷᠪᠤᠯᠵᠢ ᠶᠢ ᠤᠩᠰᠢᠬᠤ ᠳᠠᠭᠠᠨ ᠵᠣᠬᠢᠶᠠᠭᠴᠢ᠂ ᠵᠣᠷᠢᠯᠭ᠎ᠠ ᠪᠠ ᠤᠩᠰᠢᠭᠴᠢ ᠶᠢ ᠨᠢ ᠠᠩᠬᠠᠷᠤᠨ᠎ᠠ᠃ ᠪᠢᠴᠢᠭᠰᠡᠨ ᠴᠠᠭ ᠨᠢ ᠥᠭᠦᠯᠡᠭᠰᠡᠨ ᠦᠢᠯᠡ ᠶᠠᠪᠤᠳᠠᠯ ᠤᠨ ᠴᠠᠭ ᠠᠴᠠ ᠵᠥᠷᠢᠵᠦ ᠪᠣᠯᠣᠨ᠎ᠠ᠃',
        'ᠲᠤᠬᠠᠶᠢᠨ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠣᠷᠴᠢᠨ ᠪᠠᠶᠢᠳᠠᠯ ᠢ ᠰᠤᠳᠤᠯᠵᠤ᠂ ᠪᠤᠰᠤᠳ ᠮᠠᠲ᠋ᠧᠷᠢᠶᠠᠯ ᠲᠠᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠤᠨ᠎ᠠ᠃ ᠢᠨᠭᠡᠵᠦ ᠪᠠᠷᠢᠮᠲᠠ ᠪᠠ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠶᠢ ᠶᠠᠯᠭᠠᠨ ᠣᠶᠢᠯᠠᠭᠠᠨ᠎ᠠ᠃',
      ],
