      summary: 'ᠮᠣᠷᠢᠨ ᠬᠤᠭᠤᠷ ᠨᠢ ᠬᠣᠶᠠᠷ ᠴᠢᠪᠬᠠᠳᠠᠰᠤᠲᠤ᠂ ᠨᠤᠮᠤ ᠪᠠᠷ ᠲᠠᠲᠠᠵᠤ ᠬᠥᠭᠵᠢᠮᠳᠡᠳᠡᠭ ᠬᠥᠭᠵᠢᠮ ᠶᠤᠮ᠃',
      body: [
        'ᠮᠣᠷᠢᠨ ᠬᠤᠭᠤᠷ ᠤᠨ ᠢᠰᠢᠨ ᠦ ᠦᠵᠦᠭᠦᠷ ᠲᠦ ᠮᠣᠷᠢᠨ ᠤ ᠲᠣᠯᠣᠭᠠᠢ ᠰᠡᠶᠢᠯᠳᠡᠭ᠃ ᠨᠤᠮᠤ ᠪᠠᠷ ᠬᠣᠶᠠᠷ ᠴᠢᠪᠬᠠᠳᠠᠰᠤ ᠶᠢ ᠬᠥᠪᠴᠢᠯᠡᠨ ᠳᠠᠭᠤ ᠭᠠᠷᠭᠠᠳᠠᠭ᠃',
        'ᠮᠣᠷᠢᠨ ᠬᠤᠭᠤᠷ ᠢ ᠭᠣᠴᠣᠯᠠᠨ ᠲᠣᠭᠯᠠᠬᠤ ᠠᠴᠠ ᠭᠠᠳᠠᠨ᠎ᠠ ᠤᠷᠲᠤ ᠶᠢᠨ ᠳᠠᠭᠤ᠂ ᠪᠦᠵᠢᠭ ᠪᠠ ᠵᠠᠩ ᠦᠢᠯᠡ ᠶᠢ ᠳᠠᠭᠠᠯᠳᠤᠭᠤᠯᠤᠨ ᠬᠥᠭᠵᠢᠮᠳᠡᠳᠡᠭ᠃ ᠪᠠᠭᠰᠢ ᠠᠴᠠ ᠱᠠᠪᠢ ᠳᠤ ᠠᠮᠠ ᠪᠠᠷ ᠵᠠᠭᠠᠨ ᠤᠯᠠᠮᠵᠢᠯᠠᠭᠤᠯᠵᠤ ᠢᠷᠡᠵᠡᠢ᠃',
      ],
