      summary:
        'ᠳᠡᠪᠡᠯ ᠦᠨ ᠬᠡᠯᠪᠡᠷᠢ ᠪᠠ ᠴᠢᠮᠡᠭᠯᠡᠯ ᠨᠢ ᠤᠯᠠᠷᠢᠯ᠂ ᠬᠡᠷᠡᠭᠴᠡᠭᠡ ᠪᠠ ᠨᠤᠲᠤᠭ ᠠᠴᠠ ᠱᠠᠯᠲᠠᠭᠠᠯᠠᠨ ᠶᠠᠯᠭᠠᠭᠠᠲᠠᠢ᠃',
