        'ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠨᠢᠭᠤᠴᠠ ᠲᠣᠪᠴᠢᠶᠠᠨ ᠳᠤ ᠡᠨᠡ ᠠᠭᠤᠯᠠ ᠶᠢ ᠴᠢᠩᠭᠢᠰ ᠬᠠᠭᠠᠨ ᠤ ᠠᠮᠢᠳᠤᠷᠠᠯ ᠤᠨ ᠦᠢᠯᠡ ᠶᠠᠪᠤᠳᠠᠯ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠨ ᠥᠭᠦᠯᠡᠳᠡᠭ᠃ ᠡᠨᠡᠬᠦ ᠥᠪ ᠢ ᠬᠠᠮᠠᠭᠠᠯᠠᠬᠤ ᠳᠤ ᠪᠠᠶᠢᠭᠠᠯᠢ ᠪᠠ ᠰᠣᠶᠣᠯ ᠤᠨ ᠤᠯᠠᠮᠵᠢᠯᠠᠯ ᠢ ᠬᠠᠮᠲᠤ ᠠᠩᠬᠠᠷᠤᠨ᠎ᠠ᠃',
