          nameMn: 'ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠦᠨᠳᠦᠰᠦᠨ ᠦ ᠲᠥᠪ',
