      summary: 'ᠬᠠᠷ᠎ᠠ ᠬᠣᠷᠤᠮ ᠤᠨ ᠵᠠᠮ ᠪᠠ ᠪᠠᠷᠢᠯᠭ᠎ᠠ ᠶᠢᠨ ᠮᠥᠷ ᠨᠢ ᠬᠡᠷᠡᠮ ᠦᠨ ᠭᠠᠳᠠᠨ᠎ᠠ ᠴᠤ ᠦᠷᠭᠦᠯᠵᠢᠯᠡᠳᠡᠭ᠃',
      body: [
        '᠒᠐᠑᠖ ᠪᠠ ᠒᠐᠑᠗ ᠣᠨ ᠳᠤ ᠰᠤᠳᠤᠯᠤᠭᠴᠢᠳ ᠬᠠᠷ᠎ᠠ ᠬᠣᠷᠤᠮ ᠳᠤ ᠰᠣᠷᠢᠨᠵᠢᠨ ᠣᠷᠣᠨ ᠪᠠ ᠭᠠᠵᠠᠷ ᠤᠨ ᠭᠠᠳᠠᠷᠭᠤ ᠶᠢ ᠬᠡᠮᠵᠢᠵᠡᠢ᠃ ᠡᠨᠡ ᠠᠷᠭ᠎ᠠ ᠪᠠᠷ ᠬᠡᠷᠡᠮ ᠦᠨ ᠳᠣᠲᠣᠷ᠎ᠠ ᠪᠠ ᠭᠠᠳᠠᠨ᠎ᠠ ᠳᠠᠬᠢ ᠡᠷᠲᠡᠨ ᠦ ᠵᠠᠮ᠂ ᠪᠠᠷᠢᠯᠭ᠎ᠠ ᠶᠢᠨ ᠮᠥᠷ ᠢ ᠰᠤᠳᠤᠯᠵᠠᠢ᠃',
        'ᠵᠡᠭᠦᠨ ᠬᠠᠭᠠᠯᠭ᠎ᠠ ᠠᠴᠠ ᠭᠠᠷᠤᠭᠰᠠᠨ ᠨᠢᠭᠡ ᠵᠠᠮ ᠢ ᠣᠶᠢᠷ᠎ᠠ ᠪᠠᠷ ᠭᠤᠷᠪᠠᠨ ᠺᠢᠯᠣᠮᠧᠲ᠋ᠷ ᠬᠦᠷᠲᠡᠯ᠎ᠡ ᠳᠠᠭᠠᠵᠤ ᠲᠣᠭᠲᠠᠭᠠᠵᠠᠢ᠃ ᠲᠡᠷᠡ ᠵᠠᠮ ᠤᠨ ᠣᠯᠠᠨ ᠬᠡᠰᠡᠭ ᠲᠦ ᠬᠣᠶᠠᠷ ᠲᠠᠯ᠎ᠠ ᠪᠠᠷ ᠨᠢ ᠪᠠᠷᠢᠯᠭ᠎ᠠ ᠵᠡᠷᠭᠡᠯᠡᠨ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠮᠥᠷ ᠪᠤᠢ᠃',
        'ᠰᠤᠳᠤᠯᠭ᠎ᠠ ᠳᠤ ᠬᠡᠷᠡᠮ ᠳᠦ ᠬᠦᠷᠢᠶᠡᠯᠡᠭᠳᠡᠭᠰᠡᠨ ᠲᠠᠯᠠᠪᠤᠷᠢ ᠶᠢᠨ ᠵᠠᠭᠤᠨ ᠤ ᠵᠢᠷᠠᠨ ᠬᠤᠪᠢ ᠳᠤ ᠪᠠᠷᠢᠯᠭ᠎ᠠ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠭᠡᠵᠦ ᠲᠣᠭᠠᠴᠠᠭᠠᠯᠵᠠᠢ᠃ ᠬᠡᠷᠡᠮ ᠦᠨ ᠭᠠᠳᠠᠨ᠎ᠠ ᠳᠠᠬᠢ ᠰᠠᠭᠤᠷᠢᠰᠢᠯ ᠤᠨ ᠮᠥᠷ ᠲᠡᠢ ᠬᠠᠮᠲᠤ ᠦᠵᠡᠪᠡᠯ᠂ ᠬᠣᠲᠠ ᠶᠢᠨ ᠬᠢᠯᠢ ᠶᠢ ᠭᠠᠭᠴᠠ ᠬᠡᠷᠡᠮ ᠢᠶᠡᠷ ᠲᠣᠭᠲᠠᠭᠠᠵᠤ ᠪᠣᠯᠬᠤ ᠦᠭᠡᠢ᠃',
      ],
