      title: 'ᠱᠠᠭᠠᠢ ᠶᠢᠨ ᠭᠡᠷ ᠦᠨ ᠨᠠᠭᠠᠳᠤᠮ',
      summary: 'ᠱᠠᠭᠠᠢ ᠪᠠᠷ ᠮᠣᠷᠢ ᠤᠷᠤᠯᠳᠤᠭᠤᠯᠬᠤ᠂ ᠨᠶᠠᠰᠯᠠᠬᠤ ᠪᠠ ᠠᠯᠠᠭ ᠮᠡᠯᠡᠬᠡᠢ ᠥᠷᠦᠬᠦ ᠵᠡᠷᠭᠡ ᠣᠯᠠᠨ ᠨᠠᠭᠠᠳᠤᠮ ᠪᠤᠢ᠃',
      body: [
        'ᠱᠠᠭᠠᠢ ᠶᠢᠨ ᠳᠥᠷᠪᠡᠨ ᠲᠠᠯ᠎ᠠ ᠶᠢ ᠮᠣᠷᠢ᠂ ᠲᠡᠮᠡᠭᠡ᠂ ᠬᠣᠨᠢ ᠪᠠ ᠢᠮᠠᠭ᠎ᠠ ᠭᠡᠵᠦ ᠨᠡᠷᠡᠯᠡᠨ᠎ᠡ᠃ ᠮᠣᠷᠢ ᠤᠷᠤᠯᠳᠤᠭᠤᠯᠬᠤ ᠳᠤ ᠱᠠᠭᠠᠢ ᠪᠠᠷ ᠵᠠᠮ ᠥᠷᠦᠵᠦ᠂ ᠳᠥᠷᠪᠡᠨ ᠱᠠᠭᠠᠢ ᠣᠷᠬᠢᠨ᠎ᠠ᠃ ᠮᠣᠷᠢ ᠪᠤᠭᠤᠭᠰᠠᠨ ᠲᠣᠭ᠎ᠠ ᠪᠠᠷ ᠮᠣᠷᠢ ᠪᠠᠨ ᠤᠷᠤᠭᠰᠢᠯᠠᠭᠤᠯᠵᠤ᠂ ᠪᠠᠷᠢᠶ᠎ᠠ ᠳᠤ ᠲᠦᠷᠦᠭᠦᠯᠡᠨ ᠬᠦᠷᠦᠭᠰᠡᠨ ᠨᠢ ᠲᠦᠷᠦᠭᠦᠯᠡᠳᠡᠭ᠃',
        'ᠱᠠᠭᠠᠢ ᠨᠶᠠᠰᠯᠠᠬᠤ ᠳᠤ ᠠᠳᠠᠯᠢ ᠲᠠᠯ᠎ᠠ ᠪᠠᠷ ᠪᠤᠭᠤᠭᠰᠠᠨ ᠱᠠᠭᠠᠢ ᠶᠢ ᠬᠣᠣᠷᠣᠨᠳᠤ ᠨᠢ ᠣᠨᠣᠭᠤᠯᠨ᠎ᠠ᠃ ᠵᠥᠪ ᠣᠨᠣᠪᠠᠯ ᠨᠢᠭᠡ ᠶᠢ ᠨᠢ ᠠᠪᠴᠤ ᠦᠷᠭᠦᠯᠵᠢᠯᠡᠭᠦᠯᠦᠨ᠎ᠡ᠃ ᠠᠯᠳᠠᠬᠤ ᠪᠤᠶᠤ ᠪᠤᠰᠤᠳ ᠱᠠᠭᠠᠢ ᠶᠢ ᠬᠥᠳᠡᠯᠭᠡᠪᠡᠯ ᠡᠭᠡᠯᠵᠢ ᠪᠡᠨ ᠳᠠᠷᠠᠭ᠎ᠠ ᠶᠢᠨ ᠬᠦᠮᠦᠨ ᠳᠦ ᠰᠢᠯᠵᠢᠭᠦᠯᠦᠨ᠎ᠡ᠃',
        'ᠠᠯᠠᠭ ᠮᠡᠯᠡᠬᠡᠢ ᠶᠢ ᠱᠠᠭᠠᠢ ᠪᠠᠷ ᠪᠡᠶ᠎ᠡ ᠪᠠ ᠮᠥᠴᠢ ᠶᠢᠨ ᠳᠦᠷᠰᠦ ᠲᠡᠢ ᠥᠷᠦᠨ᠎ᠡ᠃ ᠡᠨᠡ ᠨᠣᠮ ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠙᠒ ᠱᠠᠭᠠᠢ ᠲᠠᠢ᠂ ᠴᠠᠭᠠᠨ ᠰᠠᠷ᠎ᠠ ᠶᠢᠨ ᠦᠶ᠎ᠡ ᠳᠦ ᠑᠐᠘ ᠱᠠᠭᠠᠢ ᠲᠠᠢ ᠬᠤᠪᠢᠯᠪᠤᠷᠢ ᠶᠢ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠵᠡᠢ᠃ ᠡᠳᠡᠭᠡᠷ ᠲᠣᠭ᠎ᠠ ᠨᠢ ᠪᠦᠬᠦ ᠨᠤᠲᠤᠭ ᠤᠨ ᠨᠢᠭᠡᠳᠦᠮᠡᠯ ᠳᠦᠷᠢᠮ ᠪᠢᠰᠢ᠃',
      ],
