      title: 'ᠨᠤᠮᠤ ᠬᠢᠬᠦ ᠤᠷ᠎ᠠ',
      summary: 'ᠤᠯᠠᠮᠵᠢᠯᠠᠯᠲᠤ ᠨᠤᠮᠤ ᠬᠢᠬᠦ ᠳᠦ ᠮᠣᠳᠣ᠂ ᠡᠪᠡᠷ ᠪᠠ ᠰᠢᠷᠪᠦᠰᠦ ᠶᠢ ᠬᠣᠰᠯᠠᠭᠤᠯᠳᠠᠭ᠃',
      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠨᠤᠮᠤ ᠬᠢᠬᠦ ᠤᠷ᠎ᠠ ᠶᠢᠨ ᠲᠤᠬᠠᠢ ᠒᠐᠑᠗ ᠣᠨ ᠤ ᠪᠠᠷᠢᠮᠲᠠᠲᠤ ᠺᠢᠨᠣ᠋ ᠶᠢᠨ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠭ᠎ᠠ ᠳᠤ ᠣᠯᠠᠨ ᠡᠳ ᠢ ᠬᠣᠰᠯᠠᠭᠤᠯᠬᠤ ᠠᠷᠭ᠎ᠠ ᠶᠢ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠡᠢ᠃ ᠳᠤᠮᠳᠠ ᠬᠡᠰᠡᠭ ᠲᠦ ᠬᠤᠯᠤᠰᠤ ᠪᠤᠶᠤ ᠬᠤᠰᠤ ᠮᠣᠳᠣ᠂ ᠠᠷᠤ ᠲᠠᠯ᠎ᠠ ᠳᠤ ᠰᠢᠷᠪᠦᠰᠦ᠂ ᠳᠣᠲᠣᠷ ᠲᠠᠯ᠎ᠠ ᠳᠤ ᠡᠪᠡᠷ ᠬᠡᠷᠡᠭᠯᠡᠳᠡᠭ᠃',
        'ᠲᠡᠷᠡ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠭ᠎ᠠ ᠬᠠᠯᠬ᠎ᠠ᠂ ᠪᠤᠷᠢᠶᠠᠳ᠂ ᠤᠷᠢᠶᠠᠩᠬᠠᠢ ᠪᠠ ᠮᠣᠷᠢᠨ ᠬᠠᠷᠪᠤᠯᠲᠠ ᠵᠡᠷᠭᠡ ᠶᠠᠯᠭᠠᠭᠠᠲᠠᠢ ᠬᠡᠯᠪᠡᠷᠢ ᠶᠢ ᠳᠤᠷᠠᠳᠴᠠᠢ᠃ ᠡᠨᠡ ᠨᠢ ᠨᠤᠮᠤ ᠰᠤᠮᠤ ᠨᠤ ᠤᠷ᠎ᠠ ᠪᠠ ᠬᠠᠷᠪᠤᠯᠲᠠ ᠶᠢᠨ ᠤᠯᠠᠮᠵᠢᠯᠠᠯ ᠢ ᠬᠠᠮᠲᠤ ᠰᠤᠳᠤᠯᠬᠤ ᠬᠡᠷᠡᠭᠲᠡᠢ ᠶᠢ ᠬᠠᠷᠠᠭᠤᠯᠤᠨ᠎ᠠ᠃',
        'ᠦᠨᠳᠡᠰᠦᠨ ᠦ ᠥᠪ ᠦᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠤᠷᠠᠴᠤ ᠵᠠᠮᠪᠠ ᠶᠢᠨ ᠰᠦᠬᠡᠪᠠᠭᠠᠲᠤᠷ ᠡᠴᠢᠭᠡ ᠡᠴᠡ ᠪᠡᠨ ᠨᠤᠮᠤ ᠰᠤᠮᠤ ᠬᠢᠬᠦ ᠶᠢ ᠰᠤᠷᠤᠭᠰᠠᠨ ᠢ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠲᠡᠷᠡ ᠑᠙᠔᠐ ᠣᠨ ᠳᠤ ᠳᠣᠷᠣᠨᠣᠳᠤ ᠠᠶᠢᠮᠠᠭ ᠤᠨ ᠬᠠᠯᠬ᠎ᠠ ᠭᠣᠣᠯ ᠰᠤᠮᠤᠨ ᠳᠤ ᠲᠥᠷᠥᠭᠰᠡᠨ᠃ ᠡᠨᠡ ᠵᠢᠱᠢᠶ᠎ᠡ ᠨᠢ ᠭᠠᠷ ᠤᠷᠠᠯᠠᠯ ᠢ ᠭᠡᠷ ᠪᠦᠯᠢ ᠳᠦ ᠳᠠᠮᠵᠢᠭᠤᠯᠬᠤ ᠨᠢᠭᠡ ᠠᠷᠭ᠎ᠠ ᠶᠢ ᠬᠠᠷᠠᠭᠤᠯᠤᠨ᠎ᠠ᠃',
      ],
