      title: 'ᠶᠢᠰᠦᠨ ᠡᠷᠳᠡᠨᠢ ᠶᠢᠨ ᠭᠠᠨᠵᠤᠷ',
      summary:
        'ᠡᠨᠡ ᠭᠠᠨᠵᠤᠷ ᠨᠢ ᠨᠣᠮ ᠪᠦᠲᠦᠭᠡᠬᠦ ᠤᠷ᠎ᠠ ᠪᠠ ᠪᠤᠷᠬᠠᠨ ᠤ ᠱᠠᠰᠢᠨ ᠤ ᠡᠷᠳᠡᠮ ᠦᠨ ᠥᠪ ᠢ ᠬᠠᠮᠲᠤ ᠬᠠᠳᠠᠭᠠᠯᠳᠠᠭ᠃',
      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠦᠨᠳᠦᠰᠦᠨ ᠦ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ ᠳᠤ ᠶᠢᠰᠦᠨ ᠡᠷᠳᠡᠨᠢ ᠪᠡᠷ ᠪᠢᠴᠢᠭᠰᠡᠨ ᠭᠠᠨᠵᠤᠷ ᠬᠠᠳᠠᠭᠠᠯᠠᠭᠳᠠᠵᠤ ᠪᠠᠶᠢᠨ᠎ᠠ᠃ ᠡᠨᠡ ᠨᠢ ᠡᠷᠳᠡᠨᠢᠲᠦ ᠮᠠᠲ᠋ᠧᠷᠢᠶᠠᠯ ᠠᠰᠢᠭᠯᠠᠨ ᠨᠣᠮ ᠪᠦᠲᠦᠭᠡᠳᠡᠭ ᠤᠯᠠᠮᠵᠢᠯᠠᠯ ᠤᠨ ᠣᠨᠴᠠᠭᠠᠢ ᠵᠢᠱᠢᠶ᠎ᠡ ᠶᠤᠮ᠃',
        'ᠶᠦᠨᠧᠰᠺᠣ ᠶᠢᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠳᠤ ᠭᠦᠨ ᠤᠬᠠᠭᠠᠨ᠂ ᠡᠮᠨᠡᠯᠭᠡ᠂ ᠬᠡᠯᠡ ᠪᠠ ᠢᠷᠠᠭᠤ ᠨᠠᠶᠢᠷᠠᠭ ᠵᠡᠷᠭᠡ ᠣᠯᠠᠨ ᠡᠷᠳᠡᠮ ᠦᠨ ᠠᠭᠤᠯᠭ᠎ᠠ ᠲᠠᠢ ᠭᠡᠵᠦ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠨᠣᠮ ᠤᠨ ᠵᠢᠷᠤᠭ ᠲᠤ ᠪᠤᠷᠬᠠᠳ᠂ ᠬᠥᠮᠦᠰ ᠪᠠ ᠠᠮᠢᠲᠠᠳ ᠢ ᠣᠯᠠᠨ ᠥᠩᠭᠡ ᠪᠡᠷ ᠳᠦᠷᠰᠦᠯᠡᠭᠰᠡᠨ ᠪᠤᠢ᠃',
        'ᠡᠨᠡ ᠴᠤᠭᠯᠠᠷᠠᠯ ᠒᠐᠑᠓ ᠣᠨ ᠳᠤ ᠳᠡᠯᠡᠬᠡᠢ ᠶᠢᠨ ᠳᠤᠷᠠᠰᠬᠠᠯ ᠤᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠣᠷᠣᠵᠠᠢ᠃ ᠡᠨᠳᠡ ᠨᠡᠷᠡᠯᠡᠭᠰᠡᠨ ᠣᠨ ᠪᠣᠯ ᠪᠦᠷᠢᠳᠬᠡᠰᠡᠨ ᠣᠨ ᠪᠣᠯᠬᠤ ᠠᠴᠠ ᠨᠣᠮ ᠢ ᠪᠢᠴᠢᠭᠰᠡᠨ ᠣᠨ ᠪᠢᠰᠢ᠃',
      ],
