      summary: 'ᠱᠠᠩᠳᠤ ᠶᠢᠨ ᠲᠥᠯᠥᠪᠯᠡᠯᠲᠡ ᠳᠦ ᠣᠷᠳᠣᠨ᠂ ᠬᠡᠷᠡᠮ ᠪᠠ ᠨᠡᠭᠦᠳᠡᠯᠴᠢᠳ ᠦᠨ ᠪᠤᠭᠤᠳᠠᠯ ᠬᠣᠰᠣᠯᠵᠠᠢ᠃',
