      body: [
        'ᠮᠧᠲ᠋ᠷᠣᠫᠣᠯᠢᠲ᠋ᠧᠨ ᠦ ᠮᠦᠽᠧᠢ ᠳᠦ ᠤᠷᠲᠤ ᠰᠡᠭᠦᠯ ᠲᠡᠢ ᠭᠠᠯᠲᠤ ᠱᠢᠪᠠᠭᠤᠨ ᠤ ᠳᠦᠷᠰᠦ ᠲᠡᠢ ᠴᠢᠮᠡᠭᠯᠡᠯ ᠦᠨ ᠬᠠᠪᠲᠠᠰᠤ ᠪᠤᠢ᠃ ᠮᠦᠽᠧᠢ ᠲᠡᠭᠦᠨ ᠢ ᠠᠷᠪᠠᠨ ᠭᠤᠷᠪᠠᠳᠤᠭᠠᠷ ᠵᠠᠭᠤᠨ ᠤ ᠰᠡᠭᠦᠯᠴᠢ ᠳᠦ ᠢᠷᠠᠨ ᠳᠤ ᠬᠢᠭᠰᠡᠨ ᠭᠡᠵᠦ ᠪᠦᠷᠢᠳᠬᠡᠵᠡᠢ᠃',
        'ᠮᠦᠽᠧᠢ ᠶᠢᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠳᠤ᠂ ᠢᠯ ᠬᠠᠨ ᠤ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠢᠷᠠᠨ ᠤ ᠤᠷᠠᠴᠤᠳ ᠬᠢᠲᠠᠳ ᠤᠨ ᠭᠠᠯᠲᠤ ᠱᠢᠪᠠᠭᠤ᠂ ᠯᠤᠤ ᠪᠠ ᠯᠢᠩᠬᠤ᠎ᠠ ᠶᠢᠨ ᠳᠦᠷᠰᠦ ᠶᠢ ᠠᠪᠴᠤ ᠬᠡᠷᠡᠭᠯᠡᠵᠡᠢ᠃ ᠭᠡᠪᠡᠴᠦ ᠲᠡᠳᠡ ᠳᠦᠷᠰᠦ ᠶᠢ ᠥᠪᠡᠷ ᠦᠨ ᠤᠷᠠᠯᠢᠭ ᠤᠨ ᠤᠯᠠᠮᠵᠢᠯᠠᠯ ᠲᠠᠢ ᠬᠣᠰᠣᠯᠤᠯᠠᠨ ᠥᠭᠡᠷᠴᠢᠯᠡᠵᠡᠢ᠃',
      ],
