      category: 'language',
      title: 'ᠲᠠᠪᠤᠨ ᠬᠡᠯᠡᠨ ᠦ ᠲᠣᠯᠢ',
      summary:
        'ᠲᠠᠪᠤᠨ ᠬᠡᠯᠡ ᠶᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠤᠭᠰᠠᠨ ᠲᠣᠯᠢ ᠳᠤ ᠮᠣᠩᠭᠣᠯ ᠦᠭᠡ ᠨᠢ ᠣᠯᠠᠨ ᠬᠡᠯᠡᠲᠦ ᠡᠷᠳᠡᠮ ᠦᠨ ᠣᠷᠴᠢᠨ ᠳᠤ ᠪᠠᠶᠢᠷᠢᠯᠠᠨ᠎ᠠ᠃',
      body: [
        'ᠴᠢᠩ ᠤᠯᠤᠰ ᠤᠨ ᠲᠡᠩᠭᠡᠷᠢ ᠶᠢᠨ ᠲᠡᠳᠬᠦᠭᠰᠡᠨ ᠦ ᠦᠶᠡᠳᠦ ᠡᠮᠬᠢᠳᠬᠡᠭᠰᠡᠨ ᠲᠠᠪᠤᠨ ᠬᠡᠯᠡᠨ ᠦ ᠲᠣᠯᠢ ᠨᠢ ᠮᠠᠨᠵᠤ᠂ ᠲᠥᠪᠡᠳ᠂ ᠮᠣᠩᠭᠣᠯ᠂ ᠴᠠᠭᠠᠳᠠᠢ ᠲᠦᠷᠦᠭ ᠪᠠ ᠬᠢᠲᠠᠳ ᠬᠡᠯᠡ ᠶᠢ ᠵᠡᠷᠭᠡᠴᠡᠭᠦᠯᠵᠡᠢ᠃ ᠪᠷᠢᠲᠠᠨᠢ ᠶᠢᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ ᠤᠨ ᠭᠠᠷᠴᠠᠭ ᠲᠤ ᠮᠣᠩᠭᠣᠯ ᠦᠭᠡ ᠶᠢ ᠮᠣᠩᠭᠣᠯ ᠪᠢᠴᠢᠭ ᠢᠶᠡᠷ ᠪᠢᠴᠢᠭᠰᠡᠨ ᠢ ᠲᠣᠳᠣᠷᠬᠠᠶᠢᠯᠠᠵᠠᠢ᠃',
        'ᠨᠡᠶᠢᠲᠡᠯᠡᠭᠰᠡᠨ ᠵᠢᠱᠢᠶ᠎ᠡ ᠬᠠᠭᠤᠳᠠᠰᠤᠨ ᠳᠤ «ᠲᠡᠩᠭᠡᠷᠢ» ᠭᠡᠰᠡᠨ ᠤᠳᠬ᠎ᠠ ᠶᠢ ᠲᠠᠪᠤᠨ ᠬᠡᠯᠡ ᠪᠡᠷ ᠬᠠᠷᠠᠭᠤᠯᠵᠠᠢ᠃ ᠡᠨᠡ ᠲᠣᠯᠢ ᠶᠢ ᠤᠩᠰᠢᠬᠤ ᠳᠤ ᠦᠭᠡ ᠶᠢᠨ ᠣᠷᠴᠢᠭᠤᠯᠭ᠎ᠠ ᠪᠠ ᠳᠠᠭᠤᠳᠠᠯᠭ᠎ᠠ ᠶᠢ ᠲᠡᠮᠳᠡᠭᠯᠡᠭᠰᠡᠨ ᠪᠢᠴᠢᠯᠭᠡ ᠶᠢ ᠶᠠᠯᠭᠠᠨ ᠦᠵᠡᠬᠦ ᠬᠡᠷᠡᠭᠲᠡᠢ᠃',
      ],
