      category: 'history',
      title: 'ᠪᠠᠯᠳᠠᠨ ᠪᠷᠠᠶᠢᠪᠦᠩ ᠬᠡᠶᠢᠳ',
      summary:
        'ᠪᠠᠯᠳᠠᠨ ᠪᠷᠠᠶᠢᠪᠦᠩ ᠬᠡᠶᠢᠳ ᠳᠦ ᠰᠦᠮ᠎ᠡ᠂ ᠬᠠᠳᠠᠨ ᠰᠡᠶᠢᠯᠦᠮᠡᠯ ᠪᠠ ᠮᠥᠷᠭᠥᠯ ᠦᠨ ᠵᠠᠮ ᠨᠢᠭᠡᠨ ᠣᠷᠴᠢᠨ ᠢ ᠪᠦᠷᠢᠳᠦᠭᠦᠯᠦᠨ᠎ᠡ᠃',
      body: [
        'ᠬᠡᠶᠢᠳ ᠨᠢ ᠬᠡᠨᠲᠡᠢ ᠠᠶᠢᠮᠠᠭ ᠤᠨ ᠪᠠᠷᠠᠭᠤᠨ ᠵᠢᠷᠭᠠᠯᠠᠩᠲᠤ ᠭᠣᠣᠯ ᠤᠨ ᠬᠥᠨᠳᠡᠢ ᠳᠦ᠂ ᠮᠥᠩᠬᠡ ᠥᠯᠵᠡᠶᠢᠲᠦ ᠠᠭᠤᠯᠠ ᠶᠢᠨ ᠡᠪᠡᠷ ᠲᠦ ᠪᠠᠶᠢᠨ᠎ᠠ᠃ ᠭᠣᠣᠯ ᠴᠣᠭᠴᠢᠨ ᠳᠤᠭᠠᠩ ᠢ ᠑᠘᠑᠓ ᠣᠨ ᠳᠤ ᠪᠠᠷᠢᠵᠠᠢ᠃',
        'ᠮᠥᠷᠭᠥᠯ ᠦᠨ ᠵᠠᠮ ᠤᠨ ᠳᠠᠭᠠᠭᠤ ᠪᠤᠷᠬᠠᠨ ᠤ ᠳᠦᠷᠰᠦ᠂ ᠲᠠᠷᠨᠢ ᠪᠠ ᠰᠣᠶᠣᠮᠪᠣ ᠶᠢᠨ ᠰᠡᠶᠢᠯᠦᠮᠡᠯ ᠪᠤᠢ᠃ ᠬᠡᠶᠢᠳ ᠑᠙᠓᠐ ᠣᠨ ᠤ ᠦᠶ᠎ᠡ ᠳᠦ ᠶᠡᠬᠡ ᠪᠡᠷ ᠡᠪᠳᠡᠷᠡᠭᠰᠡᠨ ᠪᠣᠯᠪᠠᠴᠤ᠂ ᠑᠙᠙᠐ ᠣᠨ ᠠᠴᠠ ᠬᠣᠶᠢᠰᠢ ᠰᠦᠮ᠎ᠡ ᠶᠢ ᠰᠡᠷᠭᠦᠭᠡᠨ ᠵᠠᠰᠠᠬᠤ ᠪᠠ ᠵᠠᠩ ᠦᠢᠯᠡ ᠶᠢ ᠳᠠᠬᠢᠨ ᠶᠠᠪᠤᠭᠤᠯᠬᠤ ᠠᠵᠢᠯ ᠡᠬᠢᠯᠡᠵᠡᠢ᠃',
      ],
