      summary:
        'ᠬᠡᠷᠦᠯᠡᠨ ᠦ ᠬᠥᠳᠡᠭᠡ ᠠᠷᠠᠯ ᠳᠠᠬᠢ ᠠᠪᠠᠷᠭ᠎ᠠ ᠶᠢᠨ ᠲᠤᠭᠤᠷᠢ ᠨᠢ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠡᠵᠡᠨᠲᠦ ᠭᠦᠷᠦᠨ ᠦ ᠡᠬᠢᠨ ᠦᠶ᠎ᠡ ᠶᠢ ᠰᠤᠳᠤᠯᠬᠤ ᠭᠠᠵᠠᠷ ᠶᠤᠮ᠃',
      body: [
        'ᠬᠥᠳᠡᠭᠡ ᠠᠷᠠᠯ ᠨᠢ ᠬᠡᠨᠲᠡᠢ ᠠᠶᠢᠮᠠᠭ ᠤᠨ ᠳᠡᠯᠭᠡᠷ ᠬᠠᠨ ᠰᠤᠮᠤᠨ ᠳᠤ᠂ ᠬᠡᠷᠦᠯᠡᠨ ᠪᠠ ᠴᠡᠩᠬᠡᠷ ᠭᠣᠣᠯ ᠤᠨ ᠵᠠᠭᠤᠷ᠎ᠠ ᠪᠠᠶᠢᠨ᠎ᠠ᠃ ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠥᠪ ᠦᠨ ᠮᠡᠳᠡᠭᠦᠯᠭᠡ ᠳᠦ ᠠᠪᠠᠷᠭ᠎ᠠ ᠶᠢᠨ ᠲᠤᠭᠤᠷᠢ ᠶᠢ ᠴᠢᠩᠭᠢᠰ ᠬᠠᠭᠠᠨ ᠤ ᠶᠡᠬᠡ ᠠᠭᠤᠷᠤᠭ ᠣᠷᠳᠤ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠵᠤ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃',
        'ᠮᠠᠯᠲᠠᠯᠲᠠ ᠪᠠᠷ ᠣᠷᠳᠤᠨ ᠤ ᠪᠠᠷᠢᠯᠭ᠎ᠠ᠂ ᠳᠠᠷᠬᠠᠨ ᠤ ᠭᠠᠵᠠᠷ᠂ ᠤᠰᠤᠨ ᠤ ᠰᠠᠩ ᠪᠠ ᠵᠠᠮ ᠤᠨ ᠮᠥᠷ ᠢ ᠢᠯᠡᠷᠡᠭᠦᠯᠵᠡᠢ᠃ ᠱᠠᠪᠠᠷ ᠰᠠᠪᠠ᠂ ᠴᠢᠯᠠᠭᠤᠨ ᠪᠠ ᠲᠥᠮᠦᠷ ᠪᠠᠭᠠᠵᠢ᠂ ᠠᠮᠢᠲᠠᠨ ᠤ ᠶᠠᠰᠤ ᠶᠢ ᠪᠢᠴᠢᠭ ᠦᠨ ᠰᠤᠷᠪᠤᠯᠵᠢ ᠲᠠᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠬᠤ ᠨᠢ ᠡᠨᠡ ᠰᠠᠭᠤᠷᠢᠨ ᠤ ᠲᠡᠦᠬᠡ ᠶᠢ ᠲᠣᠳᠣᠷᠬᠠᠶᠢᠯᠠᠬᠤ ᠳᠤ ᠴᠢᠬᠤᠯᠠ᠃',
      ],
