          organization: 'ᠳᠤᠮᠳᠠᠳᠤ ᠤᠯᠤᠰ ᠤᠨ ᠪᠤᠰᠤ ᠪᠣᠳᠠᠰ ᠤᠨ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠣᠣᠴᠢᠮ ᠮᠦᠽᠧᠢ',
