      summary: 'ᠤᠲᠠᠰᠤᠨ ᠤ ᠵᠦᠢᠯ᠂ ᠥᠩᠭᠡ ᠪᠠ ᠣᠶᠣᠳᠠᠯ ᠤᠨ ᠠᠷᠭ᠎ᠠ ᠨᠢ ᠬᠠᠲᠤᠭᠠᠮᠠᠯ ᠤᠨ ᠳᠦᠷᠰᠦ ᠶᠢ ᠪᠦᠲᠦᠭᠡᠳᠡᠭ᠃',
      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠵᠡᠭᠦᠦ ᠤᠲᠠᠰᠤᠨ ᠤ ᠤᠷ᠎ᠠ ᠳᠤ ᠨᠣᠣᠰᠤᠨ ᠪᠠ ᠲᠣᠷᠭᠣᠨ ᠤᠲᠠᠰᠤ᠂ ᠪᠠᠰᠠ ᠰᠢᠷᠪᠦᠰᠦ ᠵᠡᠷᠭᠡ ᠡᠳ ᠬᠡᠷᠡᠭᠯᠡᠵᠦ ᠢᠷᠡᠵᠡᠢ᠃ ᠤᠲᠠᠰᠤ ᠪᠠᠨ ᠡᠷᠴᠢᠯᠡᠬᠦ᠂ ᠰᠦᠯᠵᠢᠬᠦ ᠪᠠ ᠥᠩᠭᠡ ᠬᠣᠰᠯᠠᠭᠤᠯᠬᠤ ᠨᠢ ᠣᠶᠣᠬᠤ ᠠᠴᠠ ᠥᠮᠦᠨᠡᠬᠢ ᠪᠡᠯᠡᠳᠬᠡᠯ ᠶᠤᠮ᠃',
        'ᠬᠣᠨᠢᠨ ᠬᠣᠯᠪᠣᠭ᠎ᠠ ᠬᠡᠮᠡᠬᠦ ᠣᠶᠣᠳᠠᠯ ᠨᠢ ᠨᠢᠭᠡ ᠭᠣᠭᠠᠴᠢᠭ᠎ᠠ ᠶᠢ ᠳᠠᠷᠠᠭ᠎ᠠ ᠶᠢᠨ ᠭᠣᠭᠠᠴᠢᠭ᠎ᠠ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠵᠤ ᠭᠢᠨᠵᠢ ᠮᠡᠲᠦ ᠳᠦᠷᠰᠦ ᠭᠠᠷᠭᠠᠳᠠᠭ᠃ ᠡᠨᠡ ᠨᠡᠷ᠎ᠡ ᠶᠢ ᠬᠣᠨᠢ ᠬᠣᠯᠪᠣᠬᠤ ᠵᠠᠩᠭᠢᠯᠭ᠎ᠠ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠭᠠᠲᠠᠢ ᠭᠡᠵᠦ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠳᠠᠭ᠃ ᠬᠤᠪᠴᠠᠰᠤᠨ ᠤ ᠵᠠᠬ᠎ᠠ᠂ ᠭᠤᠲᠤᠯ ᠪᠠ ᠤᠭᠤᠲᠠ ᠶᠢ ᠴᠢᠮᠡᠭᠯᠡᠬᠦ ᠳᠦ ᠬᠡᠷᠡᠭᠯᠡᠳᠡᠭ᠃',
        'ᠬᠣᠰ ᠤᠲᠠᠰᠤᠨ ᠤ ᠬᠠᠲᠤᠭᠠᠮᠠᠯ ᠳᠤ ᠤᠲᠠᠰᠤ ᠣᠷᠢᠶᠠᠬᠤ ᠴᠢᠭᠯᠡᠯ᠂ ᠨᠢᠭᠡᠨ ᠵᠢᠭᠳᠡ ᠵᠠᠶᠢ ᠪᠠ ᠥᠩᠭᠡᠨ ᠦ ᠤᠶᠠᠯᠳᠤᠭ᠎ᠠ ᠴᠢᠬᠤᠯᠠ᠃',
      ],
