        'ᠤᠷ᠎ᠠ ᠮᠡᠳᠡᠯᠭᠡ ᠶᠢ ᠪᠠᠭᠰᠢ ᠠᠴᠠ ᠱᠠᠪᠢ ᠳᠤ ᠳᠠᠮᠵᠢᠭᠤᠯᠳᠠᠭ᠃ ᠱᠠᠪᠢ ᠨᠢ ᠤᠷᠢᠳᠠᠬᠢ ᠠᠷᠭ᠎ᠠ ᠶᠢ ᠡᠵᠡᠮᠰᠢᠭᠡᠳ᠂ ᠥᠪᠡᠷ ᠦᠨ ᠬᠡᠪ ᠮᠠᠶᠢᠭ ᠢ ᠬᠥᠭᠵᠢᠭᠦᠯᠳᠡᠭ ᠭᠡᠵᠦ ᠡᠬᠡ ᠮᠠᠲ᠋ᠧᠷᠢᠶᠠᠯ ᠳᠤ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃',
