        'ᠥᠯᠵᠡᠢ ᠶᠢᠨ ᠬᠡᠭᠡ ᠨᠢ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠴᠢᠮᠡᠭᠯᠡᠬᠦ ᠤᠷᠠᠯᠢᠭ ᠲᠤ ᠥᠷᠭᠡᠨ ᠬᠡᠷᠡᠭᠯᠡᠭᠳᠡᠳᠡᠭ ᠭᠧᠣᠮᠧᠲ᠋ᠷ ᠦᠨ ᠬᠡᠭᠡ ᠶᠤᠮ᠃ ᠣᠭᠣᠰᠣᠷ ᠪᠠ ᠵᠠᠩᠭᠢᠯᠭ᠎ᠠ ᠳᠤ ᠴᠤ ᠲᠡᠭᠦᠨ ᠦ ᠬᠤᠪᠢᠯᠪᠤᠷᠢ ᠶᠢ ᠬᠡᠷᠡᠭᠯᠡᠳᠡᠭ᠃',
