          nameMn: 'ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠲᠡᠦᠬᠡ ᠶᠢᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠲᠣᠯᠢ',
