      summary: 'ᠰᠤᠳᠤᠷ ᠪᠢᠴᠢᠭ ᠦᠨ ᠬᠦᠷᠢᠶᠡᠯᠡᠩ ᠪᠣᠯ ᠬᠣᠷᠢᠳᠤᠭᠠᠷ ᠵᠠᠭᠤᠨ ᠤ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠰᠤᠳᠤᠯᠭᠠᠨ ᠤ ᠲᠥᠪ ᠪᠠᠶᠢᠵᠠᠢ᠃',
      body: [
        'ᠰᠤᠳᠤᠷ ᠪᠢᠴᠢᠭ ᠦᠨ ᠬᠦᠷᠢᠶᠡᠯᠡᠩ ᠢ ᠑᠙᠒᠑ ᠣᠨ ᠳᠤ ᠪᠠᠶᠢᠭᠤᠯᠵᠠᠢ᠃ ᠑᠙᠒᠙ ᠣᠨ ᠳᠤ ᠲᠡᠭᠦᠨ ᠳᠦ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ᠂ ᠮᠦᠽᠧᠢ᠂ ᠭᠠᠵᠠᠷ ᠤᠨ ᠵᠢᠷᠤᠭ᠂ ᠭᠡᠷᠡᠯ ᠵᠢᠷᠤᠭ᠂ ᠲᠡᠦᠬᠡ ᠪᠠ ᠳᠠᠩᠰᠠ ᠡᠪᠬᠡᠮᠡᠯ ᠦᠨ ᠲᠠᠰᠤᠭ ᠵᠡᠷᠭᠡ ᠣᠯᠠᠨ ᠰᠠᠯᠪᠤᠷᠢ ᠪᠤᠢ ᠪᠣᠯᠵᠠᠢ᠃',
        'ᠲᠤᠰ ᠬᠦᠷᠢᠶᠡᠯᠡᠩ ᠱᠢᠨ᠎ᠡ ᠨᠡᠷ᠎ᠡ ᠲᠣᠮᠢᠶ᠎ᠠ ᠶᠢ ᠮᠣᠩᠭᠣᠯ ᠬᠡᠯᠡᠨ ᠳᠦ ᠣᠨᠣᠪᠴᠢᠲᠠᠢ ᠪᠠᠭᠤᠯᠭᠠᠬᠤ ᠺᠣᠮᠢᠰ ᠪᠠᠶᠢᠭᠤᠯᠵᠠᠢ᠃ ᠑᠙᠓᠐ ᠣᠨ ᠳᠤ ᠲᠡᠷᠡ ᠰᠢᠨᠵᠢᠯᠡᠬᠦ ᠤᠬᠠᠭᠠᠨ ᠤ ᠬᠦᠷᠢᠶᠡᠯᠡᠩ ᠪᠣᠯᠣᠨ ᠥᠷᠭᠡᠵᠢᠵᠡᠢ᠃',
      ],
