          title: 'ᠮᠠᠨᠵᠤᠰᠢᠷᠢ ᠬᠡᠶᠢᠳ ᠦᠨ ᠲᠤᠭᠤᠷᠢ',
          organization: 'ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠦᠨᠳᠦᠰᠦᠨ ᠦ ᠲᠥᠪ',
          nameMn: 'ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠦᠨᠳᠦᠰᠦᠨ ᠦ ᠲᠥᠪ',
