      summary:
        'ᠴᠣᠭᠤᠷ ᠤᠨ ᠳᠠᠭᠤ ᠳᠤ ᠥᠨᠳᠥᠷ ᠠᠶᠠᠯᠭᠤ ᠪᠠ ᠦᠷᠭᠦᠯᠵᠢᠯᠡᠭᠰᠡᠨ ᠨᠠᠮ ᠠᠪᠢᠶ᠎ᠠ ᠶᠢ ᠣᠯᠠᠨ ᠳᠠᠭᠤᠴᠢᠨ ᠬᠣᠰᠣᠯᠠᠭᠤᠯᠤᠨ ᠳᠠᠭᠤᠯᠠᠳᠠᠭ᠃',
      body: [
        'ᠴᠣᠭᠤᠷ ᠤᠨ ᠳᠠᠭᠤ ᠨᠢ ᠰᠢᠯᠢᠨᠬᠣᠲᠠ ᠪᠠ ᠠᠪᠠᠭ᠎ᠠ ᠵᠡᠷᠭᠡ ᠰᠢᠯᠢᠨ ᠭᠣᠣᠯ ᠤᠨ ᠨᠤᠲᠤᠭ ᠲᠤ ᠤᠯᠠᠮᠵᠢᠯᠠᠭᠳᠠᠭᠰᠠᠨ ᠬᠠᠮᠲᠤ ᠳᠠᠭᠤᠯᠠᠬᠤ ᠠᠷᠭ᠎ᠠ ᠶᠤᠮ᠃ ᠨᠢᠭᠡ ᠳᠠᠭᠤᠴᠢᠨ ᠤᠷᠲᠤ ᠶᠢᠨ ᠳᠠᠭᠤ ᠶᠢᠨ ᠥᠨᠳᠥᠷ ᠠᠶᠠᠯᠭᠤ ᠶᠢ ᠳᠠᠭᠤᠯᠠᠬᠤ ᠳᠤ᠂ ᠪᠤᠰᠤᠳ ᠬᠡᠳᠦᠨ ᠳᠠᠭᠤᠴᠢᠨ ᠨᠠᠮ ᠠᠪᠢᠶ᠎ᠠ ᠪᠠᠷ ᠲᠡᠭᠦᠨ ᠢ ᠳᠡᠪᠢᠰᠬᠡᠷᠯᠡᠨ᠎ᠡ᠃',
        'ᠨᠠᠮ ᠠᠪᠢᠶᠠᠨ ᠤ ᠬᠡᠰᠡᠭ ᠨᠢ ᠭᠣᠤᠯ ᠠᠶᠠᠯᠭᠤ ᠲᠠᠢ ᠬᠠᠮᠲᠤ ᠦᠷᠭᠦᠯᠵᠢᠯᠡᠳᠡᠭ᠃ ᠪᠣᠭᠣᠨᠢ ᠦᠭᠡ ᠶᠢ ᠤᠷᠲᠤ ᠠᠶᠠᠯᠭᠤ ᠲᠠᠢ ᠨᠡᠶᠢᠯᠡᠭᠦᠯᠵᠦ᠂ ᠬᠡᠮᠨᠡᠯ ᠢ ᠴᠢᠯᠥᠭᠡᠲᠡᠢ ᠨᠤᠭᠤᠯᠠᠳᠠᠭ᠃ ᠡᠨᠡ ᠨᠢ ᠨᠢᠭᠡ ᠬᠦᠮᠦᠨ ᠦ ᠬᠥᠭᠡᠮᠡᠢ ᠪᠤᠰᠤ᠂ ᠣᠯᠠᠨ ᠬᠦᠮᠦᠨ ᠦ ᠠᠪᠢᠶᠠᠨ ᠤ ᠬᠠᠮᠰᠠᠯ ᠶᠤᠮ᠃',
        'ᠠᠪᠠᠭ᠎ᠠ ᠶᠢᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠨᠢ ᠴᠣᠭᠤᠷ ᠤᠨ ᠳᠠᠭᠤ ᠶᠢ ᠲᠠᠬᠢᠯᠭ᠎ᠠ᠂ ᠶᠣᠰᠣᠯᠠᠯ ᠪᠠ ᠶᠡᠬᠡ ᠴᠤᠭᠯᠠᠷᠠᠯ ᠲᠤ ᠳᠠᠭᠤᠯᠠᠵᠤ᠂ ᠬᠤᠪᠴᠠᠰᠤ ᠪᠠ ᠳᠠᠭᠤᠨ ᠤ ᠳᠡᠰ ᠳᠠᠷᠠᠭ᠎ᠠ ᠳᠤ ᠲᠤᠰᠬᠠᠢ ᠶᠣᠰᠣ ᠪᠤᠢ ᠶᠢ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠶᠣᠰᠣ ᠶᠢ ᠪᠦᠬᠦ ᠳᠠᠭᠤᠴᠢᠳ ᠲᠤ ᠠᠳᠠᠯᠢ ᠭᠡᠵᠦ ᠦᠵᠡᠬᠦ ᠦᠭᠡᠢ᠃',
      ],
