      summary: 'ᠨᠣᠣᠰᠤ ᠶᠢ ᠵᠤᠯᠬᠠᠵᠤ᠂ ᠨᠣᠷᠭᠠᠵᠤ ᠥᠩᠬᠥᠷᠢᠭᠦᠯᠬᠦ ᠳᠦ ᠠᠶᠢᠯ ᠤᠳ ᠬᠠᠮᠲᠤᠷᠠᠨ ᠠᠵᠢᠯᠯᠠᠳᠠᠭ᠃',
      body: [
        'ᠡᠰᠡᠭᠡᠢ ᠬᠢᠬᠦ ᠳᠦ ᠬᠣᠨᠢᠨ ᠤ ᠨᠣᠣᠰᠤ ᠶᠢ ᠪᠡᠯᠡᠳᠬᠡᠵᠦ᠂ ᠬᠠᠭᠤᠴᠢᠨ ᠡᠰᠡᠭᠡᠢ ᠳᠡᠭᠡᠷ᠎ᠡ ᠵᠤᠯᠬᠠᠳᠠᠭ᠃ ᠡᠨᠡ ᠰᠠᠭᠤᠷᠢ ᠶᠢ ᠡᠬᠡ ᠡᠰᠡᠭᠡᠢ ᠭᠡᠳᠡᠭ᠃ ᠨᠣᠣᠰᠤ ᠶᠢ ᠤᠰᠤᠯᠠᠵᠤ᠂ ᠮᠣᠳᠣᠨ ᠭᠣᠣᠯ ᠳᠤ ᠣᠷᠢᠶᠠᠨ ᠪᠠᠭᠯᠠᠵᠤ ᠥᠩᠬᠥᠷᠢᠭᠦᠯᠡᠭᠡᠳ ᠳᠠᠪᠬᠤᠷᠭ᠎ᠠ ᠶᠢ ᠨᠢ ᠨᠢᠭᠲᠠᠷᠠᠭᠤᠯᠨ᠎ᠠ᠃',
        'ᠳᠠᠷᠠᠭ᠎ᠠ ᠨᠢ ᠡᠰᠡᠭᠡᠢ ᠶᠢ ᠵᠠᠳᠠᠯᠵᠤ᠂ ᠲᠡᠭᠰᠢᠯᠡᠵᠦ᠂ ᠳᠡᠯᠭᠡᠨ ᠬᠠᠲᠠᠭᠠᠨ᠎ᠠ᠃ ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠥᠪ ᠡᠨᠡ ᠠᠵᠢᠯ ᠢ ᠠᠶᠢᠯ ᠬᠥᠷᠱᠢ ᠪᠡᠷ ᠢᠶᠡᠨ ᠲᠤᠰᠠᠯᠠᠯᠴᠠᠵᠤ᠂ ᠠᠷᠭ᠎ᠠ ᠲᠤᠷᠰᠢᠯᠭ᠎ᠠ ᠪᠠᠨ ᠰᠣᠯᠢᠯᠴᠠᠬᠤ ᠬᠠᠮᠲᠤ ᠶᠢᠨ ᠦᠢᠯᠡ ᠭᠡᠵᠦ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠵᠠᠢ᠃',
      ],
