      summary: 'ᠨᠣᠣᠰᠤ ᠬᠠᠶᠢᠴᠢᠯᠠᠬᠤ ᠪᠠ ᠰᠠᠪᠠᠬᠤ ᠨᠢ ᠬᠥᠷᠱᠢ ᠠᠶᠢᠯ ᠤᠳ ᠤᠨ ᠲᠤᠰᠠᠯᠠᠯᠴᠠᠬᠤ ᠠᠵᠢᠯ ᠪᠠᠶᠢᠵᠠᠢ᠃',
      body: [
        'ᠡᠬᠡ ᠮᠠᠲ᠋ᠧᠷᠢᠶᠠᠯ ᠳᠤ ᠵᠤᠨ ᠤ ᠨᠣᠣᠰᠤ ᠶᠢ ᠤᠷᠲᠤ ᠨᠣᠣᠰᠤ᠂ ᠨᠠᠮᠤᠷ ᠤᠨ ᠢ ᠠᠬᠠᠷ ᠨᠣᠣᠰᠤ ᠭᠡᠵᠦ ᠶᠠᠯᠭᠠᠨ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠬᠠᠶᠢᠴᠢᠯᠠᠬᠤ ᠡᠳᠦᠷ ᠢ ᠤᠷᠢᠳᠴᠢᠯᠠᠨ ᠮᠡᠳᠡᠭᠳᠡᠵᠦ᠂ ᠲᠥᠷᠥᠯ ᠰᠠᠳᠤᠨ ᠪᠠ ᠬᠥᠷᠱᠢ ᠠᠶᠢᠯ ᠤᠳ ᠠᠶᠢᠯ ᠪᠦᠷᠢ ᠳᠦ ᠡᠭᠡᠯᠵᠢᠯᠡᠨ ᠲᠤᠰᠠᠯᠠᠳᠠᠭ᠃',
        'ᠨᠣᠣᠰᠤ ᠰᠠᠪᠠᠬᠤ ᠠᠴᠠ ᠥᠮᠦᠨ᠎ᠡ ᠨᠣᠣᠰᠤ ᠶᠢ ᠳᠡᠯᠭᠡᠨ ᠬᠠᠲᠠᠭᠠᠵᠤ᠂ ᠰᠠᠪᠠᠭ᠎ᠠ ᠪᠡᠯᠡᠳᠬᠡᠨ᠎ᠡ᠃ ᠬᠦᠮᠦᠰ ᠲᠣᠭᠣᠷᠢᠭ ᠪᠣᠯᠣᠨ ᠰᠠᠭᠤᠵᠤ ᠬᠠᠮᠲᠤ ᠰᠠᠪᠠᠳᠠᠭ᠃ ᠡᠵᠡᠨ ᠠᠶᠢᠯ ᠲᠤᠰᠠᠯᠠᠭᠴᠢᠳ ᠢ ᠴᠠᠢ ᠢᠳᠡᠭᠡ ᠪᠡᠷ ᠳᠠᠶᠢᠯᠠᠵᠤ᠂ ᠠᠵᠢᠯ ᠳᠠᠭᠤᠰᠤᠭᠠᠳ ᠥᠭᠡᠷ᠎ᠡ ᠠᠶᠢᠯ ᠳᠤ ᠲᠤᠰᠠᠯᠠᠬᠤ ᠡᠭᠡᠯᠵᠢ ᠢᠷᠡᠨ᠎ᠡ᠃',
      ],
