      summary: 'ᠮᠤᠺᠠᠳᠳᠢᠮᠠᠲ ᠠᠯ ᠠᠳᠠᠪ ᠤᠨ ᠵᠠᠷᠢᠮ ᠡᠬᠡ ᠳᠦ ᠮᠣᠩᠭᠣᠯ ᠦᠭᠡ ᠶᠢ ᠠᠷᠠᠪ ᠦᠰᠦᠭ ᠢᠶᠡᠷ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃',
      body: [
        '«ᠮᠤᠺᠠᠳᠳᠢᠮᠠᠲ ᠠᠯ ᠠᠳᠠᠪ» ᠭᠡᠳᠡᠭ ᠠᠷᠠᠪ ᠬᠡᠯᠡᠨ ᠦ ᠲᠣᠯᠢ ᠶᠢᠨ ᠣᠯᠠᠨ ᠬᠤᠭᠤᠯᠪᠤᠷᠢ ᠳᠤ ᠥᠭᠡᠷ᠎ᠡ ᠬᠡᠯᠡᠨ ᠦ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠨᠡᠮᠡᠵᠡᠢ᠃ ᠲᠡᠳᠡᠭᠡᠷ ᠲᠦ ᠫᠧᠷᠰ᠂ ᠲᠦᠷᠦᠭ ᠪᠠ ᠮᠣᠩᠭᠣᠯ ᠬᠡᠯᠡᠨ ᠦ ᠮᠠᠲ᠋ᠧᠷᠢᠶᠠᠯ ᠪᠤᠢ᠃ ᠪᠦᠬᠦ ᠬᠤᠭᠤᠯᠪᠤᠷᠢ ᠠᠳᠠᠯᠢ ᠬᠡᠯᠡᠨ ᠦ ᠠᠭᠤᠯᠭ᠎ᠠ ᠲᠠᠢ ᠪᠢᠰᠢ᠃',
        'ᠶᠣᠰᠢᠶᠣ ᠰᠠᠢᠲᠣ ᠮᠣᠩᠭᠣᠯ ᠦᠭᠡ ᠶᠢᠨ ᠳᠣᠲᠣᠷ᠎ᠠ ᠠᠷᠠᠪ ᠦᠰᠦᠭ ᠦᠨ ᠠᠳᠠᠭ ᠤᠨ ᠳᠦᠷᠰᠦ ᠣᠷᠣᠭᠰᠠᠨ ᠲᠣᠬᠢᠶᠠᠯ ᠤᠳ ᠢ ᠰᠤᠳᠤᠯᠵᠠᠢ᠃ ᠡᠨᠡ ᠰᠠᠯᠭᠠᠵᠤ ᠪᠢᠴᠢᠭᠰᠡᠨ ᠪᠠᠶᠢᠳᠠᠯ ᠢ ᠦᠭᠡ ᠶᠢᠨ ᠪᠦᠲᠦᠴᠡ ᠲᠡᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠤᠨ ᠦᠵᠡᠵᠡᠢ᠃ ᠭᠡᠬᠦ ᠳᠡᠭᠡᠨ ᠵᠠᠷᠢᠮ ᠠᠯᠳᠠᠭ᠎ᠠ ᠬᠣᠵᠢᠮ ᠬᠤᠭᠤᠯᠵᠤ ᠪᠢᠴᠢᠬᠦ ᠳᠦ ᠭᠠᠷᠤᠭᠰᠠᠨ ᠪᠠᠶᠢᠵᠤ ᠪᠣᠯᠣᠨ᠎ᠠ ᠭᠡᠵᠦ ᠠᠩᠬᠠᠷᠠᠭᠤᠯᠵᠠᠢ᠃',
      ],
