      summary: 'ᠡᠨᠡ ᠬᠢᠲᠠᠳ ᠮᠣᠩᠭᠣᠯ ᠲᠣᠯᠢ ᠦᠭᠡ ᠪᠠ ᠠᠯᠪᠠᠨ ᠪᠢᠴᠢᠭ ᠦᠨ ᠵᠢᠱᠢᠶ᠎ᠡ ᠶᠢ ᠬᠠᠮᠲᠤ ᠠᠭᠤᠯᠵᠠᠢ᠃',
      body: [
        'ᠮᠢᠩ ᠤᠯᠤᠰ ᠤᠨ ᠡᠬᠢᠨ ᠦᠶ᠎ᠡ ᠶᠢᠨ «ᠬᠤᠸᠠ ᠢ ᠢ ᠶᠦᠢ» ᠨᠢ ᠰᠡᠳᠦᠪ ᠢᠶᠡᠷ ᠠᠩᠭᠢᠯᠠᠭᠰᠠᠨ ᠬᠢᠲᠠᠳ ᠮᠣᠩᠭᠣᠯ ᠦᠭᠡᠰ ᠪᠠ ᠠᠷᠪᠠᠨ ᠬᠣᠶᠠᠷ ᠮᠣᠩᠭᠣᠯ ᠪᠢᠴᠢᠭ ᠦᠨ ᠪᠠᠷᠢᠮᠲᠠ ᠲᠠᠢ᠃ ᠰᠤᠳᠤᠯᠤᠭᠴᠢ ᠺᠠᠷᠯᠠ ᠨᠠᠫᠫᠢ ᠑᠓᠘᠘ ᠣᠨ ᠳᠤ ᠡᠮᠬᠢᠳᠬᠡᠵᠦ ᠳᠠᠭᠤᠰᠤᠭᠠᠳ᠂ ᠑᠓᠘᠙ ᠣᠨ ᠳᠤ ᠬᠡᠪᠯᠡᠭᠰᠡᠨ ᠢ ᠶᠠᠯᠭᠠᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃',
        'ᠮᠣᠩᠭᠣᠯ ᠬᠡᠯᠡᠨ ᠦ ᠠᠪᠢᠶ᠎ᠠ ᠶᠢ ᠬᠢᠲᠠᠳ ᠦᠰᠦᠭ ᠢᠶᠡᠷ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠦ᠂ ᠦᠭᠡ ᠶᠢᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠪᠠ ᠪᠦᠬᠦ ᠪᠢᠴᠢᠭ ᠦᠨ ᠣᠷᠴᠢᠭᠤᠯᠭ᠎ᠠ ᠶᠢ ᠣᠯᠠᠨ ᠬᠡᠯᠪᠡᠷᠢ ᠪᠡᠷ ᠬᠠᠳᠠᠭᠠᠯᠵᠡᠢ᠃ ᠢᠶᠢᠮᠦ ᠡᠴᠡ ᠬᠢᠲᠠᠳ ᠦᠰᠦᠭ ᠦᠨ ᠠᠪᠢᠶ᠎ᠠ ᠲᠡᠮᠳᠡᠭᠯᠡᠭᠰᠡᠨ ᠦᠢᠯᠡᠳᠦᠯ ᠪᠠ ᠤᠳᠬ᠎ᠠ ᠣᠷᠴᠢᠭᠤᠯᠤᠭᠰᠠᠨ ᠦᠢᠯᠡᠳᠦᠯ ᠢ ᠢᠯᠭᠠᠨ ᠤᠩᠰᠢᠨ᠎ᠠ᠃',
      ],
