        'ᠵᠢᠷᠤᠭ ᠪᠢᠴᠢᠭ ᠳᠡᠭᠡᠷᠡᠬᠢ ᠲᠠᠮᠠᠭ᠎ᠠ ᠪᠠ ᠲᠡᠮᠳᠡᠭᠯᠡᠯ ᠨᠢ ᠣᠷᠳᠣᠨ ᠤ ᠴᠤᠭᠯᠠᠭᠤᠯᠭ᠎ᠠ ᠶᠢᠨ ᠲᠡᠦᠬᠡ ᠶᠢ ᠮᠡᠳᠡᠭᠦᠯᠳᠡᠭ᠃',
      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠭᠦᠩᠵᠦ ᠰᠡᠩᠭᠡ ᠷᠠᠭᠢ ᠵᠢᠷᠤᠭ ᠪᠠ ᠤᠷᠠᠨ ᠪᠢᠴᠢᠯᠭᠡ ᠴᠤᠭᠯᠠᠭᠤᠯᠳᠠᠭ ᠪᠠᠶᠢᠵᠠᠢ᠃ ᠲᠡᠭᠦᠨ ᠦ ᠴᠤᠭᠯᠠᠭᠤᠯᠭ᠎ᠠ ᠶᠢᠨ ᠲᠠᠮᠠᠭ᠎ᠠ ᠣᠳᠣᠭ᠎ᠠ ᠦᠯᠡᠳᠡᠭᠰᠡᠨ ᠵᠠᠷᠢᠮ ᠪᠦᠲᠦᠭᠡᠯ ᠳᠡᠭᠡᠷ᠎ᠡ ᠪᠤᠢ᠃ ᠣᠷᠳᠣᠨ ᠤ ᠮᠦᠽᠧᠢ ᠲᠡᠭᠦᠰ ᠪᠠ ᠬᠠᠭᠠᠰ ᠦᠯᠡᠳᠡᠭᠰᠡᠨ ᠲᠠᠮᠠᠭ᠎ᠠ ᠶᠢ ᠴᠤ ᠰᠤᠳᠤᠯᠵᠤ᠂ ᠡᠵᠡᠮᠰᠢᠭᠴᠢᠳ ᠦᠨ ᠲᠡᠦᠬᠡ ᠶᠢ ᠮᠥᠷᠳᠡᠵᠡᠢ᠃',
        '᠑᠓᠒᠓ ᠣᠨ ᠳᠤ ᠭᠦᠩᠵᠦ ᠣᠯᠠᠨ ᠤᠭᠰᠠᠭᠠᠲᠠᠨ ᠤ ᠡᠷᠳᠡᠮᠲᠡᠨ᠂ ᠲᠦᠰᠢᠮᠡᠳ ᠢ ᠤᠷᠢᠵᠤ᠂ ᠴᠤᠭᠯᠠᠭᠤᠯᠭ᠎ᠠ ᠶᠢᠨ ᠪᠦᠲᠦᠭᠡᠯ ᠦᠳ ᠢ ᠬᠠᠮᠲᠤ ᠦᠵᠡᠵᠡᠢ᠃ ᠣᠷᠣᠯᠴᠠᠭᠴᠢᠳ ᠤᠨ ᠬᠣᠵᠢᠮ ᠨᠡᠮᠡᠵᠦ ᠪᠢᠴᠢᠭᠰᠡᠨ ᠲᠡᠮᠳᠡᠭᠯᠡᠯ ᠨᠢ ᠦᠭᠦᠨ ᠢ ᠰᠤᠳᠤᠯᠬᠤ ᠪᠠᠰᠠ ᠨᠢᠭᠡ ᠪᠠᠷᠢᠮᠲᠠ ᠪᠣᠯᠳᠠᠭ᠃',
      ],
