          organization: 'ᠠᠽᠢ ᠨᠣᠮᠣᠭᠤᠨ ᠳᠠᠯᠠᠢ ᠶᠢᠨ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠥᠪ',
          originalTitle: 'Sounds from Mongolian Grasslands — Benedictions',
          originalOrganization: 'ICHCAP, under the auspices of UNESCO',
          title: 'ᠢᠷᠥᠭᠡᠯ',
