          nameMn: 'ᠨᠠᠫᠣᠯᠢ ᠶᠢᠨ ᠳᠣᠷᠣᠨ᠎ᠠ ᠶᠢᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ',
          organization: 'ᠨᠠᠫᠣᠯᠢ ᠶᠢᠨ ᠳᠣᠷᠣᠨ᠎ᠠ ᠶᠢᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ',
