      summary:
        'ᠶᠢᠩᠴᠠᠩ ᠬᠣᠲᠠ ᠶᠢᠨ ᠲᠤᠭᠤᠷᠢ ᠨᠢ ᠶᠤᠸᠠᠨ ᠤ ᠬᠣᠩᠭᠢᠷᠠᠳ ᠨᠣᠶᠠᠳ ᠤᠨ ᠬᠣᠲᠠ ᠪᠠ ᠪᠡᠯᠴᠢᠭᠡᠷ ᠦᠨ ᠬᠣᠯᠪᠣᠭ᠎ᠠ ᠶᠢ ᠲᠠᠨᠢᠭᠤᠯᠤᠨ᠎ᠠ᠃',
      body: [
        'ᠡᠨᠡ ᠬᠣᠲᠠ ᠶᠢ ᠯᠤ ᠸᠠᠩ ᠤᠨ ᠬᠣᠲᠠ ᠭᠡᠵᠦ ᠴᠤ ᠨᠡᠷᠡᠯᠡᠳᠡᠭ᠃ ᠲᠤᠭᠤᠷᠢ ᠨᠢ ᠥᠪᠥᠷ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠬᠡᠰᠢᠭᠲᠡᠨ ᠬᠣᠰᠢᠭᠤᠨ ᠤ ᠳᠠᠯᠠᠢ ᠨᠠᠭᠤᠷ ᠤᠨ ᠪᠠᠷᠠᠭᠤᠨ ᠡᠮᠦᠨ᠎ᠡ ᠪᠠᠶᠢᠨ᠎ᠠ᠃ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠲᠡᠦᠬᠡᠨ ᠦ ᠮᠡᠳᠡᠭᠡᠨ ᠳᠦ ᠬᠣᠩᠭᠢᠷᠠᠳ ᠤᠨ ᠡᠨᠡ ᠬᠣᠲᠠ ᠶᠢ ᠑᠒᠗᠑ ᠣᠨ ᠳᠤ ᠪᠠᠷᠢᠭᠰᠠᠨ ᠭᠡᠵᠡᠢ᠃',
        'ᠬᠣᠲᠠ ᠨᠢ ᠳᠣᠲᠣᠭᠠᠳᠤ᠂ ᠭᠠᠳᠠᠭᠠᠳᠤ ᠬᠣᠲᠠ ᠪᠠ ᠬᠡᠷᠡᠮ ᠦᠨ ᠭᠠᠳᠠᠨᠠᠬᠢ ᠰᠠᠭᠤᠷᠢᠨ ᠠᠴᠠ ᠪᠦᠷᠢᠯᠳᠦᠵᠡᠢ᠃ ᠳᠣᠲᠣᠭᠠᠳᠤ ᠬᠣᠲᠠᠨ ᠤ ᠬᠠᠨ᠎ᠠ ᠶᠢ ᠳᠡᠯᠳᠡᠭᠰᠡᠨ ᠱᠣᠷᠣᠢ ᠪᠠᠷ ᠪᠠᠷᠢᠵᠤ᠂ ᠲᠣᠭᠣᠰᠬ᠎ᠠ ᠪᠠᠷ ᠪᠦᠷᠢᠵᠡᠢ᠃ ᠬᠣᠲᠠ ᠶᠢᠨ ᠣᠷᠴᠢᠮ ᠤᠨ ᠰᠦᠮ᠎ᠡ ᠪᠠ ᠪᠤᠯᠠᠰᠢᠨ ᠤ ᠲᠤᠭᠤᠷᠢ ᠨᠢ ᠬᠡᠷᠡᠮ ᠡᠴᠡ ᠭᠠᠳᠠᠭᠰᠢᠬᠢ ᠠᠮᠢᠳᠤᠷᠠᠯ ᠢ ᠰᠤᠳᠤᠯᠬᠤ ᠪᠠᠷᠢᠮᠲᠠ ᠪᠣᠯᠣᠨ᠎ᠠ᠃',
      ],
