      summary:
        'ᠠᠷᠵᠠᠢ ᠶᠢᠨ ᠬᠠᠨᠠᠨ ᠵᠢᠷᠤᠭ ᠨᠢ ᠣᠷᠳᠣᠰ ᠤᠨ ᠪᠤᠳᠳᠠ ᠶᠢᠨ ᠱᠠᠰᠢᠨ ᠪᠠ ᠮᠣᠩᠭᠣᠯ ᠨᠣᠶᠠᠳ ᠤᠨ ᠵᠠᠩ ᠦᠢᠯᠡ ᠶᠢ ᠰᠤᠳᠤᠯᠬᠤ ᠡᠬᠡ ᠮᠠᠲ᠋ᠧᠷᠢᠶᠠᠯ ᠶᠤᠮ᠃',
      body: [
        'ᠡᠨᠡ ᠠᠭᠤᠢ ᠰᠦᠮ᠎ᠡ ᠥᠪᠥᠷ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠣᠷᠳᠣᠰ ᠬᠣᠲᠠ ᠶᠢᠨ ᠣᠲᠣᠭ ᠬᠣᠰᠢᠭᠤᠨ ᠤ ᠠᠷᠪᠠᠰ ᠰᠤᠮᠤᠨ ᠳᠤ ᠪᠤᠢ᠃ ᠲᠡᠭᠦᠨ ᠢ ᠤᠯᠠᠭᠠᠨ ᠡᠯᠡᠰᠦᠨ ᠴᠢᠯᠠᠭᠤᠨ ᠲᠣᠯᠣᠭᠠᠢ ᠶᠢᠨ ᠬᠠᠳᠠᠨ ᠳᠤ ᠤᠬᠤᠨ ᠭᠠᠷᠭᠠᠵᠤ᠂ ᠳᠣᠲᠣᠷᠠᠬᠢ ᠬᠠᠨ᠎ᠠ ᠳᠤ ᠪᠤᠷᠬᠠᠨ ᠪᠠ ᠬᠦᠮᠦᠨ ᠦ ᠳᠦᠷᠰᠦ ᠵᠢᠷᠤᠵᠠᠢ᠃',
        'ᠵᠢᠷᠤᠭ ᠤᠳ ᠨᠢ ᠨᠢᠭᠡ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠪᠢᠰᠢ᠃ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠡᠮᠳᠡᠭᠯᠡᠯ ᠳᠦ ᠶᠤᠸᠠᠨ ᠪᠠ ᠮᠢᠩ ᠦᠨ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠱᠠᠰᠢᠨ ᠤ ᠵᠢᠷᠤᠭ ᠠᠴᠠ ᠭᠠᠳᠠᠨ᠎ᠠ᠂ ᠮᠣᠩᠭᠣᠯ ᠨᠣᠶᠠᠳ ᠤᠨ ᠲᠠᠬᠢᠯᠭ᠎ᠠ᠂ ᠪᠦᠵᠢᠭ᠂ ᠪᠠᠶᠠᠷ ᠪᠠ ᠣᠷᠣᠰᠢᠭᠤᠯᠭ᠎ᠠ ᠶᠢᠨ ᠳᠦᠷᠰᠦ ᠪᠤᠢ ᠭᠡᠵᠦ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃ ᠵᠢᠷᠤᠭ ᠨᠢᠭᠡᠪᠦᠷᠢ ᠶᠢᠨ ᠣᠨ ᠴᠠᠭ ᠪᠠ ᠳᠦᠷᠰᠦᠯᠡᠭᠳᠡᠭᠰᠡᠨ ᠬᠦᠮᠦᠨ ᠢ ᠲᠤᠰ ᠲᠤᠰ ᠲᠤ ᠨᠢ ᠰᠤᠳᠤᠯᠬᠤ ᠬᠡᠷᠡᠭᠲᠡᠢ᠃',
      ],
