          nameMn: 'ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠦᠨᠳᠡᠰᠦᠨ ᠦ ᠲᠥᠪ',
