      body: [
        'ᠪᠣᠷᠴᠠ ᠬᠢᠬᠦ ᠳᠦ ᠮᠢᠬ᠎ᠠ ᠶᠢ ᠶᠠᠰᠤ ᠪᠠ ᠱᠥᠷᠮᠥᠰᠦ ᠡᠴᠡ ᠰᠠᠯᠭᠠᠵᠤ᠂ ᠤᠷᠲᠤᠪᠲᠤᠷ ᠵᠦᠰᠦᠭᠡᠳ ᠥᠯᠭᠥᠵᠦ ᠬᠠᠲᠠᠭᠠᠳᠠᠭ᠃ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠥᠪ ᠦᠨ ᠮᠡᠳᠡᠭᠡᠨ ᠳᠦ ᠦᠬᠡᠷ ᠪᠠ ᠲᠡᠮᠡᠭᠡᠨ ᠦ ᠮᠢᠬ᠎ᠠ ᠶᠢ ᠭᠣᠣᠯ ᠵᠢᠱᠢᠶ᠎ᠠ ᠪᠣᠯᠭᠠᠵᠠᠢ᠃',
        'ᠬᠠᠲᠠᠭᠰᠠᠨ ᠪᠣᠷᠴᠠ ᠶᠢ ᠨᠢᠳᠦᠵᠦ ᠨᠤᠨᠲᠠᠭᠯᠠᠨ ᠬᠡᠷᠡᠭᠯᠡᠬᠦ ᠠᠷᠭ᠎ᠠ ᠪᠠᠰᠠ ᠪᠤᠢ᠃ ᠡᠨᠡ ᠮᠡᠳᠡᠭᠡ ᠪᠤᠷᠢᠶᠠᠳ ᠪᠠ ᠬᠠᠮᠨᠢᠭᠠᠨ ᠤ ᠳᠤᠮᠳᠠ ᠵᠢᠭᠠᠰᠤ ᠪᠣᠷᠴᠠᠯᠠᠬᠤ ᠵᠠᠩᠰᠢᠯ ᠢ ᠴᠤ ᠳᠤᠷᠠᠳᠴᠠᠢ᠃ ᠲᠡᠶᠢᠮᠦ ᠡᠴᠡ ᠲᠡᠦᠬᠡᠢ ᠡᠳ ᠪᠠ ᠠᠷᠭ᠎ᠠ ᠨᠢ ᠨᠤᠲᠤᠭ ᠪᠠ ᠠᠷᠠᠳ ᠠᠴᠠ ᠰᠢᠯᠲᠠᠭᠠᠯᠠᠨ ᠶᠠᠯᠭᠠᠷᠠᠨ᠎ᠠ᠃',
      ],
