      summary: 'ᠪᠤᠤᠵᠠᠨ ᠤ ᠬᠡᠯᠪᠡᠷᠢ ᠪᠠ ᠴᠢᠮᠬᠢᠬᠦ ᠠᠷᠭ᠎ᠠ ᠨᠢ ᠬᠣᠭᠣᠯ ᠤᠨ ᠭᠠᠷ ᠤᠨ ᠤᠷ᠎ᠠ ᠶᠢ ᠬᠠᠷᠠᠭᠤᠯᠳᠠᠭ᠃',
      body: [
        'ᠪᠤᠤᠵᠠ ᠨᠢ ᠲᠠᠲᠠᠭᠰᠠᠨ ᠮᠢᠬ᠎ᠠ ᠶᠢ ᠡᠯᠳᠡᠭᠰᠡᠨ ᠭᠤᠷᠢᠯ ᠳᠤ ᠪᠣᠭᠣᠵᠤ᠂ ᠴᠢᠮᠬᠢᠭᠡᠳ ᠵᠢᠭᠨᠡᠳᠡᠭ ᠬᠣᠭᠣᠯ᠃ ᠮᠣᠩᠭᠣᠯ ᠵᠣᠷ ᠲᠤ ᠮᠢᠬ᠎ᠠ᠂ ᠬᠣᠨᠢᠨ ᠤ ᠰᠡᠭᠦᠯ ᠦᠨ ᠥᠭᠡᠭᠦ ᠪᠠ ᠰᠣᠩᠭᠢᠨ᠎ᠠ ᠵᠡᠷᠭᠡ ᠠᠮᠲᠠᠯᠠᠭᠤᠷ ᠬᠡᠷᠡᠭᠯᠡᠳᠡᠭ᠃ ᠪᠣᠷᠴᠠ ᠪᠤᠶᠤ ᠨᠣᠭᠣᠭ᠎ᠠ ᠲᠠᠢ ᠬᠤᠪᠢᠯᠪᠤᠷᠢ ᠴᠤ ᠪᠤᠢ᠃',
        'ᠳᠦᠷᠰᠦ ᠪᠠ ᠴᠢᠮᠬᠢᠯᠲᠠ ᠪᠠᠷ ᠨᠢ ᠳᠤᠭᠤᠶᠢ᠂ ᠤᠷᠲᠤᠪᠲᠤᠷ᠂ ᠴᠡᠴᠡᠭ ᠪᠠ ᠰᠠᠷᠠᠨ ᠬᠡᠯᠪᠡᠷᠢ ᠲᠡᠢ ᠭᠡᠵᠦ ᠨᠡᠷᠡᠯᠡᠳᠡᠭ᠃ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠥᠪ ᠦᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠬᠦᠷᠢᠶᠡᠨ ᠦ ᠪᠤᠤᠵᠠ ᠭᠡᠵᠦ ᠨᠢᠭᠡ ᠦᠮᠬᠦ ᠢᠳᠡᠬᠦ ᠵᠢᠵᠢᠭ ᠬᠡᠯᠪᠡᠷᠢ ᠶᠢ ᠴᠤ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠵᠠᠢ᠃',
      ],
