      title: 'ᠮᠠᠶᠢᠳᠠᠷ ᠤᠨ ᠵᠤᠤ',
      summary:
        'ᠮᠠᠶᠢᠳᠠᠷ ᠤᠨ ᠵᠤᠤ ᠳᠤ ᠬᠣᠲᠠ᠂ ᠣᠷᠳᠤ ᠪᠠ ᠰᠦᠮ᠎ᠡ ᠶᠢᠨ ᠦᠦᠷᠭᠡ ᠬᠣᠰᠣᠯᠣᠵᠤ᠂ ᠲᠦᠮᠡᠳ ᠦᠨ ᠲᠡᠦᠬᠡ ᠶᠢᠨ ᠥᠪ ᠢ ᠦᠯᠡᠳᠡᠭᠡᠵᠡᠢ᠃',
      body: [
        'ᠥᠪᠥᠷ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠪᠤᠭᠤᠲᠤ ᠬᠣᠲᠠ ᠶᠢᠨ ᠲᠦᠮᠡᠳ ᠦᠨ ᠪᠠᠷᠠᠭᠤᠨ ᠬᠣᠰᠢᠭᠤᠨ ᠳᠠᠬᠢ ᠮᠠᠶᠢᠳᠠᠷ ᠤᠨ ᠵᠤᠤ ᠨᠢ ᠠᠷᠪᠠᠨ ᠵᠢᠷᠭᠤᠭᠠᠳᠤᠭᠠᠷ ᠵᠠᠭᠤᠨ ᠤ ᠲᠦᠮᠡᠳ ᠦᠨ ᠤᠯᠤᠰ ᠲᠥᠷᠥ ᠶᠢᠨ ᠲᠥᠪ ᠲᠡᠢ ᠬᠣᠯᠪᠣᠭᠠᠲᠠᠢ᠃ ᠴᠣᠭᠴᠠ ᠨᠢ ᠰᠦᠮ᠎ᠡ ᠪᠠ ᠰᠠᠭᠤᠬᠤ ᠥᠷᠭᠥᠭᠡ ᠶᠢ ᠬᠡᠷᠡᠮ ᠦᠨ ᠳᠣᠲᠣᠷ᠎ᠠ ᠬᠠᠮᠲᠤ ᠪᠠᠭᠲᠠᠭᠠᠵᠠᠢ᠃',
        'ᠬᠠᠨᠠᠨ ᠵᠢᠷᠤᠭ ᠤᠳ ᠲᠤ ᠪᠤᠷᠬᠠᠨ᠂ ᠪᠣᠳᠢᠰᠠᠳᠤᠸᠠ᠂ ᠮᠠᠨᠳᠠᠯ ᠪᠠ ᠥᠭᠯᠢᠭᠡ ᠶᠢᠨ ᠡᠵᠡᠳ ᠦᠨ ᠳᠦᠷᠰᠦ ᠪᠤᠢ᠃ ᠪᠤᠭᠤᠲᠤ ᠶᠢᠨ ᠮᠦᠽᠧᠢ ᠶᠢᠨ ᠦᠵᠡᠰᠬᠦᠯᠡᠩ ᠦ ᠮᠡᠳᠡᠭᠡᠨ ᠳᠦ ᠠᠯᠲᠠᠨ ᠬᠠᠨ ᠤ ᠭᠡᠷ ᠪᠦᠯᠢ ᠶᠢᠨ ᠥᠭᠯᠢᠭᠡ ᠶᠢᠨ ᠡᠵᠡᠨ ᠦ ᠳᠦᠷᠰᠦ ᠶᠢ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠵᠢᠷᠤᠭ ᠤᠳ ᠢ ᠡᠯ᠎ᠡ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠵᠠᠰᠪᠤᠷᠢ ᠪᠠ ᠱᠠᠰᠢᠨ ᠤ ᠠᠰᠢᠭᠯᠠᠯᠲᠠ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠨ ᠤᠩᠰᠢᠬᠤ ᠬᠡᠷᠡᠭᠲᠡᠢ᠃',
      ],
