          title: 'ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠪᠠᠶᠢᠭᠠᠯ ᠣᠷᠴᠢᠮ ᠤᠨ ᠨᠤᠲᠤᠭ',
          organization: 'ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠰᠢᠨᠵᠢᠯᠡᠬᠦ ᠤᠬᠠᠭᠠᠨ ᠤ ᠠᠺᠠᠳᠧᠮᠢ',
          nameMn: 'ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠤᠨ ᠰᠢᠨᠵᠢᠯᠡᠬᠦ ᠤᠬᠠᠭᠠᠨ ᠤ ᠠᠺᠠᠳᠧᠮᠢ',
          originalTitle: 'Буриад',
