          organization: 'ᠠᠽᠢ ᠨᠣᠮᠣᠭᠤᠨ ᠳᠠᠯᠠᠢ ᠶᠢᠨ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠥᠪ',
