        'ᠱᠢᠨ᠎ᠡ ᠢᠷᠡᠭᠰᠡᠨ ᠲᠠᠬᠢ ᠶᠢ ᠠᠩᠬ᠎ᠠ ᠳᠠᠭᠠᠨ ᠬᠠᠱᠢᠶᠠᠲᠤ ᠲᠠᠯᠠᠪᠤᠷᠢ ᠳᠤ ᠳᠠᠰᠤᠭᠠᠵᠠᠢ᠃ ᠲᠡᠳᠡ ᠤᠷᠭᠤᠮᠠᠯ᠂ ᠴᠠᠭ ᠠᠭᠤᠷ ᠪᠠ ᠰᠦᠷᠦᠭ ᠲᠡᠭᠡᠨ ᠳᠠᠰᠤᠭᠰᠠᠨ ᠤ ᠳᠠᠷᠠᠭ᠎ᠠ᠂ ᠨᠢᠭᠡ ᠪᠤᠶᠤ ᠬᠣᠶᠠᠷ ᠵᠢᠯ ᠪᠣᠯᠵᠤ ᠪᠠᠶᠢᠵᠤ ᠰᠤᠯᠠ ᠲᠠᠯᠪᠢᠳᠠᠭ ᠪᠠᠶᠢᠵᠠᠢ᠃',
