      body: [
        'ᠤᠯᠠᠭᠠᠨᠪᠠᠭᠠᠲᠤᠷ ᠤᠨ ᠣᠶᠢᠷᠠᠬᠢ ᠪᠣᠭᠳᠠ ᠠᠭᠤᠯᠠᠨ ᠤ ᠬᠦᠷᠡᠯ ᠲᠣᠭᠣᠭᠠᠲᠤ ᠳᠤ ᠑᠙᠕᠗ ᠣᠨ ᠳᠤ ᠣᠳᠣᠨ ᠣᠷᠣᠨ ᠠᠵᠢᠭᠯᠠᠬᠤ ᠲᠥᠪ ᠦᠨ ᠪᠠᠷᠢᠯᠭ᠎ᠠ ᠶᠢ ᠡᠬᠢᠯᠡᠵᠡᠢ᠃ ᠡᠨᠡ ᠨᠢ ᠣᠯᠠᠨ ᠤᠯᠤᠰ ᠤᠨ ᠭᠧᠣᠹᠢᠽᠢᠺᠡ ᠶᠢᠨ ᠵᠢᠯ ᠦᠨ ᠦᠶ᠎ᠡ ᠪᠠᠶᠢᠵᠠᠢ᠃',
        '᠑᠙᠕᠘ ᠣᠨ ᠠᠴᠠ ᠣᠳᠣᠳ ᠤᠨ ᠪᠠᠶᠢᠷᠢ ᠶᠢ ᠠᠵᠢᠭᠯᠠᠵᠤ ᠴᠠᠭ ᠪᠠ ᠥᠷᠭᠡᠷᠢᠭ ᠢ ᠲᠣᠭᠲᠠᠭᠠᠬᠤ ᠠᠵᠢᠯ ᠬᠢᠵᠡᠢ᠃ ᠑᠙᠖᠔ ᠣᠨ ᠠᠴᠠ ᠨᠠᠷᠠᠨ ᠤ ᠢᠳᠡᠪᠬᠢᠲᠦ ᠦᠵᠡᠭᠳᠡᠯ ᠢ ᠰᠤᠳᠤᠯᠵᠠᠢ᠃ ᠲᠤᠰ ᠲᠥᠪ ᠦᠨ ᠡᠷᠳᠡᠮᠲᠡᠨ ᠦ ᠲᠠᠶᠢᠯᠤᠩ ᠡᠳᠡᠭᠡᠷ ᠠᠵᠢᠯ ᠢ ᠲᠣᠳᠣᠷᠬᠠᠢ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃',
      ],
