      summary:
        'ᠡᠵᠢᠨ᠎ᠡ ᠶᠢᠨ ᠬᠠᠷ᠎ᠠ ᠬᠣᠲᠠ ᠨᠢ ᠲᠠᠩᠭᠤᠳ ᠪᠠ ᠶᠤᠸᠠᠨ ᠤ ᠬᠣᠶᠠᠷ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠬᠣᠲᠠᠨ ᠤ ᠲᠤᠭᠤᠷᠢ ᠶᠢ ᠬᠠᠳᠠᠭᠠᠯᠠᠵᠠᠢ᠃',
      body: [
        'ᠬᠠᠷ᠎ᠠ ᠬᠣᠲᠠ ᠥᠪᠥᠷ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠠᠯᠠᠱᠠ ᠠᠶᠢᠮᠠᠭ ᠤᠨ ᠡᠵᠢᠨ᠎ᠡ ᠬᠣᠰᠢᠭᠤᠨ ᠳᠤ ᠪᠠᠶᠢᠨ᠎ᠠ᠃ ᠲᠠᠩᠭᠤᠳ ᠤᠨ ᠴᠡᠷᠢᠭ ᠦᠨ ᠬᠣᠲᠠ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠡᠨᠡ ᠭᠠᠵᠠᠷ ᠢ ᠶᠤᠸᠠᠨ ᠤ ᠦᠶ᠎ᠡ ᠳᠦ ᠥᠷᠭᠡᠵᠢᠭᠦᠯᠵᠦ᠂ ᠡᠵᠢᠨ᠎ᠡ ᠯᠦ᠋ ᠶᠢᠨ ᠵᠠᠬᠢᠷᠭᠠᠨ ᠤ ᠲᠥᠪ ᠪᠣᠯᠭᠠᠵᠠᠢ᠃',
        'ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠲᠡᠦᠬᠡᠨ ᠳᠦ᠂ ᠡᠨᠡ ᠬᠣᠲᠠ ᠭᠠᠨᠰᠦ᠋ ᠡᠴᠡ ᠭᠣᠪᠢ ᠶᠢᠨ ᠠᠷᠤ ᠲᠡᠶᠢᠰᠢ ᠶᠠᠪᠤᠬᠤ ᠵᠠᠮ ᠤᠨ ᠬᠦᠨᠡᠰᠦ ᠬᠠᠩᠭᠠᠬᠤ ᠭᠠᠵᠠᠷ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠢ ᠥᠭᠦᠯᠡᠵᠡᠢ᠃ ᠪᠠᠷᠠᠭᠤᠨ ᠵᠡᠭᠦᠨ ᠴᠢᠭᠯᠡᠭᠰᠡᠨ ᠶᠡᠬᠡ ᠭᠤᠳᠤᠮᠵᠢᠨ ᠤ ᠳᠠᠭᠠᠭᠤ ᠳᠡᠯᠭᠡᠭᠦᠷ᠂ ᠰᠠᠭᠤᠷᠢ ᠪᠠᠶᠢᠰᠢᠩ᠂ ᠶᠠᠮᠤ ᠪᠠ ᠰᠦᠮ᠎ᠡ ᠶᠢᠨ ᠮᠥᠷ ᠪᠤᠢ᠃',
      ],
