          organization: 'ᠳᠤᠮᠳᠠᠳᠤ ᠶᠢᠨ ᠪᠢᠶᠡᠲᠦ ᠪᠤᠰᠤ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠴᠠᠬᠢᠮ ᠮᠦᠽᠧᠢ',
          nameMn: 'ᠳᠤᠮᠳᠠᠳᠤ ᠶᠢᠨ ᠪᠢᠶᠡᠲᠦ ᠪᠤᠰᠤ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠴᠠᠬᠢᠮ ᠮᠦᠽᠧᠢ',
