      title: 'ᠮᠥᠩᠬᠡ ᠮᠥᠰᠦ ᠪᠠ ᠴᠠᠭ᠎ᠠ ᠪᠤᠭᠤ',
      summary: 'ᠬᠣᠢᠲᠤ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠥᠨᠳᠥᠷ ᠠᠭᠤᠯᠠᠨ ᠤ ᠮᠥᠰᠦ ᠨᠢ ᠴᠠᠭ᠎ᠠ ᠪᠤᠭᠤ ᠮᠠᠯᠯᠠᠬᠤ ᠠᠮᠢᠳᠤᠷᠠᠯ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠭᠠᠲᠠᠢ᠃',
      body: [
        '᠒᠐᠑᠙ ᠣᠨ ᠤ ᠰᠤᠳᠤᠯᠭ᠎ᠠ ᠬᠣᠢᠲᠤ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠪᠠᠷᠠᠭᠤᠨ ᠲᠠᠶᠢᠭ᠎ᠠ ᠳᠤ ᠣᠨ ᠳᠠᠮᠨᠠᠨ ᠲᠣᠭᠲᠠᠳᠠᠭ ᠴᠠᠰᠤ ᠮᠥᠰᠦᠨ ᠦ ᠬᠡᠰᠡᠭ ᠦᠳ ᠢ ᠰᠤᠳᠤᠯᠵᠠᠢ᠃ ᠮᠠᠯᠴᠢᠳ ᠲᠡᠳᠡᠭᠡᠷ ᠢ ᠵᠤᠨ ᠳᠤ ᠴᠠᠭ᠎ᠠ ᠪᠤᠭᠤ ᠪᠠᠨ ᠰᠡᠷᠡᠭᠦᠴᠡᠭᠦᠯᠬᠦ᠂ ᠰᠢᠮᠠᠭᠤᠯᠠᠯ ᠬᠣᠷᠣᠭᠬᠠᠢ ᠠᠴᠠ ᠵᠠᠢᠯᠠᠭᠤᠯᠬᠤ ᠳᠤ ᠠᠰᠢᠭᠯᠠᠳᠠᠭ᠃',
        'ᠮᠥᠰᠦ ᠬᠠᠶᠢᠯᠬᠤ ᠨᠢ ᠵᠤᠰᠤᠯᠠᠩ ᠪᠠ ᠮᠠᠯ ᠤᠨ ᠠᠷᠴᠢᠯᠠᠭᠠᠨ ᠳᠤ ᠬᠦᠨᠳᠦᠷᠡᠯ ᠭᠠᠷᠭᠠᠵᠤ ᠪᠠᠶᠢᠭ᠎ᠠ ᠶᠢ ᠮᠠᠯᠴᠢᠳ ᠤᠨ ᠶᠠᠷᠢᠯᠴᠠᠯᠭ᠎ᠠ ᠪᠠ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠠᠵᠢᠭᠯᠠᠯᠲᠠ ᠪᠠᠷ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠮᠥᠰᠦᠨ ᠳᠦ ᠬᠠᠳᠠᠭᠠᠯᠠᠭᠳᠠᠭᠰᠠᠨ ᠮᠣᠳᠣᠨ ᠡᠳᠯᠡᠯ ᠵᠡᠷᠭᠡ ᠵᠦᠢᠯ ᠴᠤ ᠬᠠᠶᠢᠯᠠᠯᠲᠠ ᠶᠢᠨ ᠳᠠᠷᠠᠭ᠎ᠠ ᠢᠯᠡ ᠭᠠᠷᠴᠤ᠂ ᠲᠦᠷᠭᠡᠨ ᠡᠪᠳᠡᠷᠡᠬᠦ ᠠᠶᠤᠯ ᠲᠠᠢ ᠪᠣᠯᠵᠠᠢ᠃',
      ],
