      summary: 'ᠳᠠᠷᠤᠭᠠᠴᠢ ᠶᠢᠨ ᠠᠯᠪᠠ ᠨᠢ ᠴᠠᠭ ᠦᠶ᠎ᠡ᠂ ᠭᠠᠵᠠᠷ ᠣᠷᠣᠨ ᠢ ᠳᠠᠭᠠᠵᠤ ᠶᠠᠯᠭᠠᠭ᠎ᠠ ᠲᠠᠢ ᠪᠠᠶᠢᠵᠠᠢ᠃',
      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠡᠵᠡᠨᠲᠦ ᠭᠦᠷᠦᠨ ᠡᠷᠬᠡ ᠳᠦ ᠪᠡᠨ ᠣᠷᠣᠭᠤᠯᠤᠭᠰᠠᠨ ᠭᠠᠵᠠᠷ ᠲᠤ ᠳᠠᠷᠤᠭᠠᠴᠢ ᠲᠣᠮᠢᠯᠠᠵᠤ ᠪᠠᠶᠢᠵᠠᠢ᠃ ᠲᠡᠳᠡ ᠬᠦᠨ ᠠᠮᠠᠨ ᠤ ᠲᠣᠭᠠᠯᠠᠯ᠂ ᠠᠯᠪᠠ ᠲᠠᠲᠠᠪᠤᠷᠢ᠂ ᠴᠡᠷᠢᠭ ᠲᠠᠲᠠᠬᠤ ᠵᠡᠷᠭᠡ ᠠᠵᠢᠯ ᠳᠤ ᠣᠷᠣᠯᠴᠠᠵᠤ᠂ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠨᠣᠶᠠᠳ ᠢ ᠬᠢᠨᠠᠵᠤ ᠪᠠᠶᠢᠵᠠᠢ᠃',
        'ᠭᠡᠪᠡᠴᠦ ᠪᠦᠬᠦ ᠳᠠᠷᠤᠭᠠᠴᠢ ᠠᠳᠠᠯᠢ ᠡᠷᠬᠡ᠂ ᠦᠭᠦᠷᠭᠡ ᠲᠡᠢ ᠪᠠᠶᠢᠭ᠎ᠠ ᠦᠭᠡᠢ᠃ ᠶᠤᠸᠠᠨ ᠤᠯᠤᠰ ᠤᠨ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠪᠠᠶᠢᠭᠤᠯᠤᠯᠭ᠎ᠠ ᠳᠤ ᠳᠠᠷᠤᠭᠠᠴᠢ ᠪᠤᠰᠤᠳ ᠵᠠᠬᠢᠷᠤᠭᠴᠢ ᠲᠠᠢ ᠬᠠᠮᠲᠤ ᠠᠵᠢᠯᠯᠠᠵᠤ ᠪᠠᠶᠢᠵᠠᠢ᠃ ᠢᠷᠠᠨ ᠤ ᠭᠠᠷ ᠤᠷᠠᠴᠤᠳ ᠵᠡᠷᠭᠡ ᠲᠤᠰᠬᠠᠢ ᠪᠦᠯᠦᠭ ᠢ ᠴᠦ ᠳᠠᠷᠤᠭᠠᠴᠢ ᠪᠠᠷ ᠬᠠᠷᠢᠭᠤᠴᠠᠭᠤᠯᠳᠠᠭ ᠪᠠᠶᠢᠵᠠᠢ᠃',
      ],
