      summary:
        '᠑᠙᠒᠔ ᠣᠨ ᠤ ᠦᠨᠳᠦᠰᠦᠨ ᠬᠠᠭᠤᠯᠢ ᠶᠢᠨ ᠡᠮᠡᠭᠲᠡᠶᠢᠴᠦᠳ ᠦᠨ ᠡᠷᠬᠡ ᠪᠠ ᠨᠡᠶᠢᠭᠡᠮ ᠦᠨ ᠬᠢᠵᠠᠭᠠᠷᠯᠠᠯ ᠢ ᠬᠠᠮᠲᠤ ᠦᠵᠡᠬᠦ ᠬᠡᠷᠡᠭᠲᠡᠢ᠃',
      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠯᠤᠰ ᠑᠙᠒᠔ ᠣᠨ ᠳᠤ ᠠᠩᠬᠠᠨ ᠤ ᠦᠨᠳᠦᠰᠦᠨ ᠬᠠᠭᠤᠯᠢ ᠪᠠᠨ ᠪᠠᠲᠤᠯᠠᠵᠠᠢ᠃ ᠲᠡᠷᠡ ᠣᠨ ᠳᠤ ᠡᠮᠡᠭᠲᠡᠶᠢᠴᠦᠳ ᠰᠣᠩᠭᠣᠬᠤ᠂ ᠰᠣᠩᠭᠣᠭᠳᠠᠬᠤ ᠡᠷᠬᠡ ᠲᠡᠢ ᠪᠣᠯᠤᠭᠰᠠᠨ ᠢ ᠣᠯᠠᠨ ᠤᠯᠤᠰ ᠤᠨ ᠫᠠᠷᠯᠠᠮᠧᠨᠲ ᠤᠨ ᠬᠣᠯᠪᠣᠭ᠎ᠠ ᠶᠢᠨ ᠲᠦᠦᠬᠡᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃',
        'ᠡᠨᠡ ᠨᠢ ᠬᠦᠶᠢᠰ ᠦᠨ ᠡᠷᠬᠡ ᠶᠢᠨ ᠴᠢᠬᠤᠯᠠ ᠥᠭᠡᠷᠡᠴᠡᠯᠡᠯᠲᠡ ᠪᠠᠶᠢᠪᠠᠴᠤ᠂ ᠲᠤᠰ ᠬᠠᠭᠤᠯᠢ ᠨᠡᠶᠢᠭᠡᠮ ᠦᠨ ᠪᠠᠶᠢᠳᠠᠯ ᠢᠶᠠᠷ ᠶᠠᠯᠭᠠᠨ ᠬᠢᠵᠠᠭᠠᠷᠯᠠᠳᠠᠭ ᠪᠠᠶᠢᠵᠠᠢ᠃ ᠵᠠᠷᠢᠮ ᠬᠤᠳᠠᠯᠳᠤᠭᠠᠴᠢᠨ᠂ ᠮᠥᠩᠭᠥ ᠬᠡᠭᠦᠯᠡᠭᠴᠢ᠂ ᠨᠣᠶᠠᠳ ᠪᠠ ᠬᠡᠶᠢᠳ ᠲᠦ ᠪᠠᠶᠢᠩᠭᠤ ᠰᠠᠭᠤᠳᠠᠭ ᠯᠠᠮᠠ ᠨᠠᠷ ᠤᠨ ᠰᠣᠩᠭᠣᠬᠤ᠂ ᠰᠣᠩᠭᠣᠭᠳᠠᠬᠤ ᠡᠷᠬᠡ ᠶᠢ ᠬᠠᠰᠤᠭᠰᠠᠨ ᠪᠠᠶᠢᠵᠠᠢ᠃',
      ],
