          organization: 'ᠣᠯᠠᠨ ᠤᠯᠤᠰ ᠤᠨ ᠢᠷᠭᠡᠨ ᠦ ᠠᠭᠠᠭᠠᠷ ᠤᠨ ᠲᠡᠭᠡᠪᠦᠷᠢ ᠶᠢᠨ ᠪᠠᠶᠢᠭᠤᠯᠤᠯᠭ᠎ᠠ',
