      summary:
        'ᠢᠸᠠᠯᠭ᠎ᠠ ᠶᠢᠨ ᠳᠠᠴᠠᠩ ᠨᠢ ᠬᠣᠷᠢᠳᠤᠭᠠᠷ ᠵᠠᠭᠤᠨ ᠤ ᠳᠤᠮᠳᠠ ᠪᠤᠷᠢᠶᠠᠳ ᠲᠤ ᠪᠤᠳᠳᠠ ᠶᠢᠨ ᠱᠠᠰᠢᠨ ᠤ ᠬᠤᠷᠠᠯ ᠳᠠᠬᠢᠨ ᠰᠡᠷᠭᠦᠭᠰᠡᠨ ᠦ ᠴᠢᠬᠤᠯᠠ ᠭᠠᠵᠠᠷ ᠶᠤᠮ᠃',
      body: [
        'ᠣᠷᠣᠰ ᠤᠨ ᠪᠤᠷᠢᠶᠠᠳ ᠲᠠᠬᠢ ᠡᠨᠡ ᠳᠠᠴᠠᠩ ᠤᠨ ᠠᠯᠪᠠᠨ ᠲᠡᠦᠬᠡᠨ ᠳᠦ ᠑᠙᠔᠕ ᠣᠨ ᠳᠤ ᠰᠦᠰᠦᠭᠲᠡᠨ ᠦ ᠬᠦᠰᠡᠯᠲᠡ ᠶᠢ ᠵᠥᠪᠰᠢᠶᠡᠷᠡᠵᠦ᠂ ᠬᠤᠷᠠᠯ ᠨᠣᠮ ᠤᠨ ᠭᠠᠵᠠᠷ ᠨᠡᠭᠡᠭᠡᠬᠦ ᠰᠢᠶᠢᠳᠪᠦᠷᠢ ᠭᠠᠷᠭᠠᠵᠠᠢ ᠭᠡᠵᠦ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠡᠨᠡ ᠨᠢ ᠑᠙᠓᠐ ᠣᠨ ᠤ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠬᠡᠶᠢᠳ ᠦᠳ ᠢ ᠬᠠᠭᠠᠬᠤ ᠪᠠ ᠯᠠᠮᠠᠨᠠᠷ ᠢ ᠬᠡᠯᠮᠡᠭᠳᠡᠭᠦᠯᠬᠦ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠳᠠᠷᠠᠭ᠎ᠠ ᠪᠣᠯᠵᠠᠢ᠃',
        'ᠠᠩᠬᠠᠨ ᠤ ᠬᠤᠷᠠᠯ ᠢ ᠥᠰᠦᠷ ᠪᠤᠯᠠᠭ ᠤᠨ ᠣᠷᠴᠢᠮ ᠳᠠᠬᠢ ᠥᠮᠥᠨ᠎ᠡ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠮᠥᠷᠭᠥᠯ ᠦᠨ ᠪᠠᠶᠢᠰᠢᠩ ᠳᠤ ᠶᠠᠪᠤᠭᠤᠯᠵᠠᠢ᠃ ᠳᠠᠴᠠᠩ ᠤᠨ ᠣᠳᠣᠭ᠎ᠠ ᠶᠢᠨ ᠭᠠᠵᠠᠷ ᠲᠤ ᠑᠙᠔᠖ ᠣᠨ ᠤ ᠴᠠᠭᠠᠨ ᠰᠠᠷ᠎ᠠ ᠪᠠᠷ ᠶᠡᠬᠡ ᠬᠤᠷᠠᠯ ᠬᠢᠵᠡᠢ᠃ ᠡᠨᠡ ᠲᠡᠦᠬᠡ ᠨᠢ ᠰᠦᠰᠦᠭᠲᠡᠨ᠂ ᠯᠠᠮᠠᠨᠠᠷ ᠪᠠ ᠪᠠᠷᠢᠯᠭ᠎ᠠᠨ ᠤ ᠭᠠᠵᠠᠷ ᠤᠨ ᠬᠣᠯᠪᠣᠭ᠎ᠠ ᠶᠢ ᠬᠠᠮᠲᠤ ᠰᠤᠳᠤᠯᠬᠤ ᠶᠢ ᠱᠠᠭᠠᠷᠳᠠᠨ᠎ᠠ᠃',
      ],
