        'ᠲᠠᠮᠴᠢᠨ ᠤ ᠳᠠᠴᠠᠩ ᠨᠢ ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠪᠤᠳᠳᠠ ᠶᠢᠨ ᠱᠠᠰᠢᠨ ᠤ ᠲᠡᠦᠬᠡᠨ ᠳᠦ ᠬᠠᠮᠪᠤ ᠯᠠᠮ᠎ᠠ ᠶᠢᠨ ᠲᠥᠪ ᠪᠠᠶᠢᠵᠠᠢ᠃',
      body: [
        'ᠲᠠᠮᠴᠢᠨ ᠤ ᠳᠠᠴᠠᠩ ᠢ ᠣᠷᠣᠰ ᠢᠶᠠᠷ ᠭᠤᠰᠢᠨᠣᠣᠵᠧᠷᠰᠺᠢ ᠭᠡᠵᠦ ᠴᠤ ᠨᠡᠷᠡᠯᠡᠳᠡᠭ᠃ ᠮᠦᠽᠧᠢ ᠶᠢᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠠᠩᠬᠠᠨ ᠤ ᠡᠰᠡᠭᠡᠢ ᠭᠡᠷ ᠦᠨ ᠬᠤᠷᠠᠯ ᠢ ᠑᠗᠔᠑ ᠣᠨ ᠳᠤ᠂ ᠮᠣᠳᠣᠨ ᠰᠦᠮ᠎ᠡ ᠶᠢ ᠑᠗᠕᠐ ᠣᠨ ᠳᠤ ᠬᠠᠮᠢᠶᠠᠭᠤᠯᠵᠠᠢ᠃ ᠑᠘᠐᠙ ᠣᠨ ᠠᠴᠠ ᠡᠨᠳᠡ ᠪᠠᠨᠳᠢᠳᠠ ᠬᠠᠮᠪᠤ ᠯᠠᠮ᠎ᠠ ᠰᠠᠭᠤᠵᠤ ᠪᠠᠶᠢᠵᠠᠢ᠃',
        '᠑᠙᠓᠘ ᠣᠨ ᠳᠤ ᠳᠠᠴᠠᠩ ᠢ ᠬᠠᠭᠠᠵᠠᠢ᠃ ᠣᠷᠣᠰ ᠤᠨ ᠠᠷᠠᠳ ᠵᠦᠢ ᠶᠢᠨ ᠮᠦᠽᠧᠢ ᠳᠦ ᠑᠙᠐᠘ ᠣᠨ ᠤ ᠭᠣᠣᠯ ᠰᠦᠮ᠎ᠡ ᠶᠢᠨ ᠭᠡᠷᠡᠯ ᠵᠢᠷᠤᠭ ᠬᠠᠳᠠᠭᠠᠯᠠᠭᠳᠠᠵᠠᠢ᠃ ᠢᠶᠢᠮᠦ ᠡᠷᠲᠡᠨ ᠦ ᠵᠢᠷᠤᠭ ᠨᠢ ᠠᠯᠳᠠᠭᠳᠠᠭᠰᠠᠨ ᠪᠠ ᠬᠣᠵᠢᠮ ᠰᠡᠷᠭᠦᠭᠡᠭᠰᠡᠨ ᠪᠠᠷᠢᠯᠭ᠎ᠠ ᠶᠢᠨ ᠬᠡᠯᠪᠡᠷᠢ ᠶᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠬᠤ ᠴᠢᠬᠤᠯᠠ ᠪᠠᠷᠢᠮᠲᠠ ᠪᠣᠯᠣᠨ᠎ᠠ᠃',
      ],
