          organization: 'ᠣᠷᠣᠰ ᠤᠨ ᠪᠤᠳᠳᠠ ᠶᠢᠨ ᠱᠠᠰᠢᠨ ᠰᠡᠳᠬᠦᠯ',
          nameMn: 'ᠣᠷᠣᠰ ᠤᠨ ᠪᠤᠳᠳᠠ ᠶᠢᠨ ᠱᠠᠰᠢᠨ ᠰᠡᠳᠬᠦᠯ',
