          nameMn: 'ᠮᠣᠩᠭᠣᠯ ᠬᠡᠯᠡᠨ ᠦ ᠶᠡᠬᠡ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠲᠣᠯᠢ',
