      category: 'life',
      title: 'ᠴᠢᠩᠭᠢᠰ ᠬᠠᠭᠠᠨ ᠤ ᠲᠠᠬᠢᠯᠭ᠎ᠠ',
      summary:
        'ᠣᠷᠳᠣᠰ ᠤᠨ ᠲᠠᠬᠢᠯᠭ᠎ᠠ ᠨᠢ ᠳᠠᠷᠬᠠᠳ ᠤᠨ ᠰᠠᠬᠢᠬᠤ ᠤᠯᠠᠮᠵᠢᠯᠠᠯ ᠪᠠ ᠲᠦᠦᠬᠡᠨ ᠳᠤᠷᠠᠰᠬᠠᠯ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠭ᠎ᠠ ᠲᠠᠢ᠃',
      body: [
        'ᠥᠪᠥᠷ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠣᠷᠳᠣᠰ ᠨᠤᠲᠤᠭ ᠲᠤ ᠴᠢᠩᠭᠢᠰ ᠬᠠᠭᠠᠨ ᠤ ᠳᠤᠷᠠᠰᠬᠠᠯ ᠢ ᠲᠠᠬᠢᠬᠤ ᠶᠣᠰᠣ ᠪᠤᠢ᠃ ᠡᠨᠡ ᠨᠢ ᠮᠥᠩᠬᠡ ᠲᠡᠩᠷᠢ᠂ ᠥᠪᠥᠭᠡ ᠳᠡᠭᠡᠳᠦᠰ ᠪᠠ ᠪᠠᠭᠠᠲᠤᠷ ᠢ ᠬᠦᠨᠳᠦᠳᠭᠡᠬᠦ ᠢᠲᠡᠭᠡᠯ ᠢ ᠢᠯᠡᠳᠬᠡᠨ᠎ᠡ᠃ ᠰᠦᠦ᠂ ᠠᠷᠢᠬᠢ᠂ ᠭᠠᠯ ᠪᠠ ᠳᠠᠭᠤᠨ ᠤ ᠲᠠᠬᠢᠯ ᠵᠡᠷᠭᠡ ᠬᠡᠯᠪᠡᠷᠢ ᠣᠷᠣᠯᠴᠠᠳᠠᠭ᠃',
        'ᠳᠠᠷᠬᠠᠳ ᠨᠢ ᠡᠨᠡ ᠲᠠᠬᠢᠯᠭ᠎ᠠ ᠶᠢ ᠰᠠᠬᠢᠵᠤ ᠤᠯᠠᠮᠵᠢᠯᠠᠭᠤᠯᠤᠭᠴᠢᠳ ᠶᠤᠮ᠃ ᠶᠣᠰᠣᠯᠠᠯ ᠪᠠ ᠲᠠᠬᠢᠯ ᠤᠨ ᠡᠳ ᠵᠦᠢᠯ ᠨᠢ ᠨᠢᠭᠡᠳᠡᠯ ᠦᠨ ᠳᠤᠷᠠᠰᠬᠠᠯ ᠢ ᠬᠠᠳᠠᠭᠠᠯᠠᠬᠤ ᠳᠤ ᠣᠷᠣᠯᠴᠠᠳᠠᠭ᠃ ᠡᠨᠡ ᠲᠠᠬᠢᠯᠭ᠎ᠠ ᠶᠢ ᠒᠐᠐᠖ ᠣᠨ ᠳᠤ ᠳᠤᠮᠳᠠᠳᠤ ᠤᠯᠤᠰ ᠤᠨ ᠤᠯᠤᠰ ᠤᠨ ᠳᠡᠰ ᠦᠨ ᠥᠪ ᠦᠨ ᠵᠠᠭᠰᠠᠭᠠᠯᠲᠠ ᠳᠤ ᠣᠷᠣᠭᠤᠯᠵᠠᠢ᠃',
      ],
