        'ᠬᠣᠪᠳᠤ ᠶᠢᠨ ᠮᠢᠩᠭᠠᠳ ᠰᠤᠮᠤᠨ ᠤ ᠠᠭᠤᠢ ᠠᠴᠠ ᠣᠯᠳᠠᠭᠰᠠᠨ ᠡᠮᠡᠭᠡᠯ ᠢ ᠬᠤᠰᠤᠨ ᠮᠣᠳᠣᠨ ᠤ ᠬᠡᠰᠡᠭ ᠦᠳ ᠢᠶᠡᠷ ᠡᠪᠯᠡᠭᠦᠯᠵᠦ ᠬᠢᠵᠡᠢ᠃ ᠮᠣᠳᠣᠨ ᠬᠠᠳᠠᠭᠠᠰᠤ ᠪᠠ ᠠᠷᠢᠰᠤᠨ ᠬᠣᠯᠪᠣᠭᠠᠰᠤ ᠪᠤᠢ᠃ ᠠᠷᠢᠰᠤᠨ ᠤ ᠤᠤᠷᠠᠭ ᠢ ᠰᠢᠨᠵᠢᠯᠡᠭᠡᠳ ᠠᠳᠤᠭᠤᠨ ᠤ ᠠᠷᠢᠰᠤ ᠪᠣᠯᠣᠬᠤ ᠶᠢ ᠲᠠᠨᠢᠵᠠᠢ᠃',
