        'ᠵᠠᠪᠬᠠᠨ ᠠᠶᠢᠮᠠᠭ ᠤᠨ ᠰᠢᠯᠦᠭᠦᠰᠦᠲᠡᠢ ᠰᠤᠮᠤᠨ ᠳᠤ ᠮᠠᠯᠴᠢᠳ ᠪᠠ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠠᠵᠢᠯᠲᠠᠨ ᠤᠰᠤᠨ ᠤ ᠬᠣᠮᠰᠣᠳᠣᠯ ᠢ ᠪᠠᠭᠠᠰᠬᠠᠬᠤ ᠠᠷᠭ᠎ᠠ ᠬᠡᠯᠡᠯᠴᠡᠵᠡᠢ᠃ ᠬᠠᠪᠤᠷ ᠤᠨ ᠴᠠᠰᠤᠨ ᠤ ᠬᠠᠶᠢᠯᠠᠭ ᠪᠠ ᠵᠤᠨ ᠤ ᠪᠣᠷᠣᠭᠠᠨ ᠤ ᠤᠷᠤᠰᠤᠴᠠ ᠶᠢ ᠲᠣᠭᠲᠠᠭᠠᠨ ᠬᠤᠷᠢᠮᠲᠠᠭᠤᠯᠬᠤ ᠰᠠᠨᠠᠯ ᠢ ᠰᠣᠩᠭᠣᠵᠠᠢ᠃',
        '᠒᠐᠒᠔ ᠣᠨ ᠤ ᠳᠡᠯᠡᠬᠡᠢ ᠶᠢᠨ ᠪᠠᠩᠺᠢᠨ ᠤ ᠮᠡᠳᠡᠭᠡᠨ ᠳᠦ᠂ ᠡᠨᠡ ᠠᠵᠢᠯ ᠢ ᠒᠐᠒᠒ ᠣᠨ ᠳᠤ ᠰᠠᠨᠠᠭᠠᠴᠢᠯᠠᠵᠤ᠂ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠬᠥᠭᠵᠢᠯ ᠦᠨ ᠰᠠᠩ ᠤᠨ ᠳᠡᠮᠵᠢᠯᠭᠡ ᠪᠡᠷ ᠒᠐᠒᠓ ᠣᠨ ᠳᠤ ᠪᠠᠷᠢᠭᠰᠠᠨ ᠭᠡᠵᠦ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠲᠤᠰ ᠵᠢᠱᠢᠶ᠎ᠡ ᠨᠢ ᠮᠠᠯᠴᠢᠳ ᠬᠡᠷᠡᠭᠴᠡᠭᠡ ᠪᠡᠨ ᠲᠣᠭᠲᠠᠭᠠᠵᠤ᠂ ᠤᠰᠤᠨ ᠤ ᠠᠵᠢᠯ ᠢ ᠬᠠᠮᠲᠤᠪᠠᠷ ᠲᠥᠯᠥᠪᠯᠡᠬᠦ ᠨᠢ ᠴᠢᠬᠤᠯᠠ ᠪᠣᠯᠣᠬᠤ ᠶᠢ ᠦᠵᠡᠭᠦᠯᠳᠡᠭ᠃',
