      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠪᠡᠯᠴᠢᠭᠡᠷ ᠦᠨ ᠲᠠᠯᠠᠭᠠᠷᠬᠢ ᠒᠐᠑᠕ ᠣᠨ ᠤ ᠬᠠᠮᠲᠤᠷᠠᠭᠰᠠᠨ ᠰᠤᠳᠤᠯᠭᠠᠨ ᠤ ᠲᠠᠶᠢᠯᠤᠩ ᠳᠤ᠂ ᠭᠠᠵᠠᠷ ᠳᠡᠭᠡᠷᠡᠬᠢ ᠬᠡᠮᠵᠢᠯᠲᠡ᠂ ᠠᠯᠤᠰ ᠠᠴᠠ ᠠᠵᠢᠭᠯᠠᠬᠤ ᠮᠡᠳᠡᠭᠡ ᠪᠠ ᠮᠠᠯᠴᠢᠳ ᠤᠨ ᠠᠵᠢᠭᠯᠠᠯᠲᠠ ᠶᠢ ᠬᠣᠰᠯᠠᠭᠤᠯᠬᠤ ᠶᠢ ᠣᠨᠴᠣᠯᠠᠵᠠᠢ᠃ ᠨᠢᠭᠡ ᠭᠠᠵᠠᠷ ᠢ ᠣᠯᠠᠨ ᠵᠢᠯ ᠳᠠᠪᠲᠠᠨ ᠬᠡᠮᠵᠢᠬᠦ ᠨᠢ ᠬᠤᠪᠢᠷᠠᠯᠲᠠ ᠶᠢ ᠲᠠᠨᠢᠬᠤ ᠳᠤ ᠲᠤᠰᠠᠲᠠᠢ᠃',
        'ᠪᠠᠶᠠᠨᠬᠣᠩᠭᠣᠷ ᠤᠨ ᠑᠙᠙᠔ ᠣᠨ ᠠᠴᠠ ᠒᠐᠑᠓ ᠣᠨ ᠤ ᠳᠠᠪᠲᠠᠭᠰᠠᠨ ᠠᠵᠢᠭᠯᠠᠯᠲᠠ ᠳᠤ᠂ ᠤᠷᠭᠤᠮᠠᠯ ᠤᠨ ᠨᠡᠶᠢᠲᠡ ᠬᠡᠮᠵᠢᠶ᠎ᠡ ᠶᠡᠬᠡ ᠬᠤᠪᠢᠷᠠᠬᠤ ᠦᠭᠡᠢ ᠪᠠᠶᠢᠬᠤ ᠳᠤ ᠴᠤ ᠵᠦᠢᠯ ᠦᠨ ᠪᠦᠷᠢᠳᠦᠯ ᠬᠤᠪᠢᠷᠠᠵᠤ ᠪᠣᠯᠬᠤ ᠶᠢ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠥᠪᠥᠯᠵᠢᠶ᠎ᠡ ᠳᠦ ᠣᠶᠢᠷ᠎ᠠ ᠡᠰᠡᠬᠦ ᠪᠠ ᠪᠠᠶᠢᠭᠠᠯᠢ ᠶᠢᠨ ᠪᠦᠰᠡ ᠴᠤ ᠦᠷ᠎ᠡ ᠳ᠋ᠦᠩ ᠳᠦ ᠨᠥᠯᠥᠭᠡᠯᠳᠡᠭ᠃ ᠲᠡᠶᠢᠮᠦ ᠡᠴᠡ ᠭᠠᠭᠴᠠ ᠨᠢᠭᠡ ᠲᠣᠭ᠎ᠠ ᠪᠠᠷ ᠪᠦᠬᠦ ᠪᠡᠯᠴᠢᠭᠡᠷ ᠢ ᠲᠥᠯᠥᠭᠡᠯᠡᠭᠦᠯᠵᠦ ᠪᠣᠯᠬᠤ ᠦᠭᠡᠢ᠃',
      ],
      sources: [
        {
          url: 'https://warnercnr.colostate.edu/wp-content/uploads/sites/2/2017/09/ENG_MOR2-Policy-Brief-1-Tipping-Point_6.1.15FINAL.pdf',
          title: 'ᠪᠡᠯᠴᠢᠭᠡᠷ ᠦᠨ ᠲᠥᠯᠥᠪ ᠦᠨ ᠰᠤᠳᠤᠯᠭ᠎ᠠ',
          organization: 'ᠺᠣᠯᠣᠷᠠᠳᠣ ᠮᠤᠵᠢ ᠶᠢᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ',
          nameMn: 'ᠺᠣᠯᠣᠷᠠᠳᠣ ᠮᠤᠵᠢ ᠶᠢᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ',
          originalTitle:
            'MOR2 Policy Brief No.1, Are Mongolian Rangelands at a Tipping Point?,1June2015',
          originalOrganization:
            'Mongolian Rangelands and Resilience research project; Colorado State University and Mongolian partners',
        },
      ],
      reviewNeeds:
        'ᠡᠬᠢ ᠬᠡᠯᠡᠲᠡᠨ ᠨᠠᠶᠢᠷᠠᠭᠤᠯᠭ᠎ᠠ᠂ ᠵᠥᠪ ᠪᠢᠴᠢᠯᠭᠡ ᠪᠠ ᠣᠨᠣᠭᠠᠭᠰᠠᠨ ᠨᠡᠷ᠎ᠡ ᠶᠢ ᠬᠢᠨᠠᠬᠤ ᠱᠠᠭᠠᠷᠳᠠᠯᠭ᠎ᠠ ᠲᠠᠢ᠃',
