      summary:
        'ᠰᠠᠷᠢᠳᠠᠭ ᠬᠡᠶᠢᠳ ᠦᠨ ᠮᠠᠯᠲᠠᠯᠲᠠ ᠨᠢ ᠵᠠᠨᠠᠪᠠᠵᠠᠷ ᠤᠨ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠤᠷᠠᠯᠢᠭ ᠪᠠ ᠡᠳ᠋ ᠠᠬᠤᠢ ᠶᠢ ᠪᠣᠳᠠᠲᠤ ᠣᠯᠳᠠᠪᠤᠷᠢ ᠪᠠᠷ ᠲᠠᠨᠢᠭᠤᠯᠵᠠᠢ᠃',
      body: [
        'ᠲᠥᠪ ᠠᠶᠢᠮᠠᠭ ᠤᠨ ᠡᠷᠳᠡᠨᠢ ᠰᠤᠮᠤᠨ ᠳᠠᠬᠢ ᠰᠠᠷᠢᠳᠠᠭ ᠤᠨ ᠲᠤᠭᠤᠷᠢ ᠶᠢ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠰᠤᠳᠤᠯᠤᠭᠴᠢᠳ ᠵᠠᠨᠠᠪᠠᠵᠠᠷ ᠤᠨ ᠑᠖᠕᠔–᠑᠖᠘᠖ ᠣᠨ ᠳᠤ ᠪᠠᠷᠢᠭᠤᠯᠤᠭᠰᠠᠨ ᠨᠣᠮ ᠤᠨ ᠶᠡᠬᠡ ᠬᠦᠷᠢᠶ᠎ᠡ ᠲᠡᠢ ᠬᠣᠯᠪᠣᠵᠠᠢ᠃ ᠪᠠᠷᠢᠯᠭ᠎ᠠ᠂ ᠰᠤᠪᠤᠷᠭ᠎ᠠ᠂ ᠴᠢᠯᠠᠭᠤᠨ ᠪᠠ ᠱᠣᠷᠣᠭᠠᠨ ᠬᠡᠷᠡᠮ ᠦᠨ ᠮᠥᠷ ᠢ ᠬᠠᠮᠲᠤ ᠪᠦᠷᠢᠳᠬᠡᠵᠡᠢ᠃',
        'ᠮᠠᠯᠲᠠᠯᠲᠠ ᠠᠴᠠ ᠣᠯᠠᠨ ᠪᠤᠷᠬᠠᠨ ᠤ ᠳᠦᠷᠰᠦ᠂ ᠱᠠᠭᠠᠵᠠᠨ᠂ ᠵᠣᠭᠣᠰ ᠪᠠ ᠥᠳᠥᠷ ᠲᠤᠲᠤᠮ ᠤᠨ ᠡᠳᠯᠡᠯ ᠣᠯᠵᠠᠢ᠃ ᠱᠠᠪᠠᠷ ᠳᠦᠷᠰᠦ ᠶᠢ ᠪᠢᠴᠢᠭ ᠦᠨ ᠰᠤᠷᠪᠤᠯᠵᠢ ᠲᠠᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠬᠤ ᠰᠤᠳᠤᠯᠭ᠎ᠠ ᠨᠢ ᠵᠠᠨᠠᠪᠠᠵᠠᠷ ᠤᠨ ᠱᠠᠰᠢᠨ ᠤ ᠬᠣᠯᠪᠣᠭ᠎ᠠ ᠶᠢ ᠭᠠᠭᠴᠠ ᠨᠢᠭᠡ ᠤᠷᠤᠰᠬᠠᠯ ᠢᠶᠠᠷ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠬᠤ ᠠᠴᠠ ᠢᠯᠡᠭᠦᠦ ᠨᠠᠷᠢᠨ ᠰᠤᠳᠤᠯᠬᠤ ᠬᠡᠷᠡᠭᠲᠡᠢ ᠶᠢ ᠰᠠᠨᠠᠭᠤᠯᠳᠠᠭ᠃',
      ],
