      body: [
        'ᠯᠤᠪᠰᠠᠩ ᠤᠨ ᠷᠠᠭᠴᠠᠭ᠎ᠠ ᠑᠙᠓᠕ ᠣᠨ ᠤ ᠨᠢᠭᠡᠳᠦᠭᠡᠷ ᠰᠠᠷ᠎ᠠ ᠳᠤ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠷᠠᠳᠢᠣ᠋ ᠳᠤ ᠣᠷᠣᠵᠠᠢ᠃ ᠲᠤᠰ ᠪᠠᠶᠢᠭᠤᠯᠤᠯᠭ᠎ᠠ ᠶᠢᠨ ᠲᠡᠦᠬᠡᠨ ᠳᠦ ᠲᠡᠭᠦᠨ ᠢ ᠠᠩᠬᠠᠨ ᠤ ᠡᠮᠡᠭᠲᠡᠢ ᠨᠡᠪᠲᠡᠷᠡᠭᠦᠯᠦᠭᠴᠢ ᠭᠡᠵᠦ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠲᠡᠷᠡ ᠦᠶ᠎ᠡ ᠳᠦ ᠷᠠᠳᠢᠣ᠋ ᠴᠥᠭᠡᠨ ᠠᠵᠢᠯᠲᠠᠨ᠂ ᠨᠢᠭᠡ ᠰᠲᠦᠳᠢ ᠲᠡᠢ ᠪᠠᠶᠢᠵᠠᠢ᠃',
        '᠑᠙᠕᠔ ᠣᠨ ᠳᠤ ᠷᠠᠳᠢᠣ᠋ ᠶᠢᠨ ᠳᠠᠭᠤ ᠬᠥᠭᠵᠢᠮ ᠦᠨ ᠠᠯᠲᠠᠨ ᠰᠠᠩ ᠬᠥᠮᠥᠷᠭᠡ ᠪᠦᠷᠢᠯᠳᠦᠨ᠂ ᠭᠣᠩᠴᠢᠭᠰᠤᠮᠯ᠎ᠠ ᠪᠢᠴᠢᠯᠭᠡ ᠶᠢ ᠡᠮᠬᠢᠳᠬᠡᠨ ᠠᠩᠭᠢᠯᠠᠵᠠᠢ᠃ ᠬᠣᠵᠢᠮ ᠷᠠᠭᠴᠠᠭ᠎ᠠ ᠲᠡᠷᠡ ᠰᠠᠩ ᠤᠨ ᠠᠩᠬᠠᠨ ᠤ ᠡᠷᠬᠢᠯᠡᠭᠴᠢ ᠪᠣᠯᠵᠠᠢ᠃ ᠰᠠᠩ ᠳᠤ ᠬᠥᠳᠡᠭᠡ ᠣᠷᠣᠨ ᠠᠴᠠ ᠪᠢᠴᠢᠵᠦ ᠠᠪᠤᠭᠰᠠᠨ ᠳᠠᠭᠤ᠂ ᠬᠥᠭᠵᠢᠮ᠂ ᠵᠦᠵᠦᠭ ᠴᠦ ᠣᠷᠣᠵᠠᠢ᠃',
      ],
