      body: [
        '᠑᠖᠓᠙ ᠣᠨ ᠳᠤ ᠵᠠᠨᠠᠪᠠᠵᠠᠷ ᠲᠤ ᠵᠣᠷᠢᠭᠤᠯᠵᠤ ᠪᠠᠶᠢᠭᠤᠯᠤᠭᠰᠠᠨ ᠥᠷᠭᠦᠭᠡ ᠠᠩᠬ᠎ᠠ ᠳᠠᠭᠠᠨ ᠨᠡᠭᠦᠳᠡᠭ ᠪᠠᠶᠢᠵᠠᠢ᠃ ᠬᠣᠵᠢᠮ ᠤᠨ ᠶᠡᠬᠡ ᠬᠦᠷᠢᠶ᠎ᠡ ᠳᠦ ᠬᠤᠪᠢᠯᠭᠠᠨ ᠪᠣᠭᠳᠠ ᠰᠠᠭᠤᠵᠤ᠂ ᠱᠠᠰᠢᠨ ᠤ ᠰᠤᠷᠭᠠᠯᠲᠠ᠂ ᠰᠦᠮ᠎ᠡ ᠬᠡᠶᠢᠳ ᠪᠠ ᠮᠥᠷᠭᠥᠯᠴᠢᠳ ᠲᠥᠪᠯᠡᠷᠡᠵᠡᠢ᠃',
        'ᠰᠤᠳᠤᠯᠤᠭᠴᠢ ᠲᠧᠯᠧᠺᠢ ᠬᠦᠷᠢᠶ᠎ᠡ ᠑᠗᠗᠘ ᠣᠨ ᠠᠴᠠ ᠣᠳᠣᠭᠠᠨ ᠤ ᠤᠯᠠᠭᠠᠨᠪᠠᠭᠠᠲᠤᠷ ᠤᠨ ᠬᠥᠨᠳᠡᠢ ᠳᠦ ᠪᠠᠶᠢᠵᠤ᠂ ᠑᠘᠕᠕ ᠣᠨ ᠳᠤ ᠪᠠᠶᠢᠩᠭᠤ ᠶᠢᠨ ᠪᠠᠶᠢᠷᠢ ᠳᠠᠭᠠᠨ ᠲᠣᠭᠲᠠᠭᠰᠠᠨ ᠢ ᠶᠢᠯᠭᠠᠵᠤ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃ ᠲᠤᠰ ᠬᠣᠲᠠ ᠨᠢ ᠪᠠᠰᠠ ᠴᠢᠩ ᠤᠯᠤᠰ ᠤᠨ ᠵᠠᠬᠢᠷᠭ᠎ᠠ᠂ ᠣᠷᠣᠰ ᠪᠠ ᠬᠢᠲᠠᠳ ᠤᠨ ᠬᠤᠳᠠᠯᠳᠤᠭᠠᠨ ᠤ ᠲᠥᠪ ᠪᠠᠶᠢᠵᠠᠢ᠃',
      ],
