      summary:
        'ᠪᠤᠷᠢᠶᠠᠳ ᠯᠠᠮᠠ ᠠᠭᠸᠠᠩ ᠳᠣᠷᠵᠢ ᠱᠠᠰᠢᠨ᠂ ᠡᠯᠴᠢᠨ ᠬᠠᠷᠢᠯᠴᠠᠭ᠎ᠠ ᠪᠠ ᠤᠷᠠᠨ ᠳᠠᠷᠬᠠᠨ ᠤ ᠠᠵᠢᠯ ᠢ ᠬᠣᠯᠪᠣᠵᠤ ᠪᠠᠶᠢᠵᠠᠢ᠃',
      body: [
        'ᠠᠭᠸᠠᠩ ᠳᠣᠷᠵᠢ ᠶᠢᠨ ᠑᠙᠐᠑ ᠣᠨ ᠳᠤ ᠣᠷᠣᠰ ᠤᠨ ᠭᠠᠳᠠᠭᠠᠳᠤ ᠬᠡᠷᠡᠭ ᠦᠨ ᠰᠠᠶᠢᠳ ᠲᠤ ᠪᠢᠴᠢᠭᠰᠡᠨ ᠵᠠᠬᠢᠳᠠᠯ ᠠᠷᠬᠢᠪ ᠤᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠪᠤᠢ᠃ ᠲᠡᠷᠡ ᠵᠠᠬᠢᠳᠠᠯ ᠳᠤ ᠣᠷᠣᠰ ᠪᠠ ᠲᠥᠪᠡᠳ ᠦᠨ ᠬᠠᠷᠢᠯᠴᠠᠭ᠎ᠠ ᠶᠢ ᠲᠣᠭᠲᠠᠭᠠᠬᠤ ᠳᠤ ᠲᠤᠰᠠᠯᠠᠬᠤ ᠰᠠᠨᠠᠯ ᠢᠶᠠᠨ ᠢᠯᠡᠷᠬᠡᠶᠢᠯᠡᠭᠰᠡᠨ ᠭᠡᠵᠦ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃',
        'ᠲᠡᠭᠦᠨ ᠦ ᠰᠠᠨᠠᠭᠠᠴᠢᠯᠠᠭ᠎ᠠ ᠪᠠᠷ ᠫᠧᠲ᠋ᠧᠷᠪᠦᠷᠭ ᠲᠦ ᠪᠤᠳᠳᠠ ᠶᠢᠨ ᠱᠠᠰᠢᠨ ᠤ ᠳᠠᠴᠠᠩ ᠪᠠᠷᠢᠭᠳᠠᠵᠠᠢ᠃ ᠲᠡᠷᠡ ᠪᠤᠷᠢᠶᠠᠳ ᠠᠴᠠ ᠤᠷᠠᠴᠤᠳ ᠢ ᠤᠷᠢᠭᠰᠠᠨ ᠤ ᠳᠣᠲᠣᠷ᠎ᠠ ᠵᠢᠷᠤᠭᠠᠴᠢ ᠯᠠᠮᠠ ᠣᠰᠣᠷ ᠪᠤᠳᠠᠶᠧᠸ ᠪᠠᠶᠢᠵᠠᠢ᠃ ᠡᠭᠦᠨ ᠡᠴᠡ ᠲᠡᠭᠦᠨ ᠦ ᠬᠠᠷᠢᠯᠴᠠᠭ᠎ᠠ ᠨᠢ ᠭᠠᠭᠴᠠ ᠡᠯᠴᠢᠨ ᠦ ᠠᠵᠢᠯ ᠢᠶᠠᠷ ᠬᠢᠵᠠᠭᠠᠷᠯᠠᠭᠳᠠᠬᠤ ᠦᠭᠡᠢ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠢ ᠬᠠᠷᠠᠵᠤ ᠪᠣᠯᠣᠨ᠎ᠠ᠃',
      ],
