      reviewNeeds:
        'ᠡᠬᠢ ᠬᠡᠯᠡᠲᠡᠨ ᠨᠠᠶᠢᠷᠠᠭᠤᠯᠭ᠎ᠠ᠂ ᠵᠥᠪ ᠪᠢᠴᠢᠯᠭᠡ ᠪᠠ ᠣᠨᠣᠭᠠᠭᠰᠠᠨ ᠨᠡᠷ᠎ᠡ ᠶᠢ ᠬᠢᠨᠠᠯᠲᠠ ᠳᠤ ᠣᠷᠣᠭᠤᠯᠬᠤ ᠱᠠᠭᠠᠷᠳᠠᠯᠭ᠎ᠠ ᠲᠠᠢ ᠨᠣᠣᠷᠣᠭ᠃',
