          url: 'https://archive.unesco-ichcap.org/eng/ek/sub2/pdf_down/chapter05/4.%20Religious%20Rites/06.%20The%20ceremony%20of%20consecrating%20animals.pdf',
          nameMn: 'ᠠᠽᠢ ᠨᠣᠮᠣᠭᠤᠨ ᠳᠠᠯᠠᠢ ᠶᠢᠨ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠥᠪ',
          organization: 'ᠠᠽᠢ ᠨᠣᠮᠣᠭᠤᠨ ᠳᠠᠯᠠᠢ ᠶᠢᠨ ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠲᠥᠪ',
