          organization: 'ᠨᠡᠭᠦᠳᠡᠯᠯᠡᠳᠡᠭ ᠵᠡᠷᠯᠢᠭ ᠠᠮᠢᠲᠠᠨ ᠢ ᠬᠠᠮᠠᠭᠠᠯᠠᠬᠤ ᠺᠣᠨᠸᠧᠨᠼᠢ',
          nameMn: 'ᠨᠡᠭᠦᠳᠡᠯᠯᠡᠳᠡᠭ ᠵᠡᠷᠯᠢᠭ ᠠᠮᠢᠲᠠᠨ ᠢ ᠬᠠᠮᠠᠭᠠᠯᠠᠬᠤ ᠺᠣᠨᠸᠧᠨᠼᠢ',
