          organization: 'ᠣᠷᠣᠰ ᠤᠨ ᠡᠷᠲᠡᠨ ᠰᠤᠳᠤᠯᠤᠯ ᠤᠨ ᠬᠦᠷᠢᠶᠡᠯᠡᠩ',
          nameMn: 'ᠣᠷᠣᠰ ᠤᠨ ᠡᠷᠲᠡᠨ ᠰᠤᠳᠤᠯᠤᠯ ᠤᠨ ᠬᠦᠷᠢᠶᠡᠯᠡᠩ',
