          title: 'ᠬᠥᠬᠡ ᠬᠣᠲᠠ ᠶᠢᠨ ᠴᠠᠭᠠᠨ ᠰᠤᠪᠤᠷᠭ᠎ᠠ',
          organization: 'ᠰᠠᠶᠢᠬᠠᠨ ᠲᠣᠭᠣᠷᠢᠭ ᠤᠨ ᠵᠠᠰᠠᠭ ᠤᠨ ᠣᠷᠳᠤᠨ',
          nameMn: 'ᠰᠠᠶᠢᠬᠠᠨ ᠲᠣᠭᠣᠷᠢᠭ ᠤᠨ ᠵᠠᠰᠠᠭ ᠤᠨ ᠣᠷᠳᠤᠨ',
