      summary: 'ᠲᠣᠯᠢᠨ ᠤ ᠲᠡᠮᠳᠡᠭᠯᠡᠯ ᠨᠢ ᠦᠭᠡ ᠶᠢᠨ ᠬᠡᠷᠡᠭᠯᠡᠭᠡ ᠶᠢ ᠲᠣᠳᠣᠷᠠᠭᠤᠯᠳᠠᠭ᠃',
      body: [
        'ᠶᠡᠬᠡ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠲᠣᠯᠢ ᠳᠤ ᠨᠤᠲᠤᠭ ᠤᠨ ᠠᠶᠠᠯᠭᠤ᠂ ᠬᠠᠭᠤᠴᠢᠷᠠᠭᠰᠠᠨ ᠦᠭᠡ᠂ ᠬᠦᠨᠳᠦᠳᠬᠡᠯ ᠦᠨ ᠦᠭᠡ ᠪᠠ ᠨᠡᠷ᠎ᠡ ᠲᠣᠮᠢᠶ᠎ᠠ ᠵᠡᠷᠭᠡ ᠠᠩᠭᠢᠯᠠᠯ ᠪᠤᠢ᠃ ᠡᠳᠡᠭᠡᠷ ᠨᠢ ᠦᠭᠡ ᠶᠢ ᠶᠠᠮᠠᠷ ᠣᠷᠴᠢᠨ ᠳᠤ ᠬᠡᠷᠡᠭᠯᠡᠳᠡᠭ ᠢ ᠵᠠᠭᠠᠳᠠᠭ᠃',
        'ᠲᠣᠯᠢᠨ ᠤ ᠠᠷᠭᠠᠴᠢᠯᠠᠯ ᠳᠤ ᠨᠤᠲᠤᠭ ᠤᠨ ᠦᠭᠡ ᠶᠢᠨ ᠠᠶᠠᠯᠭᠤᠨ ᠤ ᠬᠠᠮᠢᠶᠠᠯ ᠢ ᠵᠠᠭᠠᠬᠤ ᠪᠠᠷ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃ ᠨᠢᠭᠡ ᠦᠭᠡ ᠶᠢ ᠪᠦᠬᠦ ᠨᠤᠲᠤᠭ ᠪᠠ ᠪᠦᠬᠦ ᠨᠠᠶᠢᠷᠠᠭᠤᠯᠭ᠎ᠠ ᠳᠤ ᠠᠳᠠᠯᠢ ᠲᠣᠬᠢᠷᠠᠨ᠎ᠠ ᠭᠡᠵᠦ ᠦᠵᠡᠯᠭᠦᠢ᠂ ᠲᠡᠮᠳᠡᠭᠯᠡᠯ ᠪᠠ ᠵᠢᠱᠢᠶ᠎ᠠ ᠶᠢ ᠬᠠᠮᠲᠤ ᠤᠩᠰᠢᠨ᠎ᠠ᠃',
      ],
