      summary: 'ᠵᠡᠰ ᠪᠠ ᠮᠣᠳᠣ ᠪᠠᠷ ᠬᠢᠭᠰᠡᠨ ᠪᠠᠷ ᠨᠢ ᠲᠠᠷᠨᠢ ᠶᠢ ᠣᠯᠣᠨᠲᠠ ᠬᠡᠪᠯᠡᠬᠦ ᠳᠦ ᠵᠣᠷᠢᠤᠯᠠᠭᠳᠠᠵᠠᠢ᠃',
      body: [
        'ᠪᠣᠭᠳᠠ ᠬᠠᠭᠠᠨ ᠤ ᠣᠷᠳᠣᠨ ᠮᠦᠽᠧᠢ ᠡᠨᠡ ᠪᠠᠷ ᠢ ᠠᠷᠪᠠᠨ ᠨᠠᠶᠢᠮᠠ᠂ ᠠᠷᠪᠠᠨ ᠶᠢᠰᠦᠳᠦᠭᠡᠷ ᠵᠠᠭᠤᠨ ᠳᠤ ᠬᠠᠮᠢᠶᠠᠭᠤᠯᠵᠠᠢ᠃ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠲᠡᠭᠦᠨ ᠦ ᠡᠳ ᠢ ᠵᠡᠰ ᠪᠠ ᠮᠣᠳᠣ ᠭᠡᠵᠦ ᠵᠢᠭᠠᠵᠠᠢ᠃ ᠡᠨᠡ ᠨᠢ ᠬᠡᠪᠯᠡᠯ ᠦᠨ ᠪᠠᠷ ᠳᠤ ᠲᠥᠮᠦᠷᠯᠢᠭ ᠡᠳ ᠬᠡᠷᠡᠭᠯᠡᠵᠦ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠤ ᠵᠢᠱᠢᠶ᠎ᠡ ᠶᠤᠮ᠃',
        'ᠮᠦᠽᠧᠢ ᠶᠢᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠳᠤ ᠵᠢᠷᠭᠤᠭᠠᠨ ᠦᠶ᠎ᠡᠲᠦ ᠲᠠᠷᠨᠢ ᠶᠢ ᠮᠢᠩᠭᠠᠨ ᠤᠳᠠᠭ᠎ᠠ ᠰᠡᠶᠢᠯᠵᠡᠢ ᠭᠡᠵᠡᠢ᠃ ᠬᠡᠪᠯᠡᠭᠰᠡᠨ ᠴᠠᠭᠠᠰᠤ ᠶᠢ ᠮᠠᠨᠢ ᠶᠢᠨ ᠬᠦᠷᠳᠦᠨ ᠳᠦ ᠬᠡᠷᠡᠭᠯᠡᠬᠦ ᠶᠢ ᠳᠤᠷᠠᠳᠴᠠᠢ᠃ ᠲᠢᠶᠢᠮᠦ ᠡᠴᠡ ᠡᠨᠡ ᠡᠳ ᠢ ᠰᠤᠳᠤᠯᠬᠤ ᠳᠤ ᠪᠠᠷᠯᠠᠬᠤ ᠠᠷᠭ᠎ᠠ ᠪᠠ ᠱᠠᠰᠢᠨ ᠤ ᠬᠡᠷᠡᠭᠯᠡᠭᠡ ᠶᠢ ᠬᠠᠮᠲᠤ ᠠᠪᠴᠤ ᠦᠵᠡᠨ᠎ᠡ᠃',
      ],
