      body: [
        'ᠦᠨᠳᠦᠰᠦᠨ ᠦ ᠮᠦᠽᠧᠢ ᠶᠢᠨ ᠬᠣᠷᠢᠳᠤᠭᠠᠷ ᠵᠠᠭᠤᠨ ᠤ ᠦᠢᠴᠦᠦᠷ ᠦᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠮᠣᠳᠣ ᠪᠤᠶᠤ ᠶᠠᠰᠤᠨ ᠤᠷᠲᠤ ᠨᠠᠷᠢᠨ ᠬᠥᠵᠢᠷ ᠦᠳ ᠢ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃ ᠠᠷᠰᠯᠠᠨ᠂ ᠪᠠᠷᠰ᠂ ᠪᠤᠭᠤ᠂ ᠲᠠᠤᠯᠠᠢ ᠪᠠ ᠰᠢᠪᠠᠭᠤ ᠵᠡᠷᠭᠡ ᠠᠮᠢᠲᠠᠨ ᠤ ᠳᠦᠷᠰᠦ ᠰᠡᠶᠢᠯᠵᠡᠢ᠃',
        'ᠬᠥᠵᠢᠷ ᠦᠨ ᠲᠣᠭ᠎ᠠ ᠪᠠ ᠣᠨᠣᠭ᠎ᠠ ᠨᠢ ᠲᠡᠩᠴᠡᠭᠦ ᠪᠢᠰᠢ᠃ ᠮᠦᠽᠧᠢ ᠨᠢᠭᠡ ᠠᠷᠰᠯᠠᠨ ᠵᠢᠷᠠᠨ ᠳᠥᠷᠪᠡᠨ ᠣᠨᠣᠭ᠎ᠠ᠂ ᠬᠠᠷᠢᠨ ᠵᠢᠷᠠᠨ ᠳᠥᠷᠪᠡᠨ ᠰᠢᠪᠠᠭᠤ ᠲᠤᠰ ᠪᠦᠷᠢ ᠨᠢᠭᠡ ᠣᠨᠣᠭ᠎ᠠ ᠲᠠᠢ ᠭᠡᠵᠦ ᠵᠢᠱᠢᠶᠡᠯᠡᠵᠡᠢ᠃ ᠲᠣᠭᠯᠠᠭᠴᠢᠳ ᠱᠣᠭ᠎ᠠ ᠣᠷᠬᠢᠵᠤ ᠬᠥᠵᠢᠷ ᠠᠪᠤᠨ᠂ ᠡᠴᠦᠰ ᠲᠦ ᠣᠨᠣᠭ᠎ᠠ ᠪᠠᠨ ᠨᠡᠮᠡᠵᠦ ᠲᠣᠭᠠᠯᠠᠳᠠᠭ᠃',
      ],
