        'ᠮᠣᠳᠣᠨ ᠴᠠᠴᠤᠯ ᠤᠨ ᠨᠦᠬᠡ᠂ ᠰᠡᠶᠢᠯᠦᠮᠡᠯ ᠪᠠ ᠬᠠᠳᠠᠭ ᠨᠢ ᠲᠠᠬᠢᠯ ᠤᠨ ᠬᠡᠷᠡᠭᠰᠡᠯ ᠦᠨ ᠪᠦᠲᠦᠴᠡ ᠶᠢ ᠬᠠᠷᠠᠭᠤᠯᠤᠨ᠎ᠠ᠃',
      body: [
        'ᠦᠨᠳᠦᠰᠦᠨ ᠦ ᠮᠦᠽᠧᠢ ᠶᠢᠨ ᠡᠨᠡ ᠮᠣᠳᠣᠨ ᠴᠠᠴᠤᠯ ᠠᠷᠪᠠᠨ ᠶᠢᠰᠦ᠂ ᠬᠣᠷᠢᠳᠤᠭᠠᠷ ᠵᠠᠭᠤᠨ ᠳᠤ ᠬᠣᠯᠪᠣᠭᠳᠠᠨ᠎ᠠ᠃ ᠬᠠᠪᠲᠠᠭᠠᠢ ᠲᠣᠯᠣᠭᠠᠢ ᠳᠤ ᠨᠢ ᠶᠢᠰᠦᠨ ᠬᠣᠨᠬᠣᠷ ᠪᠤᠢ᠃ ᠢᠰᠢᠨ ᠦ ᠬᠣᠶᠠᠷ ᠲᠠᠯ᠎ᠠ ᠳᠤ ᠠᠷᠪᠠᠨ ᠬᠣᠶᠠᠷ ᠵᠢᠯ ᠦᠨ ᠠᠮᠢᠲᠠᠨ ᠤ ᠳᠦᠷᠰᠦ ᠰᠡᠶᠢᠯᠵᠡᠢ᠃',
        'ᠳᠡᠭᠡᠳᠦ ᠬᠡᠰᠡᠭ ᠲᠦ ᠶᠢᠰᠦᠨ ᠰᠢᠷᠭ᠎ᠠ ᠮᠣᠷᠢᠨ ᠤ ᠳᠦᠷᠰᠦ᠂ ᠢᠰᠢᠨ ᠦ ᠦᠵᠦᠭᠦᠷ ᠲᠦ ᠣᠴᠢᠷ ᠤᠨ ᠬᠡᠭᠡ ᠪᠤᠢ᠃ ᠱᠠᠷ᠎ᠠ᠂ ᠴᠠᠭᠠᠨ ᠪᠠ ᠬᠥᠬᠡ ᠬᠠᠳᠠᠭ ᠤᠶᠠᠵᠠᠢ᠃ ᠡᠳᠡᠭᠡᠷ ᠣᠨᠴᠠᠯᠢᠭ ᠨᠢ ᠡᠨᠡ ᠦᠵᠡᠭᠦᠯᠦᠩ ᠦ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠲᠤᠯᠭᠤᠭᠤᠷᠢᠯᠠᠭᠰᠠᠨ ᠲᠣᠳᠣᠷᠬᠠᠶᠢᠯᠠᠯᠲᠠ ᠶᠤᠮ᠃',
      ],
