          organization: 'ᠮᠣᠩᠭᠣᠯ᠂ ᠪᠤᠳᠳᠠ ᠪᠠ ᠲᠥᠪᠡᠳ ᠰᠤᠳᠤᠯᠤᠯ ᠤᠨ ᠬᠦᠷᠢᠶᠡᠯᠡᠩ',
