          organization: 'ᠡᠷᠭᠦᠨ᠎ᠡ ᠶᠢᠨ ᠮᠤᠽᠧᠢ',
          nameMn: 'ᠡᠷᠭᠦᠨ᠎ᠡ ᠶᠢᠨ ᠮᠤᠽᠧᠢ',
