          organization: 'ᠥᠪᠥᠷ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠲᠡᠦᠬᠡᠨ ᠦ ᠰᠤᠳᠤᠯᠭᠠᠨ ᠤ ᠭᠠᠵᠠᠷ',
          nameMn: 'ᠥᠪᠥᠷ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠣᠷᠣᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠲᠡᠦᠬᠡᠨ ᠦ ᠰᠤᠳᠤᠯᠭᠠᠨ ᠤ ᠭᠠᠵᠠᠷ',
