          url: 'https://www.cambridge.org/core/journals/journal-of-the-royal-asiatic-society/article/abs/preconditions-to-becoming-a-judge-yarguci-in-mongoliran/7A08880471FCD30202C0775E75B57409',
          title: 'ᠠᠽᠢ ᠰᠤᠳᠤᠯᠤᠯ ᠤᠨ ᠨᠡᠶᠢᠭᠡᠮᠯᠢᠭ',
