          nameMn: 'ᠡᠳ᠋ᠢᠨᠪᠤᠷᠭ ᠦᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ ᠶᠢᠨ ᠬᠡᠪᠯᠡᠯ',
