      summary: '᠑᠒᠗᠕ ᠣᠨ ᠤ ᠳᠦᠷᠢᠮ ᠨᠢ ᠣᠳᠣᠨ ᠣᠷᠣᠨ ᠰᠤᠳᠤᠯᠤᠭᠴᠢ ᠶᠢ ᠬᠡᠷᠬᠢᠨ ᠪᠡᠯᠡᠳᠬᠡᠵᠦ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠢ ᠦᠵᠡᠭᠦᠯᠦᠨ᠎ᠡ᠃',
      body: [
        'ᠶᠤᠸᠠᠨ ᠤ ᠣᠳᠣᠨ ᠣᠷᠣᠨ ᠤ ᠠᠯᠪᠠᠨ ᠤ ᠑᠒᠗᠕ ᠣᠨ ᠤ ᠳᠦᠷᠢᠮ «ᠮᠢ ᠱᠦ ᠵᠢᠶᠠᠨ ᠵᠢ» ᠬᠡᠮᠡᠬᠦ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠦᠯᠡᠳᠡᠵᠡᠢ᠃ ᠲᠡᠭᠦᠨ ᠳᠦ ᠲᠠᠪᠤᠨ ᠰᠠᠯᠪᠤᠷᠢ ᠶᠢᠨ ᠰᠤᠷᠬᠤ ᠨᠣᠮ᠂ ᠰᠢᠯᠭᠠᠯᠲᠠ ᠶᠢᠨ ᠠᠰᠠᠭᠤᠯᠲᠠ ᠪᠠ ᠳᠡᠪᠰᠢᠭᠦᠯᠬᠦ ᠱᠠᠭᠠᠷᠳᠠᠯᠭ᠎ᠠ ᠶᠢ ᠪᠢᠴᠢᠵᠡᠢ᠃ ᠪᠣᠳᠣᠯᠲᠠ᠂ ᠠᠵᠢᠭᠯᠠᠯᠲᠠ ᠪᠠ ᠴᠠᠭ ᠬᠡᠮᠵᠢᠬᠦ ᠠᠵᠢᠯ ᠥᠪᠡᠷ ᠥᠪᠡᠷ ᠦᠨ ᠮᠡᠷᠭᠡᠰᠢᠯ ᠱᠠᠭᠠᠷᠳᠠᠵᠠᠢ᠃',
        'ᠶᠠᠩ ᠴᠢᠶᠣᠣ ᠶᠢᠨ ᠰᠤᠳᠤᠯᠭ᠎ᠠ ᠳᠤ᠂ ᠰᠢᠯᠭᠠᠯᠲᠠ ᠪᠣᠳᠣᠬᠤ ᠴᠢᠳᠠᠪᠤᠷᠢ ᠠᠴᠠ ᠭᠠᠳᠠᠨ᠎ᠠ ᠪᠢᠴᠢᠭ ᠦᠨ ᠴᠢᠳᠠᠪᠤᠷᠢ ᠶᠢ ᠴᠤ ᠦᠨᠡᠯᠡᠳᠡᠭ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠢ ᠣᠨᠴᠠᠯᠠᠵᠠᠢ᠃ ᠭᠡᠷ ᠪᠦᠯᠢ ᠶᠢᠨ ᠮᠡᠳᠡᠯᠭᠡ ᠳᠠᠮᠵᠢᠬᠤ ᠨᠢ ᠴᠢᠬᠤᠯᠠ ᠠᠲᠠᠯ᠎ᠠ᠂ ᠶᠤᠸᠠᠨ ᠤ ᠡᠨᠡ ᠠᠯᠪᠠ ᠵᠠᠠᠪᠠᠯ ᠥᠪ ᠵᠠᠯᠭᠠᠳᠠᠭ ᠪᠢᠰᠢ ᠪᠠᠶᠢᠪᠠ᠃ ᠳᠦᠷᠢᠮ ᠪᠤᠢ ᠭᠡᠳᠡᠭ ᠨᠢ ᠰᠢᠯᠭᠠᠯᠲᠠ ᠪᠦᠷᠢ ᠲᠣᠭᠲᠠᠮᠠᠯ ᠬᠡᠷᠡᠭᠵᠢᠭᠰᠡᠨ ᠦ ᠪᠠᠲᠠᠯᠠᠭ᠎ᠠ ᠪᠢᠰᠢ᠃',
      ],
