      title: 'ᠳᠣᠨᠳᠣᠭᠳᠤᠯᠠᠮ ᠬᠠᠲᠤᠨ ᠤ ᠣᠷᠣ',
      summary: 'ᠮᠣᠳᠣᠨ ᠣᠷᠣᠨ ᠤ ᠪᠦᠲᠦᠴᠡ ᠳᠦ ᠰᠢᠯ᠂ ᠭᠠᠩᠲᠢᠭ ᠪᠠ ᠲᠣᠯᠢ ᠶᠢ ᠬᠣᠰᠣᠯᠠᠭᠤᠯᠵᠠᠢ᠃',
      body: [
        'ᠪᠣᠭᠳᠠ ᠬᠠᠭᠠᠨ ᠤ ᠣᠷᠳᠣᠨ ᠮᠦᠽᠧᠢ ᠳᠣᠨᠳᠣᠭᠳᠤᠯᠠᠮ ᠬᠠᠲᠤᠨ ᠤ ᠣᠷᠣ ᠶᠢ ᠡᠪᠧᠨ ᠮᠣᠳᠣᠨ ᠬᠠᠰᠢᠯᠭᠠᠲᠤ ᠣᠷᠣ ᠭᠡᠵᠦ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠵᠠᠢ᠃ ᠮᠣᠳᠣᠨ ᠬᠡᠰᠡᠭ ᠦᠳ ᠢ ᠣᠨᠢᠰᠣᠨ ᠵᠠᠭᠤᠯᠳᠤᠯ ᠠᠷ ᠨᠢᠭᠡᠳᠬᠡᠵᠦ᠂ ᠭᠠᠳᠠᠷᠭᠤ ᠶᠢ ᠰᠡᠶᠢᠯᠦᠮᠡᠯ ᠬᠡᠭᠡ ᠪᠡᠷ ᠴᠢᠮᠡᠭᠯᠡᠵᠡᠢ᠃',
        'ᠮᠦᠽᠧᠢ ᠠᠷᠪᠠᠨ ᠵᠢᠷᠤᠭᠲᠤ ᠰᠢᠯᠡᠨ ᠴᠣᠩᠬᠣ᠂ ᠨᠠᠶᠢᠮᠠᠨ ᠰᠠᠭᠠᠷᠠᠯ ᠭᠠᠩᠲᠢᠭ ᠰᠢᠭᠢᠳᠭᠡᠭᠡ᠂ ᠭᠤᠷᠪᠠᠨ ᠰᠤᠭᠤᠯᠭ᠎ᠠ ᠪᠠ ᠲᠠᠭᠠᠵᠢᠨ ᠳᠠᠬᠢ ᠳᠥᠴᠢᠨ ᠬᠣᠶᠠᠷ ᠲᠣᠯᠢ ᠶᠢ ᠳᠤᠷᠠᠳᠴᠠᠢ᠃ ᠬᠥᠰᠢᠭᠡᠨ ᠦ ᠳᠡᠭᠡᠳᠦ ᠬᠡᠰᠡᠭ ᠪᠠ ᠭᠣᠣᠯ ᠳᠤ ᠠᠯᠲᠠᠨ ᠤᠲᠠᠰᠤᠨ ᠤ ᠯᠤᠤᠨ ᠬᠡᠭᠡ ᠪᠤᠢ᠃ ᠡᠨᠡ ᠨᠢ ᠣᠷᠳᠣᠨ ᠤ ᠲᠠᠪᠢᠯᠭ᠎ᠠ ᠳᠤ ᠮᠣᠳᠣᠴᠢᠨ ᠪᠠ ᠣᠶᠣᠳᠣᠯᠴᠢᠨ ᠤ ᠠᠵᠢᠯ ᠬᠣᠰᠣᠯᠳᠠᠭ ᠢ ᠦᠵᠡᠭᠦᠯᠦᠨ᠎ᠡ᠃',
      ],
