          title: 'ᠢᠷᠠᠨᠢᠺᠠ ᠨᠡᠪᠲᠡᠷᠬᠡᠢ ᠲᠣᠯᠢ',
          nameMn: 'ᠢᠷᠠᠨᠢᠺᠠ ᠨᠡᠪᠲᠡᠷᠬᠡᠢ ᠲᠣᠯᠢ',
