          nameMn: 'ᠲᠣᠷᠭᠠᠨ ᠵᠠᠮ ᠤᠨ ᠰᠤᠳᠤᠯᠭᠠᠨ ᠤ ᠰᠡᠳᠬᠦᠯ',
          organization: 'ᠲᠣᠷᠭᠠᠨ ᠵᠠᠮ ᠤᠨ ᠰᠤᠳᠤᠯᠭᠠᠨ ᠤ ᠰᠡᠳᠬᠦᠯ',
