      summary:
        '᠑᠙᠙᠐–᠑᠙᠙᠕ ᠣᠨ ᠤ ᠰᠣᠨᠢᠨ ᠤᠳ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠣᠯᠠᠨ ᠳᠠᠭᠤ ᠬᠣᠭᠣᠯᠠᠢ ᠲᠠᠢ ᠬᠡᠪᠯᠡᠯ ᠡᠭᠦᠰᠦᠭᠰᠡᠨ ᠢ ᠰᠤᠳᠤᠯᠬᠤ ᠪᠠᠷᠢᠮᠲᠠ ᠶᠤᠮ᠃',
      body: [
        'ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠬᠡᠪᠯᠡᠯ ᠦᠨ ᠬᠦᠷᠢᠶᠡᠯᠡᠩ ᠦᠨ ᠴᠤᠭᠯᠠᠷᠠᠯ ᠠᠴᠠ ᠕᠙ ᠨᠡᠷ᠎ᠡ ᠶᠢᠨ ᠰᠣᠨᠢᠨ ᠢ ᠴᠠᠬᠢᠮ ᠬᠤᠪᠢ ᠪᠣᠯᠭᠠᠨ ᠬᠠᠳᠠᠭᠠᠯᠠᠵᠠᠢ᠃ ᠡᠳᠡᠭᠡᠷ ᠨᠢ ᠑᠙᠙᠐–᠑᠙᠙᠕ ᠣᠨ ᠳᠤ ᠭᠠᠷᠤᠭᠰᠠᠨ ᠪᠥᠭᠡᠳ ᠤᠯᠤᠰ ᠲᠥᠷᠥ ᠶᠢᠨ ᠥᠪᠡᠷᠴᠢᠯᠡᠯᠲᠡ᠂ ᠪᠡᠶ᠎ᠡ ᠳᠠᠭᠠᠭᠰᠠᠨ ᠬᠡᠪᠯᠡᠯ ᠦᠨ ᠥᠰᠦᠯᠲᠡ ᠶᠢ ᠠᠵᠢᠭᠯᠠᠬᠤ ᠪᠣᠯᠣᠮᠵᠢ ᠥᠭᠳᠡᠭ᠃',
        'ᠪᠷᠢᠲᠠᠨᠢ ᠶᠢᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ ᠤᠨ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠳᠦ ᠵᠠᠷᠢᠮ ᠬᠤᠭᠤᠳᠠᠰᠤ ᠳᠤᠲᠠᠭᠤ᠂ ᠤᠷᠠᠭᠳᠠᠭᠰᠠᠨ ᠪᠤᠶᠤ ᠳᠦᠷᠰᠦ ᠨᠢ ᠭᠡᠮᠲᠦᠭᠰᠡᠨ ᠭᠡᠵᠦ ᠵᠠᠭᠠᠵᠠᠢ᠃ ᠲᠡᠶᠢᠮᠦ ᠡᠴᠡ ᠨᠢᠭᠡ ᠮᠡᠳᠡᠭᠡ ᠣᠯᠳᠠᠬᠤ ᠦᠭᠡᠢ ᠪᠠᠶᠢᠬᠤ ᠶᠢ ᠲᠡᠷᠡ ᠦᠶ᠎ᠡ ᠳᠦ ᠣᠭᠲᠤ ᠬᠡᠪᠯᠡᠭᠳᠡᠭᠡᠳᠦᠢ ᠭᠡᠰᠡᠨ ᠨᠣᠲᠠᠯᠠᠭ᠎ᠠ ᠪᠣᠯᠭᠠᠵᠤ ᠦᠯᠦ ᠪᠣᠯᠣᠨ᠎ᠠ᠃',
      ],
