          title: 'ᠯᠣᠰ ᠠᠨᠵᠧᠯᠧᠰ ᠤᠨ ᠺᠠᠯᠢᠹᠣᠷᠨᠢ ᠶᠠ ᠶᠢᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ',
          organization: 'ᠯᠣᠰ ᠠᠨᠵᠧᠯᠧᠰ ᠤᠨ ᠺᠠᠯᠢᠹᠣᠷᠨᠢ ᠶᠠ ᠶᠢᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ',
