      category: 'people',
      title: 'ᠵᠠᠶ᠎ᠠ ᠪᠠᠨᠳᠢᠳᠠ ᠯᠤᠪᠰᠠᠩᠫᠷᠢᠨᠯᠠᠢ',
      summary: 'ᠯᠤᠪᠰᠠᠩᠫᠷᠢᠨᠯᠠᠢ ᠮᠣᠩᠭᠣᠯ ᠪᠠ ᠲᠥᠪᠡᠳ ᠬᠡᠯᠡ ᠪᠡᠷ ᠲᠡᠦᠬᠡ᠂ ᠭᠦᠨ ᠤᠬᠠᠭᠠᠨ ᠪᠠ ᠰᠢᠯᠦᠭ ᠦᠨ ᠣᠨᠣᠯ ᠪᠢᠴᠢᠵᠡᠢ᠃',
      body: [
        'ᠬᠠᠯᠬ᠎ᠠ ᠶᠢᠨ ᠵᠠᠶ᠎ᠠ ᠪᠠᠨᠳᠢᠳᠠ ᠯᠤᠪᠰᠠᠩᠫᠷᠢᠨᠯᠠᠢ ᠑᠖᠔᠒–᠑᠗᠑᠕ ᠣᠨ ᠳᠤ ᠠᠮᠢᠳᠤᠷᠠᠵᠠᠢ᠃ ᠲᠡᠷᠡ ᠥᠨᠳᠥᠷ ᠭᠡᠭᠡᠨ ᠳᠦ ᠰᠢᠪᠢᠯᠠᠨ᠂ ᠮᠣᠩᠭᠣᠯ ᠪᠠ ᠲᠥᠪᠡᠳ ᠪᠢᠴᠢᠭ ᠰᠤᠷᠴᠠᠢ᠃ ᠑᠖᠖᠐ ᠣᠨ ᠳᠤ ᠯᠾᠠᠰᠠ ᠳᠤ ᠣᠴᠢᠵᠤ᠂ ᠑᠖᠗᠙ ᠣᠨ ᠬᠦᠷᠲᠡᠯ᠎ᠡ ᠲᠥᠪᠡᠳ ᠲᠦ ᠰᠤᠷᠤᠯᠴᠠᠬᠤ ᠳᠠᠭᠠᠨ ᠭᠣᠣᠯᠳᠠᠭᠤ ᠳᠠᠰᠢᠯᠬᠦᠩᠪᠦ ᠳᠦ ᠰᠠᠭᠤᠵᠠᠢ᠃',
        'ᠲᠡᠷᠡ ᠑᠖᠗᠔ ᠣᠨ ᠳᠤ ᠲᠥᠪᠡᠳ ᠲᠦ ᠪᠠᠶᠢᠬᠤ ᠳᠠᠭᠠᠨ ᠲᠦᠰᠢᠶᠡᠲᠦ ᠬᠠᠨ ᠤ ᠨᠠᠮᠲᠠᠷ ᠢ ᠮᠣᠩᠭᠣᠯ ᠬᠡᠯᠡ ᠪᠡᠷ ᠪᠢᠴᠢᠵᠡᠢ᠃ ᠲᠡᠦᠬᠡ ᠶᠢᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠲᠣᠯᠢ ᠲᠡᠭᠦᠨ ᠦ ᠵᠣᠬᠢᠶᠠᠯ ᠢ ᠵᠢᠷᠭᠤᠭᠠᠨ ᠪᠣᠲᠢ ᠭᠡᠵᠦ᠂ ᠲᠡᠭᠦᠨ ᠡᠴᠡ ᠳᠥᠷᠪᠡᠨ ᠪᠣᠲᠢ ᠶᠢ ᠲᠥᠪᠡᠳ ᠬᠡᠯᠡᠲᠦ ᠵᠠᠶ᠎ᠠ ᠶᠢᠨ ᠰᠠᠨᠶᠢᠭ ᠭᠡᠵᠦ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃ ᠲᠡᠷᠡ ᠨᠣᠮ ᠵᠣᠬᠢᠶᠠᠬᠤ ᠠᠴᠠ ᠭᠠᠳᠠᠨ᠎ᠠ᠂ ᠑᠖᠘᠖ ᠣᠨ ᠤ ᠬᠦᠷᠡᠨ ᠪᠡᠯᠴᠢᠷ ᠦᠨ ᠴᠢᠭᠤᠯᠭᠠᠨ ᠳᠤ ᠬᠠᠯᠬ᠎ᠠ ᠶᠢᠨ ᠨᠣᠶᠠᠳ ᠢ ᠡᠪᠯᠡᠷᠡᠭᠦᠯᠬᠦ ᠳᠦ ᠣᠷᠣᠯᠴᠠᠵᠠᠢ᠃',
      ],
