          title: 'ᠠᠽᠢ ᠶᠢᠨ ᠥᠪ ᠦᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
          organization: 'ᠠᠽᠢ ᠶᠢᠨ ᠥᠪ ᠦᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
