          title: 'ᠬᠢᠮᠠᠯᠠᠶ᠎ᠠ ᠶᠢᠨ ᠤᠷᠠᠯᠢᠭ ᠤᠨ ᠪᠠᠶᠠᠯᠢᠭ',
          organization: 'ᠬᠢᠮᠠᠯᠠᠶ᠎ᠠ ᠶᠢᠨ ᠤᠷᠠᠯᠢᠭ ᠤᠨ ᠪᠠᠶᠠᠯᠢᠭ',
