      title: 'ᠳᠥᠷᠪᠡᠨ ᠬᠡᠦᠬᠡᠳ ᠦᠨ ᠸᠠᠩ ᠤᠨ ᠮᠥᠩᠭᠥᠨ ᠲᠠᠮᠠᠭ᠎ᠠ',
      summary: '᠑᠖᠘᠖ ᠣᠨ ᠤ ᠲᠠᠮᠠᠭᠠᠨ ᠳᠤ ᠬᠣᠰᠢᠭᠤᠨ ᠤ ᠨᠡᠷ᠎ᠡ᠂ ᠦᠢᠯᠡᠳᠦᠭᠰᠡᠨ ᠭᠠᠵᠠᠷ ᠪᠠ ᠣᠨ ᠰᠠᠷ᠎ᠠ ᠲᠡᠮᠳᠡᠭᠯᠡᠵᠡᠢ᠃',
      body: [
        'ᠮᠧᠲ᠋ᠷᠣᠫᠣᠯᠢᠲ᠋ᠧᠨ ᠦ ᠮᠦᠽᠧᠢ ᠳᠦ ᠵᠡᠭᠡᠯᠡᠷ ᠦᠵᠡᠭᠦᠯᠵᠦ ᠪᠤᠢ ᠡᠨᠡ ᠮᠥᠩᠭᠥᠨ ᠲᠠᠮᠠᠭ᠎ᠠ ᠳᠥᠷᠪᠡᠨ ᠬᠡᠦᠬᠡᠳ ᠬᠣᠰᠢᠭᠤᠨ ᠤ ᠸᠠᠩ ᠳᠤ ᠬᠣᠯᠪᠣᠭᠳᠠᠨ᠎ᠠ᠃ ᠪᠠᠷᠰᠤᠨ ᠳᠦᠷᠰᠦᠲᠦ ᠠᠲᠭᠠᠭᠤᠯ ᠲᠠᠢ᠃ ᠤᠯᠠᠨ ᠳᠤ ᠨᠢ ᠸᠠᠩ ᠤᠨ ᠲᠠᠮᠠᠭ᠎ᠠ ᠭᠡᠰᠡᠨ ᠤᠲᠭᠠᠲᠠᠢ ᠮᠠᠨᠵᠤ ᠪᠠ ᠮᠣᠩᠭᠣᠯ ᠲᠣᠪᠣᠶᠢᠮᠠᠯ ᠦᠰᠦᠭ ᠪᠤᠢ᠃',
        'ᠰᠠᠭᠤᠷᠢᠨ ᠤ ᠳᠡᠭᠡᠳᠦ ᠲᠠᠯ᠎ᠠ ᠳᠤ ᠲᠡᠷᠡ ᠨᠡᠷ᠎ᠡ ᠶᠢ ᠬᠣᠶᠠᠷ ᠬᠡᠯᠡ ᠪᠡᠷ ᠳᠠᠬᠢᠨ ᠰᠡᠶᠢᠯᠵᠡᠢ᠃ ᠬᠠᠵᠠᠭᠤ ᠳᠤ ᠦᠢᠯᠡᠳᠦᠭᠰᠡᠨ ᠶᠠᠮᠤᠨ ᠪᠠ ᠡᠩᠬᠡ ᠠᠮᠤᠭᠤᠯᠠᠩ ᠤᠨ ᠬᠣᠷᠢᠨ ᠲᠠᠪᠤᠳᠤᠭᠠᠷ ᠣᠨ ᠤ ᠳᠥᠷᠪᠡᠳᠦᠭᠡᠷ ᠰᠠᠷ᠎ᠠ ᠭᠡᠰᠡᠨ ᠪᠢᠴᠢᠭ ᠪᠤᠢ᠃ ᠡᠨᠡ ᠣᠨ ᠨᠢ ᠑᠖᠘᠖ ᠣᠨ ᠲᠠᠢ ᠲᠣᠬᠢᠷᠠᠨ᠎ᠠ᠃',
      ],
