          organization: 'ᠮᠧᠲ᠋ᠷᠣᠫᠣᠯᠢᠲ᠋ᠧᠨ ᠦ ᠤᠷᠠᠯᠢᠭ ᠤᠨ ᠮᠦᠽᠧᠢ',
