      summary: 'ᠬᠥᠭᠦᠷᠭᠡ᠂ ᠲᠠᠭᠯᠠᠭᠠᠨ ᠤ ᠬᠠᠯᠪᠠᠭ᠎ᠠ ᠪᠠ ᠳᠠᠯᠢᠩ ᠨᠢ ᠠᠪᠴᠤ ᠶᠠᠪᠤᠬᠤ ᠬᠡᠷᠡᠭᠯᠡᠭᠡ ᠪᠡᠷ ᠬᠣᠯᠪᠣᠭᠳᠠᠨ᠎ᠠ᠃',
      body: [
        'ᠳᠠᠨᠢ ᠶᠢᠨ ᠦᠨᠳᠦᠰᠦᠨ ᠦ ᠮᠦᠽᠧᠢ ᠶᠢᠨ ᠡᠨᠡ ᠪᠦᠷᠢᠳᠬᠡᠯ ᠬᠠᠲᠤᠭᠠᠮᠠᠯ ᠲᠣᠷᠭᠣᠨ ᠲᠠᠮᠠᠬᠢᠨ ᠤ ᠤᠭᠤᠲᠠ᠂ ᠶᠠᠭᠠᠪᠲᠤᠷ ᠭᠠᠷᠲᠠᠮ ᠬᠥᠭᠦᠷᠭᠡ ᠪᠠ ᠲᠡᠭᠦᠨ ᠦ ᠳᠠᠯᠢᠩ ᠢ ᠬᠠᠮᠲᠤ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠵᠠᠢ᠃ ᠬᠥᠭᠦᠷᠭᠡᠨ ᠦ ᠲᠠᠭᠯᠠᠭᠠᠨ ᠳᠤ ᠪᠠᠭ᠎ᠠ ᠬᠠᠯᠪᠠᠭ᠎ᠠ ᠪᠡᠬᠢᠯᠡᠭᠳᠡᠵᠡᠢ᠃',
        'ᠲᠣᠷᠭᠣᠨ ᠳᠠᠯᠢᠩ ᠢ ᠬᠥᠭᠦᠷᠭᠡᠨ ᠦ ᠬᠡᠮᠵᠢᠶ᠎ᠡ ᠳᠦ ᠲᠣᠬᠢᠷᠠᠭᠤᠯᠵᠤ ᠣᠶᠣᠭᠰᠠᠨ᠃ ᠠᠷᠤ ᠲᠠᠯ᠎ᠠ ᠳᠤ ᠨᠢ ᠪᠡᠬᠢᠯᠡᠭᠰᠡᠨ ᠤᠯᠠᠭᠠᠨ ᠲᠣᠷᠭᠣᠨ ᠣᠭᠣᠰᠣᠷ ᠢᠶᠠᠷ ᠪᠦᠰᠡᠨ ᠳᠦ ᠵᠡᠭᠦᠵᠦ ᠪᠣᠯᠣᠨ᠎ᠠ᠃ ᠡᠳᠡᠭᠡᠷ ᠡᠳ᠋ ᠢ ᠬᠠᠮᠲᠤ ᠠᠵᠢᠭᠯᠠᠪᠠᠯ ᠴᠢᠯᠠᠭᠤᠨ ᠰᠠᠪᠠ ᠪᠠ ᠬᠠᠲᠤᠭᠠᠮᠠᠯ ᠤᠭᠤᠲᠠᠨ ᠤ ᠡᠭᠦᠷᠭᠡ ᠢᠯᠡ ᠪᠣᠯᠣᠨ᠎ᠠ᠃',
      ],
