          organization: 'ᠹᠢᠨᠯᠠᠨᠳ᠋ ᠤᠨ ᠭᠡᠷᠡᠯ ᠵᠢᠷᠤᠭ ᠤᠨ ᠮᠦᠽᠧᠢ',
