          title: 'ᠱᠤᠺᠱᠢᠨ ᠤ ᠨᠡᠷᠡᠮᠵᠢᠲᠦ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
          organization: 'ᠱᠤᠺᠱᠢᠨ ᠤ ᠨᠡᠷᠡᠮᠵᠢᠲᠦ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
