          organization: 'ᠠᠮᠤᠷ ᠰᠠᠨᠠᠨ ᠤ ᠨᠡᠷᠡᠮᠵᠢᠲᠦ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
