          title: 'ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ ᠶᠢᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
          organization: 'ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠶᠡᠬᠡ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ ᠶᠢᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
