      summary: 'ᠥᠴᠦᠬᠡᠨ ᠰᠠᠪᠠᠨ ᠤ ᠬᠡᠰᠡᠭ ᠴᠤ ᠠᠯᠤᠰ ᠣᠷᠣᠨ ᠤ ᠰᠣᠯᠢᠯᠴᠠᠭᠠᠨ ᠤ ᠪᠠᠷᠢᠮᠲᠠ ᠪᠣᠯᠵᠤ ᠪᠣᠯᠣᠨ᠎ᠠ᠃',
      body: [
        '᠒᠐᠑᠖ ᠣᠨ ᠤ ᠶᠠᠪᠤᠭᠠᠨ ᠬᠠᠶᠢᠭᠤᠯ ᠠᠷ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠵᠡᠭᠦᠨ ᠡᠮᠦᠨᠡᠳᠦ ᠭᠣᠪᠢ ᠳᠤ ᠬᠥᠬᠡ ᠨᠣᠭᠣᠭᠠᠨ ᠫᠠᠭᠠᠵᠢᠲᠠᠢ ᠬᠣᠶᠠᠷ ᠬᠡᠰᠡᠭ ᠣᠯᠳᠠᠵᠠᠢ᠃ ᠲᠡᠳᠡᠭᠡᠷ ᠡᠰᠦᠨ ᠮᠢᠩᠭ᠎ᠠ ᠠᠴᠠ ᠣᠯᠠᠨ ᠳᠤᠮᠳᠠᠳᠤ ᠵᠠᠭᠤᠨ ᠤ ᠰᠠᠪᠠᠨ ᠤ ᠬᠡᠰᠡᠭ ᠦᠨ ᠳᠤᠮᠳᠠ ᠮᠠᠰᠢ ᠴᠥᠭᠡᠨ ᠪᠠᠶᠢᠪᠠ᠃ ᠬᠡᠰᠡᠭ ᠦᠳ ᠪᠠᠭ᠎ᠠ ᠲᠤᠯᠠ ᠭᠠᠩᠴᠠ ᠬᠡᠯᠪᠡᠷᠢ ᠪᠡᠷ ᠭᠠᠷᠤᠯ ᠢ ᠨᠢ ᠲᠠᠨᠢᠬᠤ ᠪᠡᠷᠬᠡ ᠪᠠᠶᠢᠵᠠᠢ᠃',
        '᠒᠐᠒᠖ ᠣᠨ ᠤ ᠥᠭᠦᠯᠡᠯ ᠳᠦ ᠫᠠᠭᠠᠵᠢ ᠶᠢᠨ ᠪᠦᠷᠢᠯᠳᠦᠬᠦᠨ ᠢ ᠰᠢᠨᠵᠢᠯᠵᠦ᠂ ᠫᠧᠷᠰ ᠪᠠ ᠴᠢᠨᠠ ᠶᠢᠨ ᠰᠠᠪᠠ ᠲᠠᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠤᠭᠰᠠᠨ ᠢ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃ ᠦᠷ᠎ᠡ ᠳ᠋ᠦᠩ ᠨᠢ ᠫᠧᠷᠰ ᠦᠨ ᠲᠧᠬᠨᠢᠺ ᠲᠡᠢ ᠨᠡᠶᠢᠴᠡᠵᠦ᠂ ᠠᠯᠤᠰ ᠤᠨ ᠡᠳ ᠵᠠᠷᠢᠮ ᠳᠠᠭᠠᠨ ᠵᠢᠵᠢᠭ ᠨᠡᠭᠦᠳᠡᠯᠴᠢᠳ ᠤᠨ ᠪᠠᠭᠤᠷᠢ ᠳᠤ ᠬᠦᠷᠳᠡᠭ ᠢ ᠰᠠᠨᠠᠭᠠᠯᠵᠠᠢ᠃ ᠭᠡᠪᠡᠴᠦ ᠶᠠᠭ ᠠᠯᠢ ᠵᠤᠤᠬ᠎ᠠ ᠳᠤ ᠬᠢᠭᠰᠡᠨ ᠢ ᠲᠣᠭᠲᠠᠭᠠᠭᠰᠠᠨ ᠦᠭᠡᠢ᠃',
      ],
