      summary: 'ᠰᠦᠦᠨ ᠤᠨᠳᠠᠨ ᠢ ᠨᠡᠷᠡᠬᠦ ᠲᠣᠨᠣᠭ ᠲᠤ ᠲᠣᠭᠣᠭ᠎ᠠ᠂ ᠪᠦᠷᠬᠡᠭᠦᠷ ᠪᠠ ᠬᠥᠷᠥᠭᠡᠬᠦ ᠰᠠᠪᠠ ᠬᠣᠯᠪᠣᠭᠳᠠᠨ᠎ᠠ᠃',
      body: [
        'ᠰᠣᠶᠣᠯ ᠤᠨ ᠥᠪ ᠦᠨ ᠦᠨᠳᠦᠰᠦᠨ ᠦ ᠲᠥᠪ ᠦᠨ ᠒᠐᠒᠒ ᠣᠨ ᠤ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠭ᠎ᠠ ᠰᠢᠮ᠎ᠡ ᠶᠢᠨ ᠠᠷᠢᠬᠢ ᠶᠢ ᠢᠰᠭᠡᠭᠰᠡᠨ ᠰᠦᠦᠨ ᠤᠨᠳᠠᠨ ᠠᠴᠠ ᠨᠡᠷᠡᠵᠦ ᠭᠠᠷᠭᠠᠳᠠᠭ ᠭᠡᠵᠡᠢ᠃ ᠲᠣᠨᠣᠭ ᠲᠤ ᠳᠣᠣᠳᠤ ᠲᠣᠭᠣᠭ᠎ᠠ᠂ ᠮᠣᠳᠣ ᠪᠤᠶᠤ ᠲᠥᠮᠦᠷᠯᠢᠭ ᠪᠦᠷᠬᠡᠭᠦᠷ᠂ ᠳᠡᠭᠡᠷ᠎ᠡ ᠨᠢ ᠬᠦᠶᠢᠲᠡᠨ ᠤᠰᠤᠲᠠᠢ ᠰᠠᠪᠠ ᠣᠷᠣᠳᠠᠭ᠃',
        'ᠲᠤᠰ ᠪᠠᠷᠢᠮᠲᠠ ᠨᠡᠭᠡᠭᠡᠯᠲᠡᠲᠡᠢ ᠪᠠ ᠬᠠᠭᠠᠯᠲᠠᠲᠠᠢ ᠬᠣᠶᠠᠷ ᠠᠷᠭ᠎ᠠ ᠶᠢ ᠶᠠᠯᠭᠠᠵᠠᠢ᠃ ᠨᠢᠭᠡ ᠳᠦ ᠨᠢ ᠨᠡᠷᠡᠭᠡᠰᠦ ᠶᠢ ᠭᠠᠳᠠᠭᠰᠢ ᠬᠣᠭᠣᠯᠣᠢ ᠪᠠᠷ ᠠᠪᠳᠠᠭ᠂ ᠨᠥᠭᠥᠭᠡᠳᠦ ᠳᠦ ᠨᠢ ᠳᠣᠲᠣᠷ᠎ᠠ ᠥᠯᠭᠥᠭᠰᠡᠨ ᠰᠠᠪᠠᠨ ᠳᠤ ᠬᠤᠷᠢᠶᠠᠳᠠᠭ᠃ ᠡᠨᠡ ᠶᠠᠯᠭᠠᠭ᠎ᠠ ᠨᠢ ᠪᠦᠲᠦᠴᠡ ᠶᠢᠨ ᠰᠠᠪᠠ ᠪᠠ ᠬᠣᠭᠣᠯᠣᠢ ᠶᠢᠨ ᠪᠠᠶᠢᠷᠢᠯᠠᠯ ᠠᠷ ᠢᠯᠡᠷᠡᠳᠡᠭ᠃',
      ],
