      summary: 'ᠵᠠᠷᠭᠤ ᠶᠢᠨ ᠪᠢᠴᠢᠭ ᠨᠢ ᠬᠠᠤᠯᠢ ᠬᠡᠷᠬᠢᠨ ᠬᠡᠷᠡᠭᠵᠢᠭᠰᠡᠨ ᠢ ᠠᠰᠠᠭᠤᠬᠤ ᠪᠣᠯᠣᠮᠵᠢ ᠥᠭᠳᠡᠭ᠃',
      body: [
        'ᠪᠧᠲᠢᠨ ᠪᠢᠷᠭᠡ «ᠶᠤᠸᠠᠨ ᠳ᠋ᠢᠶᠠᠨᠵᠠᠩ» ᠤᠨ ᠠᠷᠪᠠᠨ ᠨᠠᠶᠢᠮᠠᠳᠤᠭᠠᠷ ᠳᠡᠪᠲᠡᠷ ᠦᠨ ᠭᠡᠷᠯᠡᠯᠲᠡ ᠶᠢᠨ ᠳᠠᠯᠠᠨ ᠲᠠᠪᠤᠨ ᠬᠡᠷᠡᠭ ᠢ ᠣᠷᠴᠢᠭᠤᠯᠵᠤ ᠰᠤᠳᠤᠯᠵᠠᠢ᠃ ᠺᠧᠯᠢᠾᠧᠷ ᠦᠨ ᠱᠦᠭᠦᠮᠵᠢ ᠳᠦ᠂ ᠡᠨᠡ ᠡᠬᠡ ᠪᠢᠴᠢᠭ ᠪᠣᠯ ᠭᠠᠭᠴᠠ ᠲᠣᠭᠲᠠᠮᠠᠯ ᠵᠦᠢᠯ ᠵᠠᠭᠠᠯᠲᠠ ᠪᠢᠰᠢ᠂ ᠵᠠᠷᠭᠤ᠂ ᠮᠠᠷᠭᠤᠭᠠᠨ ᠪᠠ ᠱᠢᠶᠢᠳᠪᠦᠷᠢ ᠶᠢᠨ ᠴᠤᠭᠯᠠᠭᠤᠯᠭ᠎ᠠ ᠪᠣᠯᠬᠤ ᠶᠢ ᠣᠨᠴᠠᠯᠠᠵᠠᠢ᠃',
        'ᠭᠡᠷᠯᠡᠯᠲᠡ ᠰᠠᠯᠬᠤ᠂ ᠳᠠᠬᠢᠨ ᠭᠡᠷᠯᠡᠬᠦ ᠪᠠ ᠭᠡᠷ ᠪᠦᠯᠢ ᠶᠢᠨ ᠥᠮᠴᠢ ᠶᠢᠨ ᠠᠰᠠᠭᠤᠳᠠᠯ ᠢ ᠥᠭᠡᠷ᠎ᠡ ᠥᠭᠡᠷ᠎ᠡ ᠱᠠᠲᠤᠨ ᠤ ᠠᠯᠪᠠ ᠬᠡᠯᠡᠯᠴᠡᠵᠡᠢ᠃ ᠵᠠᠷᠢᠮ ᠱᠢᠶᠢᠳᠪᠦᠷᠢ ᠨᠤᠲᠤᠭ ᠤᠨ ᠵᠠᠩᠰᠢᠯ ᠢ ᠵᠥᠪᠰᠢᠶᠡᠷᠡᠭᠰᠡᠨ ᠪᠣᠯ ᠬᠣᠵᠢᠮ ᠨᠢ ᠲᠡᠭᠦᠨ ᠢ ᠥᠭᠡᠷᠡᠴᠢᠯᠡᠭᠰᠡᠨ ᠲᠣᠬᠢᠶᠠᠯ ᠴᠤ ᠪᠤᠢ᠃ ᠲᠡᠶᠢᠮᠦ ᠡᠴᠡ ᠨᠢᠭᠡ ᠬᠡᠷᠡᠭ ᠦᠨ ᠱᠢᠶᠢᠳᠪᠦᠷᠢ ᠶᠢ ᠪᠦᠬᠦ ᠶᠤᠸᠠᠨ ᠤ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠠᠳᠠᠯᠢ ᠵᠢᠷᠤᠮ ᠭᠡᠵᠦ ᠳᠦᠩᠨᠡᠬᠦ ᠡᠴᠡ ᠵᠠᠶᠢᠯᠠᠰᠬᠢᠨ᠎ᠠ᠃',
      ],
