      title: 'ᠬᠣᠴᠠ ᠨᠠᠮᠰᠠᠷᠠᠶᠧᠪ',
      summary:
        'ᠨᠠᠮᠰᠠᠷᠠᠶᠧᠪ ᠦᠨ ᠤᠷᠠᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠭᠠᠷ ᠪᠢᠴᠢᠭ ᠦᠨ ᠣᠷᠴᠢᠨ ᠡᠴᠡ ᠰᠢᠨ᠎ᠡ ᠲᠠᠶᠢᠵᠠ ᠪᠠ ᠷᠣᠮᠠᠨ ᠳᠤ ᠥᠷᠭᠡᠵᠢᠵᠡᠢ᠃',
      body: [
        'ᠬᠣᠴᠠ ᠨᠠᠮᠰᠠᠷᠠᠶᠧᠪ ᠑᠘᠘᠙–᠑᠙᠕᠙ ᠣᠨ ᠳᠤ ᠠᠮᠢᠳᠤᠷᠠᠭᠰᠠᠨ ᠪᠤᠷᠢᠶᠠᠳ ᠵᠣᠬᠢᠶᠠᠯᠴᠢ ᠶᠤᠮ᠃ ᠬᠢᠵᠢᠩᠭ᠎ᠠ ᠳᠤ ᠪᠠᠭ᠎ᠠ ᠨᠠᠰᠤᠨ ᠠᠴᠠ ᠮᠣᠩᠭᠣᠯ ᠪᠢᠴᠢᠭ ᠰᠤᠷᠴᠤ᠂ ᠨᠤᠲᠤᠭ ᠲᠠᠭᠠᠨ ᠪᠠᠭᠰᠢᠯᠠᠵᠠᠢ᠃ ᠲᠡᠷᠡ ᠰᠠᠶᠢᠨ ᠳᠤᠷᠠᠨ ᠤ ᠲᠧᠠᠲᠷ ᠪᠠᠶᠢᠭᠤᠯᠵᠤ᠂ ᠑᠙᠑᠙ ᠣᠨ ᠳᠤ ᠬᠠᠷᠠᠩᠭᠤᠢ ᠬᠡᠮᠡᠬᠦ ᠥᠪᠡᠷ ᠦᠨ ᠵᠦᠴᠦᠭᠡ ᠪᠡᠨ ᠲᠣᠭᠯᠠᠭᠤᠯᠵᠠᠢ᠃',
        'ᠲᠡᠭᠦᠨ ᠦ ᠡᠬᠢᠨ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠤᠳ ᠱᠠᠰᠢᠨ ᠤ ᠵᠢᠳᠬᠦᠯᠲᠡᠨ ᠪᠠ ᠬᠠᠭᠤᠴᠢᠨ ᠨᠡᠶᠢᠭᠡᠮ ᠢ ᠰᠢᠭᠦᠮᠵᠢᠯᠡᠭᠰᠡᠨ ᠬᠣᠱᠤᠩ ᠥᠩᠭᠡ ᠲᠡᠢ ᠪᠠᠶᠢᠵᠠᠢ᠃ ᠲᠡᠷᠡ ᠥᠭᠦᠯᠡᠯᠭᠡ᠂ ᠲᠤᠭᠤᠵᠢ ᠪᠠ ᠷᠣᠮᠠᠨ ᠪᠢᠴᠢᠵᠦ᠂ ᠑᠙᠕᠐ ᠣᠨ ᠳᠤ ᠦᠷ ᠦᠨ ᠲᠣᠯᠣᠨ ᠭᠡᠭᠡᠨ ᠳᠦ ᠬᠡᠮᠡᠬᠦ ᠷᠣᠮᠠᠨ ᠢᠶᠠᠨ ᠭᠠᠷᠭᠠᠵᠠᠢ᠃ ᠮᠥᠨ ᠠᠯᠠᠮᠵᠢ ᠮᠡᠷᠭᠡᠨ ᠵᠡᠷᠭᠡ ᠠᠮᠠᠨ ᠲᠤᠭᠤᠵᠢ ᠶᠢ ᠤᠷᠠᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠤᠨ ᠬᠡᠯᠪᠡᠷᠢ ᠳᠦ ᠨᠠᠶᠢᠷᠠᠭᠤᠯᠵᠠᠢ᠃ ᠡᠳᠡᠭᠡᠷ ᠢ ᠠᠮᠠᠨ ᠡᠬᠡ ᠶᠢᠨ ᠦᠭᠡᠴᠢᠯᠡᠭᠰᠡᠨ ᠲᠡᠮᠳᠡᠭᠯᠡᠯ ᠡᠴᠡ ᠶᠢᠯᠭᠠᠨ ᠦᠵᠡᠨ᠎ᠡ᠃',
      ],
