      category: 'people',
      title: 'ᠪᠠᠪᠠᠰᠠᠨ ᠠᠪᠢᠳᠤᠶᠧᠪ',
      summary: 'ᠠᠪᠢᠳᠤᠶᠧᠪ ᠰᠢᠯᠦᠭ᠂ ᠬᠡᠦᠬᠡᠳ ᠦᠨ ᠦᠯᠢᠭᠡᠷ ᠪᠠ ᠣᠷᠴᠢᠭᠤᠯᠭ᠎ᠠ ᠲᠤᠭᠤᠷᠪᠢᠵᠠᠢ᠃',
      body: [
        'ᠪᠠᠪᠠᠰᠠᠨ ᠠᠪᠢᠳᠤᠶᠧᠪ ᠑᠙᠐᠙–᠑᠙᠔᠐ ᠣᠨ ᠳᠤ ᠠᠮᠢᠳᠤᠷᠠᠭᠰᠠᠨ ᠪᠤᠷᠢᠶᠠᠳ ᠵᠣᠬᠢᠶᠠᠯᠴᠢ ᠶᠤᠮ᠃ ᠶᠠᠩᠭᠠᠵᠢᠨ ᠳᠤ ᠲᠥᠷᠦᠵᠦ᠂ ᠰᠣᠨᠢᠨ ᠤ ᠰᠤᠷᠪᠤᠯᠵᠢᠯᠠᠭᠴᠢ ᠪᠠ ᠨᠠᠶᠢᠷᠠᠭᠤᠯᠤᠭᠴᠢ ᠪᠠᠷ ᠠᠵᠢᠯᠯᠠᠵᠠᠢ᠃ ᠲᠡᠭᠦᠨ ᠦ ᠡᠬᠢᠨ ᠰᠢᠯᠦᠭ ᠦᠳ ᠑᠙᠒᠗ ᠣᠨ ᠳᠤ ᠨᠡᠶᠢᠲᠡᠯᠡᠭᠳᠡᠵᠦ᠂ ᠨᠢᠰᠬᠡᠯ ᠣᠩᠭᠣᠴᠠ ᠬᠡᠮᠡᠬᠦ ᠨᠠᠶᠢᠷᠠᠭᠯᠠᠯ ᠳᠠᠭᠠᠨ ᠨᠤᠲᠤᠭ ᠤᠨ ᠰᠢᠨᠡᠴᠢᠯᠡᠯ ᠦᠨ ᠰᠡᠳᠦᠪ ᠢ ᠪᠢᠴᠢᠵᠡᠢ᠃',
        '᠑᠙᠓᠐ ᠭᠠᠳ ᠣᠨ ᠳᠤ ᠲᠡᠷᠡ ᠣᠰᠲᠷᠣᠪᠰᠺᠢ ᠶᠢᠨ ᠷᠣᠮᠠᠨ ᠪᠠ ᠮᠠᠶᠠᠺᠣᠪᠰᠺᠢ ᠶᠢᠨ ᠰᠢᠯᠦᠭ ᠢ ᠣᠷᠴᠢᠭᠤᠯᠵᠠᠢ᠃ ᠮᠥᠨ ᠡᠷᠡᠯᠬᠡᠭ ᠢᠰᠢᠭᠡ ᠪᠠᠪᠠᠨᠠ᠂ ᠪᠠᠷ ᠤᠨᠤᠭᠴᠢ ᠵᠡᠷᠭᠡ ᠬᠡᠦᠬᠡᠳ ᠦᠨ ᠦᠯᠢᠭᠡᠷ ᠪᠢᠴᠢᠵᠡᠢ᠃ ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠬᠡᠦᠬᠡᠳ ᠵᠠᠯᠠᠭᠤᠰ ᠤᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ ᠲᠡᠭᠦᠨ ᠦ ᠪᠦᠲᠦᠭᠡᠯ ᠢ ᠰᠣᠨᠢᠨ ᠬᠡᠪᠯᠡᠯ᠂ ᠣᠷᠴᠢᠭᠤᠯᠭ᠎ᠠ ᠪᠠ ᠬᠡᠦᠬᠡᠳ ᠦᠨ ᠤᠩᠰᠢᠯᠭ᠎ᠠ ᠶᠢ ᠬᠣᠯᠪᠣᠭᠰᠠᠨ ᠠᠵᠢᠯ ᠭᠡᠵᠦ ᠲᠠᠨᠢᠯᠴᠠᠭᠤᠯᠵᠠᠢ᠃',
      ],
