        'ᠪᠠᠯᠳᠠᠶᠧᠪ ᠦᠨ ᠵᠦᠴᠦᠭᠡ ᠪᠠ ᠠᠮᠠᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠤᠨ ᠴᠤᠭᠯᠠᠷᠠᠯ ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠰᠣᠶᠣᠯ ᠢ ᠰᠤᠳᠤᠯᠬᠤ ᠥᠪ ᠪᠣᠯᠵᠠᠢ᠃',
      body: [
        'ᠰᠧᠷᠭᠧᠢ ᠪᠠᠯᠳᠠᠶᠧᠪ ᠑᠘᠘᠙–᠑᠙᠗᠙ ᠣᠨ ᠳᠤ ᠠᠮᠢᠳᠤᠷᠠᠭᠰᠠᠨ᠂ ᠬᠣᠬᠣᠷᠰᠺ ᠠᠴᠠ ᠭᠠᠷᠤᠯ ᠲᠠᠢ ᠪᠤᠷᠢᠶᠠᠳ ᠡᠷᠳᠡᠮᠲᠡᠨ ᠶᠤᠮ᠃ ᠡᠷᠬᠡᠦ ᠶᠢᠨ ᠪᠠᠭᠰᠢ ᠶᠢᠨ ᠰᠤᠷᠭᠠᠭᠤᠯᠢ ᠳᠤ ᠰᠤᠷᠤᠯᠴᠠᠬᠤ ᠳᠠᠭᠠᠨ ᠣᠶᠤᠲᠠᠳ ᠤᠨ ᠤᠷᠠᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠪᠠ ᠲᠧᠠᠲᠷ ᠤᠨ ᠠᠵᠢᠯ ᠳᠤ ᠣᠷᠣᠯᠴᠠᠵᠠᠢ᠃ ᠠᠪᠠᠭᠠᠢ ᠶᠢᠨ ᠲᠦᠷᠭᠡᠨ ᠬᠡᠮᠡᠬᠦ ᠪᠢᠴᠢᠭ ᠦᠨ ᠨᠡᠷ᠎ᠡ ᠪᠡᠷ ᠮᠠᠯᠴᠢᠨ ᠴᠡᠷᠡᠨ ᠵᠦᠴᠦᠭᠡ ᠪᠡᠨ ᠲᠣᠭᠯᠠᠭᠤᠯᠵᠠᠢ᠃',
        'ᠬᠣᠵᠢᠮ ᠲᠡᠷᠡ ᠥᠪᠡᠷ ᠦᠨ ᠣᠷᠣᠯᠴᠠᠭᠰᠠᠨ ᠤᠷᠠᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠤᠨ ᠣᠷᠴᠢᠨ᠂ ᠭᠠᠷ ᠪᠢᠴᠢᠮᠡᠯ ᠰᠡᠳᠬᠦᠯ ᠪᠠ ᠵᠦᠴᠦᠭᠡ ᠶᠢ ᠰᠤᠳᠤᠯᠵᠠᠢ᠃ ᠪᠠᠶᠢᠭᠠᠯ ᠤᠨ ᠪᠠᠷᠠᠭᠤᠨ ᠪᠠ ᠵᠡᠭᠦᠨ ᠡᠷᠭᠢ ᠶᠢᠨ ᠣᠯᠠᠨ ᠨᠤᠲᠤᠭ ᠠᠴᠠ ᠳᠠᠭᠤ ᠪᠠ ᠳᠣᠮᠣᠭ ᠴᠤᠭᠯᠠᠭᠤᠯᠵᠠᠢ᠃ ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠠᠷᠠᠳ ᠤᠨ ᠳᠠᠭᠤ᠂ ᠤᠭ ᠭᠠᠷᠤᠯ ᠤᠨ ᠳᠣᠮᠣᠭ ᠪᠠ ᠬᠤᠷᠢᠮ ᠤᠨ ᠵᠠᠩ ᠦᠢᠯᠡ ᠶᠢᠨ ᠲᠤᠬᠠᠢ ᠨᠣᠮ ᠤᠳ ᠨᠢ ᠲᠡᠷᠡ ᠴᠤᠭᠯᠠᠷᠠᠯ ᠤᠨ ᠦᠷ᠎ᠡ ᠳ᠋ᠦᠩ ᠶᠤᠮ᠃',
      ],
