      summary: 'ᠳᠠᠰᠢᠨᠢᠮᠠᠶᠧᠪ ᠪᠤᠷᠢᠶᠠᠳ ᠰᠢᠯᠦᠭ ᠦᠨ ᠬᠡᠮ ᠠᠶᠠᠯᠭᠤ ᠳᠤ ᠰᠢᠨ᠎ᠡ ᠲᠤᠷᠰᠢᠯᠲᠠ ᠬᠢᠵᠡᠢ᠃',
      body: [
        'ᠳᠠᠮᠪᠠ ᠳᠠᠰᠢᠨᠢᠮᠠᠶᠧᠪ ᠑᠙᠐᠔–᠑᠙᠓᠗ ᠣᠨ ᠳᠤ ᠠᠮᠢᠳᠤᠷᠠᠭᠰᠠᠨ ᠪᠤᠷᠢᠶᠠᠳ ᠰᠢᠯᠦᠭᠴᠢ ᠶᠤᠮ᠃ ᠰᠡᠯᠡᠩᠭᠡ ᠶᠢᠨ ᠵᠢᠷᠭᠠᠯᠠᠩᠲᠤ ᠳᠤ ᠲᠥᠷᠦᠵᠦ᠂ ᠑᠙᠒᠖ ᠣᠨ ᠠᠴᠠ ᠰᠢᠯᠦᠭ ᠨᠡᠶᠢᠲᠡᠯᠡᠵᠡᠢ᠃ ᠲᠡᠭᠦᠨ ᠦ ᠰᠡᠳᠦᠪ ᠲᠦ ᠨᠤᠲᠤᠭ ᠤᠨ ᠪᠠᠶᠢᠭᠠᠯᠢ᠂ ᠠᠷᠠᠳ ᠤᠨ ᠬᠥᠳᠡᠯᠮᠦᠷᠢ ᠪᠠ ᠲᠤᠬᠠᠶᠢᠨ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠰᠣᠴᠢᠶᠠᠯᠢᠰᠲᠤ ᠰᠢᠨᠡᠴᠢᠯᠡᠯ ᠣᠷᠣᠵᠠᠢ᠃',
        'ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ ᠤᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢ ᠲᠡᠭᠦᠨ ᠦ ᠰᠢᠯᠦᠭ ᠲᠦ ᠮᠥᠷ ᠦᠨ ᠦᠶ᠎ᠡ ᠶᠢᠨ ᠲᠣᠭ᠎ᠠ ᠪᠠ ᠠᠳᠠᠭ ᠤᠨ ᠲᠣᠯᠣᠭᠠᠢ ᠬᠣᠯᠪᠣᠭ᠎ᠠ ᠪᠠᠷ ᠲᠤᠷᠰᠢᠯᠲᠠ ᠬᠢᠭᠰᠡᠨ ᠢ ᠣᠨᠴᠠᠯᠠᠵᠠᠢ᠃ ᠡᠨᠡ ᠨᠢ ᠮᠥᠷ ᠦᠨ ᠡᠬᠢᠨ ᠦ ᠠᠪᠢᠶ᠎ᠠ ᠶᠢ ᠳᠠᠪᠲᠠᠬᠤ ᠤᠯᠠᠮᠵᠢᠯᠠᠯ ᠲᠠᠢ ᠬᠠᠷᠢᠴᠠᠭᠤᠯᠵᠤ ᠰᠤᠳᠤᠯᠬᠤ ᠵᠦᠢᠯ ᠶᠤᠮ᠃ ᠲᠡᠷᠡ ᠮᠥᠨ ᠫᠤᠱᠺᠢᠨ᠂ ᠺᠷᠢᠯᠣᠪ ᠪᠠ ᠲᠣᠯᠰᠲᠣᠢ ᠶᠢᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠢ ᠣᠷᠴᠢᠭᠤᠯᠵᠤ᠂ ᠤᠤᠲᠠᠨ ᠳᠠᠬᠢ ᠴᠢᠨᠣ᠎ᠠ ᠬᠡᠮᠡᠬᠦ ᠤᠷᠠᠨ ᠦᠯᠢᠭᠡᠷ ᠪᠢᠴᠢᠵᠡᠢ᠃',
      ],
