          title: 'ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠬᠡᠦᠬᠡᠳ ᠵᠠᠯᠠᠭᠤᠰ ᠤᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
          organization: 'ᠪᠤᠷᠢᠶᠠᠳ ᠤᠨ ᠬᠡᠦᠬᠡᠳ ᠵᠠᠯᠠᠭᠤᠰ ᠤᠨ ᠨᠣᠮ ᠤᠨ ᠰᠠᠩ',
