      summary: 'ᠰᠣᠯᠪᠣᠨ ᠤ ᠲᠤᠶᠠᠭ᠎ᠠ ᠣᠷᠣᠰ ᠪᠠ ᠪᠤᠷᠢᠶᠠᠳ ᠬᠡᠯᠡ ᠪᠡᠷ ᠵᠣᠬᠢᠶᠠᠵᠠᠢ᠃',
      body: [
        'ᠰᠣᠯᠪᠣᠨ ᠤ ᠲᠤᠶᠠᠭ᠎ᠠ ᠭᠡᠳᠡᠭ ᠨᠢ ᠫᠧᠲᠷ ᠳᠠᠮᠪᠢᠨᠣᠪ ᠤᠨ ᠪᠢᠴᠢᠭ ᠦᠨ ᠨᠡᠷ᠎ᠡ ᠶᠤᠮ᠃ ᠲᠡᠷᠡ ᠑᠘᠙᠒–᠑᠙᠓᠘ ᠣᠨ ᠳᠤ ᠠᠮᠢᠳᠤᠷᠠᠵᠤ᠂ ᠵᠠᠭᠯᠢᠭ ᠠᠴᠠ ᠭᠠᠷᠤᠯ ᠲᠠᠢ ᠪᠤᠷᠢᠶᠠᠳ ᠪᠠᠭᠰᠢ᠂ ᠰᠢᠯᠦᠭᠴᠢ ᠪᠠᠶᠢᠵᠠᠢ᠃ ᠡᠬᠢᠨ ᠰᠢᠯᠦᠭ ᠦᠳ ᠨᠢ ᠡᠷᠬᠡᠦ ᠶᠢᠨ ᠪᠤᠷᠢᠶᠠᠳ ᠣᠶᠤᠲᠠᠳ ᠤᠨ ᠭᠠᠷ ᠪᠢᠴᠢᠮᠡᠯ ᠰᠡᠳᠬᠦᠯ ᠳᠦ ᠭᠠᠷᠴᠠᠢ᠃ ᠬᠣᠵᠢᠮ ᠰᠣᠨᠢᠨ ᠬᠡᠪᠯᠡᠯ ᠪᠠ ᠲᠧᠠᠲᠷ ᠤᠨ ᠠᠵᠢᠯ ᠳᠤ ᠣᠷᠣᠯᠴᠠᠵᠠᠢ᠃',
        'ᠴᠡᠴᠡᠭᠲᠦ ᠲᠠᠯ᠎ᠠ ᠬᠡᠮᠡᠬᠦ ᠡᠬᠢᠨ ᠴᠣᠭᠣᠯᠭᠠᠨ ᠨᠢ ᠣᠷᠣᠰ ᠬᠡᠯᠡ ᠪᠡᠷ ᠪᠢᠴᠢᠭᠳᠡᠵᠡᠢ᠃ ᠲᠤᠰ ᠨᠣᠮ ᠢ ᠰᠤᠳᠤᠯᠤᠭᠴᠢ ᠠᠯᠧᠺᠰᠠᠨᠳᠷ ᠢᠰᠠᠺᠣᠪ ᠣᠷᠣᠰ ᠬᠡᠯᠡᠲᠦ ᠪᠤᠷᠢᠶᠠᠳ ᠤᠷᠠᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠤᠨ ᠡᠬᠢᠨ ᠦᠶ᠎ᠡ ᠲᠡᠢ ᠬᠣᠯᠪᠣᠨ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃ ᠬᠣᠵᠢᠮ ᠤᠨ ᠰᠢᠯᠦᠭ᠂ ᠥᠭᠦᠯᠡᠯᠭᠡ ᠪᠠ ᠬᠡᠦᠬᠡᠳ ᠦᠨ ᠵᠣᠬᠢᠶᠠᠯ ᠳᠠᠭᠠᠨ ᠪᠤᠷᠢᠶᠠᠳ ᠬᠡᠯᠡ ᠶᠢ ᠭᠣᠣᠯᠯᠠᠨ ᠬᠡᠷᠡᠭᠯᠡᠵᠡᠢ᠃ ᠲᠡᠶᠢᠮᠦ ᠡᠴᠡ ᠲᠡᠭᠦᠨ ᠦ ᠵᠣᠬᠢᠶᠠᠯ ᠤᠨ ᠬᠡᠯᠡ ᠶᠢ ᠪᠦᠲᠦᠭᠡᠯ ᠲᠤᠰ ᠪᠦᠷᠢ ᠪᠡᠷ ᠶᠢᠯᠭᠠᠨ᠎ᠠ᠃',
      ],
