      reviewNeeds:
        'ᠡᠬᠢ ᠬᠡᠯᠡᠲᠡᠨ ᠨᠠᠶᠢᠷᠠᠭᠤᠯᠭ᠎ᠠ᠂ ᠵᠥᠪ ᠪᠢᠴᠢᠯᠭᠡ ᠪᠠ ᠮᠡᠷᠭᠡᠵᠢᠯ ᠦᠨ ᠨᠡᠷ᠎ᠡ ᠶᠢ ᠬᠢᠨᠠᠬᠤ ᠱᠠᠭᠠᠷᠳᠠᠯᠭ᠎ᠠ ᠲᠠᠢ᠃',
