      summary: 'ᠲᠥᠮᠦᠷᠯᠢᠭ ᠬᠡᠪ ᠢᠶᠡᠷ ᠱᠠᠪᠠᠷ ᠳᠦᠷᠰᠦ ᠭᠠᠷᠭᠠᠬᠤ ᠨᠢ ᠪᠠᠷᠢᠮᠠᠯ ᠪᠦᠲᠦᠭᠡᠬᠦ ᠨᠢᠭᠡ ᠠᠷᠭ᠎ᠠ ᠶᠤᠮ᠃',
      body: [
        'ᠷᠦᠪᠢᠨ ᠦ ᠮᠦᠽᠧᠢ ᠳᠦ ᠪᠤᠢ ᠵᠣᠩᠬᠠᠪᠠ ᠶᠢᠨ ᠳᠦᠷᠰᠦ ᠬᠢᠬᠦ ᠬᠡᠪ ᠢ ᠠᠷᠪᠠᠨ ᠶᠢᠰᠦᠳᠦᠭᠡᠷ ᠵᠠᠭᠤᠨ ᠤ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠡᠳ ᠭᠡᠵᠦ ᠪᠦᠷᠢᠳᠬᠡᠵᠡᠢ᠃ ᠵᠡᠰ ᠦᠨ ᠬᠠᠶᠢᠯᠠᠰᠢ ᠪᠠᠷ ᠬᠢᠭᠰᠡᠨ ᠬᠣᠶᠠᠷ ᠬᠠᠭᠠᠰ ᠬᠡᠰᠡᠭ ᠲᠡᠢ᠃ ᠡᠨᠡ ᠬᠡᠪ ᠨᠢ ᠰᠦᠵᠢᠭ ᠦᠨ ᠳᠦᠷᠰᠦ ᠪᠦᠲᠦᠭᠡᠬᠦ ᠪᠠᠭᠠᠵᠢ ᠶᠤᠮ᠃',
        'ᠮᠦᠽᠧᠢ ᠡᠴᠡ ᠲᠤᠰ ᠡᠳ ᠢ ᠱᠠᠪᠠᠷ ᠠᠷ ᠪᠦᠲᠦᠭᠡᠬᠦ ᠠᠷᠭ᠎ᠠ ᠶᠢ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠭᠰᠠᠨ ᠬᠡᠰᠡᠭ ᠲᠦ ᠦᠵᠡᠭᠦᠯᠵᠡᠢ᠃ ᠡᠨᠳᠡ ᠪᠥᠭᠡᠷᠡᠩᠬᠡᠢ ᠪᠠ ᠲᠣᠪᠣᠶᠢᠮᠠᠯ ᠵᠢᠵᠢᠭ ᠳᠦᠷᠰᠦ ᠶᠢ ᠬᠡᠪ ᠢᠶᠡᠷ ᠭᠠᠷᠭᠠᠵᠤ᠂ ᠱᠠᠪᠠᠷ ᠢ ᠲᠥᠮᠦᠷᠯᠢᠭ ᠬᠡᠪ ᠲᠦ ᠳᠠᠷᠤᠵᠤ ᠴᠠᠴᠠ ᠬᠢᠳᠡᠭ ᠢ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃',
      ],
