          organization: 'ᠸᠠᠷᠱᠠᠸ ᠤᠨ ᠠᠽᠢ ᠨᠣᠮᠣᠭᠤᠨ ᠳᠠᠯᠠᠢ ᠶᠢᠨ ᠮᠦᠽᠧᠢ',
