      summary: 'ᠲᠣᠮᠣ ᠳᠤᠷᠠᠰᠬᠠᠯ ᠨᠢ ᠨᠢᠭᠡ ᠤᠳᠠᠭ᠎ᠠ ᠶᠢᠨ ᠠᠵᠢᠯ ᠢᠶᠠᠷ ᠪᠦᠲᠦᠭᠡᠭᠳᠡᠭᠰᠡᠨ ᠪᠠᠶᠢᠬᠤ ᠠᠯᠪᠠ ᠦᠭᠡᠢ᠃',
      body: [
        '᠒᠐᠑᠙ ᠣᠨ ᠤ ᠰᠤᠳᠤᠯᠭ᠎ᠠ ᠲᠥᠪ ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠪᠤᠭᠤᠨ ᠴᠢᠯᠠᠭᠤ ᠪᠠ ᠬᠢᠷᠭᠢᠰᠦᠭᠦᠷ ᠦᠨ ᠲᠣᠮᠣ ᠴᠣᠭᠴᠠᠯᠪᠤᠷᠢ ᠳᠤ ᠵᠠᠭᠤᠨ ᠰᠢᠨ᠎ᠡ ᠨᠡᠭᠦᠷᠡᠰᠦᠲᠥ᠋ᠷᠥᠭᠴᠢ ᠶᠢᠨ ᠣᠨ ᠴᠠᠭ ᠤᠨ ᠬᠡᠮᠵᠢᠯᠲᠡ ᠬᠢᠵᠡᠢ᠃ ᠣᠯᠠᠨ ᠬᠡᠮᠵᠢᠯᠲᠡ ᠶᠢ ᠬᠠᠮᠲᠤ ᠦᠵᠡᠬᠦ ᠳᠦ ᠪᠦᠲᠦᠭᠡᠨ ᠪᠠᠶᠢᠭᠤᠯᠬᠤ ᠠᠵᠢᠯ ᠨᠢ ᠪᠠᠷᠤᠭ ᠲᠠᠪᠢᠨ ᠵᠢᠯ ᠦᠷᠭᠦᠯᠵᠢᠯᠡᠭᠰᠡᠨ ᠪᠠᠶᠢᠵᠤ ᠪᠣᠯᠬᠤ ᠶᠢ ᠰᠠᠨᠠᠭᠠᠯᠵᠠᠢ᠃',
        'ᠬᠡᠷᠪᠡ ᠠᠵᠢᠯ ᠣᠯᠠᠨ ᠵᠢᠯ ᠳᠦ ᠬᠤᠪᠢᠶᠠᠭᠳᠠᠭᠰᠠᠨ ᠪᠣᠯ᠂ ᠨᠢᠭᠡ ᠤᠳᠠᠭ᠎ᠠ ᠳᠤ ᠬᠡᠳᠦᠨ ᠬᠦᠮᠦᠨ ᠪᠠ ᠠᠳᠤᠭᠤ ᠴᠤᠭᠯᠠᠬᠤ ᠱᠠᠭᠠᠷᠳᠠᠯᠭ᠎ᠠ ᠲᠠᠢ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠲᠣᠭᠠᠴᠠᠭ᠎ᠠ ᠥᠭᠡᠷᠡ ᠪᠣᠯᠣᠨ᠎ᠠ᠃ ᠰᠤᠳᠤᠯᠤᠭᠴᠢᠳ ᠣᠷᠣᠨ ᠤ ᠨᠥᠭᠡᠴᠡ ᠬᠦᠷᠦᠯᠴᠡᠬᠦ ᠪᠣᠯᠣᠮᠵᠢ ᠶᠢ ᠲᠠᠶᠢᠯᠪᠤᠷᠢᠯᠠᠵᠠᠢ᠃ ᠡᠨᠡ ᠪᠣᠯ ᠨᠢᠭᠡ ᠴᠣᠭᠴᠠᠯᠪᠤᠷᠢ ᠶᠢᠨ ᠣᠨ ᠴᠠᠭ ᠲᠤ ᠲᠦᠰᠢᠭᠯᠡᠭᠰᠡᠨ ᠲᠠᠢᠯᠪᠤᠷᠢ᠂ ᠪᠦᠬᠦ ᠬᠢᠷᠭᠢᠰᠦᠭᠦᠷ ᠦᠨ ᠨᠡᠶᠢᠲᠡ ᠳᠦᠷᠢᠮ ᠪᠢᠰᠢ᠃',
      ],
