      title: 'ᠪᠠᠷᠠᠭᠤᠨ ᠬᠦᠷᠢᠶ᠎ᠡ ᠶᠢᠨ ᠡᠷᠲᠡᠨ ᠦ ᠱᠠᠪᠠᠷ ᠰᠠᠪᠠ',
      summary:
        'ᠭᠣᠪᠢ ᠶᠢᠨ ᠡᠷᠲᠡᠨ ᠦ ᠨᠠᠭᠤᠷ ᠤᠨ ᠡᠷᠭᠢ ᠶᠢᠨ ᠭᠠᠯ ᠤᠨ ᠣᠷᠣᠮ ᠰᠠᠪᠠᠨ ᠤ ᠬᠡᠷᠡᠭᠯᠡᠭᠡ ᠶᠢ ᠣᠨ ᠴᠠᠭ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠳᠠᠭ᠃',
      body: [
        '᠒᠐᠒᠕ ᠣᠨ ᠤ ᠰᠤᠳᠤᠯᠭ᠎ᠠ ᠪᠠᠷᠠᠭᠤᠨ ᠬᠦᠷᠢᠶ᠎ᠡ ᠭᠡᠳᠡᠭ ᠡᠷᠲᠡᠨ ᠦ ᠨᠠᠭᠤᠷ ᠤᠨ ᠡᠷᠭᠢ ᠶᠢᠨ ᠪᠠᠭᠤᠷᠢ ᠶᠢ ᠰᠤᠳᠤᠯᠵᠠᠢ᠃ ᠮᠣᠳᠣᠨ ᠤ ᠨᠡᠭᠦᠷᠡᠰᠦ ᠪᠠ ᠱᠠᠲᠠᠭᠰᠠᠨ ᠤᠷᠭᠤᠮᠠᠯ ᠤᠨ ᠦᠯᠡᠳᠡᠯ ᠳᠦ ᠠᠷᠪᠠᠨ ᠨᠢᠭᠡᠨ ᠨᠡᠭᠦᠷᠡᠰᠦᠲᠥ᠋ᠷᠥᠭᠴᠢ ᠶᠢᠨ ᠬᠡᠮᠵᠢᠯᠲᠡ ᠬᠢᠵᠦ᠂ ᠪᠠᠷᠤᠭ ᠠᠷᠪᠠᠨ ᠨᠢᠭᠡᠨ ᠮᠢᠩᠭᠠᠨ ᠵᠢᠯ ᠦᠨ ᠡᠮᠦᠨᠡᠬᠢ ᠦᠢᠯᠡ ᠠᠵᠢᠯᠯᠠᠭᠠᠨ ᠤ ᠣᠨ ᠴᠠᠭ ᠢ ᠲᠣᠭᠲᠠᠭᠠᠵᠠᠢ᠃',
        'ᠲᠡᠨᠳᠡ ᠱᠠᠪᠠᠷ ᠰᠠᠪᠠᠨ ᠤ ᠬᠡᠰᠡᠭ᠂ ᠪᠠᠭ᠎ᠠ ᠴᠢᠯᠠᠭᠤᠨ ᠢᠯᠲᠡᠰᠦ ᠬᠢᠬᠦ ᠴᠥᠮ᠎ᠡ ᠪᠠ ᠶᠠᠰᠤ ᠣᠯᠳᠠᠵᠠᠢ᠃ ᠡᠳᠡᠭᠡᠷ ᠢ ᠭᠠᠯ ᠤᠨ ᠣᠷᠣᠮ ᠲᠠᠢ ᠬᠣᠯᠪᠣᠨ ᠰᠤᠳᠤᠯᠬᠤ ᠨᠢ ᠡᠷᠲᠡᠨ ᠦ ᠨᠡᠭᠦᠳᠡᠯᠲᠡᠢ ᠠᠩᠴᠢᠳ ᠤᠨ ᠲᠧᠬᠨᠢᠺ ᠢ ᠣᠶᠢᠯᠠᠭᠠᠬᠤ ᠳᠤ ᠲᠤᠰᠠᠯᠠᠵᠠᠢ᠃ ᠰᠠᠪᠠ ᠪᠠᠶᠢᠬᠤ ᠨᠢ ᠳᠠᠩᠭᠠᠷ ᠢᠶᠠᠨ ᠲᠠᠷᠢᠶ᠎ᠠ ᠲᠠᠷᠢᠳᠠᠭ ᠪᠤᠶᠤ ᠵᠢᠯ ᠦᠨ ᠲᠤᠷᠰᠢ ᠰᠠᠭᠤᠳᠠᠭ ᠲᠣᠰᠬᠣᠨ ᠪᠠᠶᠢᠭᠰᠠᠨ ᠢ ᠪᠠᠲᠠᠯᠠᠬᠤ ᠦᠭᠡᠢ᠃',
      ],
